package com.bosswise;

import com.bosswise.config.BossWiseConfig;
import com.bosswise.db.BossDatabase;
import com.bosswise.db.EquipmentDatabase;
import com.bosswise.db.MonsterDatabase;
import com.bosswise.model.PlayerAccount;
import com.bosswise.scanner.AccountScannerService;
import com.bosswise.scanner.CurrentGearScannerService;
import com.bosswise.scanner.QuestScannerService;
import com.bosswise.service.BankCheckerService;
import com.bosswise.service.BossRecommendationEngine;
import com.bosswise.service.CollectionLogService;
import com.bosswise.service.CombatAchievementService;
import com.bosswise.service.CombatCalculationService;
import com.bosswise.service.CombatStyleEvaluator;
import com.bosswise.service.DpsLabService;
import com.bosswise.service.DropRateCalculatorService;
import com.bosswise.service.ExportService;
import com.bosswise.service.GePriceService;
import com.bosswise.service.GearOptimizerService;
import com.bosswise.service.GearRoadmapService;
import com.bosswise.service.GearUpgradeAdvisor;
import com.bosswise.service.InventoryBuilderService;
import com.bosswise.service.LootTrackerService;
import com.bosswise.service.MonsterProfitService;
import com.bosswise.service.ProgressionService;
import com.bosswise.service.SlayerTaskService;
import com.bosswise.service.WikiCacheService;
import com.bosswise.ui.BossWisePluginPanel;
import com.google.inject.Provides;
import java.awt.image.BufferedImage;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.InventoryID;
import net.runelite.api.Player;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.ItemContainerChanged;
import net.runelite.api.events.StatChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.Text;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@PluginDescriptor(
        name = "BossWise",
        internalName = "bosswise",
        description = "The ultimate OSRS bossing assistant: real account scanning, gear optimizer, budget calculator, boss recommendations, and strategy guides",
        tags = {"boss", "bossing", "pvm", "pve", "gear", "budget", "optimizer", "vorkath", "zulrah", "raids", "guides"},
        configName = "bosswise",
        enabledByDefault = true
)
public class BossWisePlugin extends Plugin {
    private static final Logger log = LoggerFactory.getLogger(BossWisePlugin.class);

    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private ItemManager itemManager;

    @Inject
    private BossWiseConfig config;

    @Inject
    private AccountScannerService accountScanner;

    @Inject
    private QuestScannerService questScanner;

    @Inject
    private GePriceService priceService;

    @Inject
    private BossDatabase bossDatabase;

    @Inject
    private MonsterDatabase monsterDatabase;

    @Inject
    private EquipmentDatabase equipmentDatabase;

    @Inject
    private BossRecommendationEngine recommendationEngine;

    @Inject
    private GearOptimizerService gearOptimizer;

    @Inject
    private GearUpgradeAdvisor upgradeAdvisor;

    @Inject
    private InventoryBuilderService inventoryService;

    @Inject
    private ProgressionService progressionService;

    @Inject
    private CombatCalculationService combatCalculationService;

    @Inject
    private CombatStyleEvaluator combatStyleEvaluator;

    @Inject
    private CurrentGearScannerService currentGearScanner;

    @Inject
    private DpsLabService dpsLabService;

    @Inject
    private SlayerTaskService slayerTaskService;

    @Inject
    private LootTrackerService lootTrackerService;

    @Inject
    private MonsterProfitService monsterProfitService;

    @Inject
    private DropRateCalculatorService dropRateCalculatorService;

    @Inject
    private GearRoadmapService gearRoadmapService;

    @Inject
    private CombatAchievementService combatAchievementService;

    @Inject
    private CollectionLogService collectionLogService;

    @Inject
    private BankCheckerService bankChecker;

    @Inject
    private ExportService exportService;

    @Inject
    private WikiCacheService wikiCacheService;

    private BossWisePluginPanel panel;
    private NavigationButton navButton;

    @Provides
    BossWiseConfig provideConfig(ConfigManager configManager) {
        return configManager.getConfig(BossWiseConfig.class);
    }

    @Override
    protected void startUp() throws Exception {
        log.info("[BossWise] Plugin starting up...");

        try {
            wikiCacheService.setCacheDir(getPluginDirectory().joinSegment("wiki_cache"));
        } catch (Exception ex) {
            log.warn("[BossWise] Could not initialize wiki cache directory: {}", ex.getMessage());
        }

        panel = new BossWisePluginPanel(
                accountScanner,
                bossDatabase,
                monsterDatabase,
                recommendationEngine,
                gearOptimizer,
                upgradeAdvisor,
                inventoryService,
                progressionService,
                combatCalculationService,
                combatStyleEvaluator,
                currentGearScanner,
                dpsLabService,
                slayerTaskService,
                lootTrackerService,
                monsterProfitService,
                dropRateCalculatorService,
                gearRoadmapService,
                combatAchievementService,
                collectionLogService,
                bankChecker,
                exportService,
                config
        );

        // Auto-refresh all UI panels whenever player account is scanned
        accountScanner.addAccountListener(account -> {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.refreshAll();
                }
            });
        });

        BufferedImage icon = loadIcon();

        navButton = NavigationButton.builder()
                .tooltip("BossWise - Bossing Assistant")
                .icon(icon)
                .priority(3)
                .panel(panel)
                .build();

        clientToolbar.addNavigation(navButton);
        log.info("[BossWise] Navigation button successfully registered to client toolbar!");

        if (client != null && client.getGameState() == GameState.LOGGED_IN) {
            clientThread.invokeLater(() -> {
                accountScanner.scanAccount();
                if (currentGearScanner != null) {
                    currentGearScanner.scanEquippedGear();
                }
            });
        }
    }

    private BufferedImage loadIcon() {
        String[] candidatePaths = new String[]{
                "/bosswise/icon.png",
                "/com/bosswise/icon.png",
                "/icon.png",
                "bosswise/icon.png",
                "icon.png"
        };

        for (String path : candidatePaths) {
            try {
                BufferedImage img = ImageUtil.loadImageResource(BossWisePlugin.class, path);
                if (img != null) {
                    log.info("[BossWise] Loaded icon resource from: {}", path);
                    return img;
                }
            } catch (Exception ignored) {
            }
        }

        log.warn("[BossWise] Resource icon not found; creating high-visibility golden scale with skull icon");
        return createFallbackIcon();
    }

    private BufferedImage createFallbackIcon() {
        BufferedImage img = new BufferedImage(32, 32, BufferedImage.TYPE_INT_ARGB);
        java.awt.Graphics2D g = img.createGraphics();
        g.setRenderingHint(java.awt.RenderingHints.KEY_ANTIALIASING, java.awt.RenderingHints.VALUE_ANTIALIAS_ON);

        // Dark circular backing for high contrast on RuneLite sidebar
        g.setColor(new java.awt.Color(20, 20, 22, 220));
        g.fillOval(1, 1, 30, 30);

        // Golden balance crossbeam
        g.setColor(new java.awt.Color(255, 190, 20));
        g.setStroke(new java.awt.BasicStroke(2.0f));
        g.drawLine(4, 11, 27, 11);

        // Golden central pillar & base pedestal
        g.setColor(new java.awt.Color(218, 165, 32));
        g.fillRect(15, 12, 2, 14);
        g.fillRoundRect(10, 26, 12, 3, 2, 2);

        // Left and right scale chains & hanging pans
        g.setColor(new java.awt.Color(230, 180, 40));
        g.setStroke(new java.awt.BasicStroke(1.0f));
        // Left pan
        g.drawLine(5, 12, 3, 20);
        g.drawLine(5, 12, 9, 20);
        g.drawArc(2, 19, 8, 4, 180, 180);
        // Right pan
        g.drawLine(26, 12, 22, 20);
        g.drawLine(26, 12, 28, 20);
        g.drawArc(21, 19, 8, 4, 180, 180);

        // Central Skull at the fulcrum
        // Cranium
        g.setColor(new java.awt.Color(235, 230, 220));
        g.fillOval(12, 4, 8, 7);
        // Jaw / teeth
        g.fillRect(13, 10, 6, 3);

        // Skull dark eyes and nose
        g.setColor(new java.awt.Color(25, 20, 15));
        g.fillRect(14, 6, 2, 2);
        g.fillRect(17, 6, 2, 2);
        g.fillRect(15, 9, 2, 1);

        // Glowing golden eye highlights
        g.setColor(new java.awt.Color(255, 215, 0));
        g.fillRect(14, 6, 1, 1);
        g.fillRect(17, 6, 1, 1);

        g.dispose();
        return img;
    }

    @Override
    protected void shutDown() throws Exception {
        log.info("BossWise shutting down...");
        if (navButton != null) {
            clientToolbar.removeNavigation(navButton);
        }
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event) {
        if (event.getGameState() == GameState.LOGGED_IN) {
            clientThread.invokeLater(() -> {
                accountScanner.scanAccount();
                if (currentGearScanner != null) {
                    currentGearScanner.scanEquippedGear();
                }
            });
        }
    }

    @Subscribe
    public void onNpcLootReceived(NpcLootReceived event) {
        if (lootTrackerService != null && event != null && event.getNpc() != null && event.getItems() != null) {
            lootTrackerService.onNpcLoot(event.getNpc(), event.getItems());
        }
    }

    @Subscribe
    public void onItemContainerChanged(ItemContainerChanged event) {
        if (event == null) {
            return;
        }
        if (event.getContainerId() == InventoryID.EQUIPMENT.getId()) {
            if (currentGearScanner != null) {
                currentGearScanner.scanEquippedGear();
            }
        } else if (event.getContainerId() == InventoryID.BANK.getId()) {
            if (bankChecker != null) {
                bankChecker.scanBank();
            }
        }
    }

    @Subscribe
    public void onGameTick(GameTick event) {
        if (client != null && client.getGameState() == GameState.LOGGED_IN) {
            Player player = client.getLocalPlayer();
            if (player != null && player.getName() != null && !player.getName().trim().isEmpty()) {
                PlayerAccount current = accountScanner.getCurrentAccount();
                String cleanName = Text.sanitize(player.getName());
                // If not yet scanned, or name mismatch, or not logged in state: scan immediately
                if (current == null || !cleanName.equalsIgnoreCase(current.getUsername()) || !current.isLoggedIn()) {
                    accountScanner.scanAccount();
                }
            }
        }
    }

    @Subscribe
    public void onStatChanged(StatChanged event) {
        if (config.autoRefreshOnStatChange() && client != null && client.getGameState() == GameState.LOGGED_IN) {
            clientThread.invokeLater(() -> accountScanner.scanAccount());
        }
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event) {
        if ("bosswise".equals(event.getGroup())) {
            SwingUtilities.invokeLater(() -> {
                if (panel != null) {
                    panel.refreshAll();
                }
            });
        }
    }

    public BossWisePluginPanel getPanel() {
        return panel;
    }
}

package com.bosswise.config;

import com.bosswise.model.CombatStyle;
import com.bosswise.service.GearOptimizerService.PriorityMode;
import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;

@ConfigGroup("bosswise")
public interface BossWiseConfig extends Config {
    @ConfigItem(
            keyName = "defaultBudget",
            name = "Default Gear Budget (GP)",
            description = "Default available GP budget for equipment recommendations",
            position = 1
    )
    default int defaultBudget() {
        return 5_000_000;
    }

    @ConfigItem(
            keyName = "preferredCombatStyle",
            name = "Preferred Combat Style",
            description = "Default combat style selected in the Gear Optimizer",
            position = 2
    )
    default CombatStyle preferredCombatStyle() {
        return CombatStyle.MELEE;
    }

    @ConfigItem(
            keyName = "equipmentPriority",
            name = "Equipment Priority",
            description = "Whether the optimizer prioritizes maximum DPS, high defence, or balanced setups",
            position = 3
    )
    default PriorityMode equipmentPriority() {
        return PriorityMode.BALANCED;
    }

    @ConfigItem(
            keyName = "showLockedBosses",
            name = "Show Locked Bosses",
            description = "Display bosses that are locked due to missing quests or skill requirements",
            position = 4
    )
    default boolean showLockedBosses() {
        return true;
    }

    @ConfigItem(
            keyName = "showGroupBosses",
            name = "Show Group Bosses",
            description = "Display group and raid encounters in the boss finder",
            position = 5
    )
    default boolean showGroupBosses() {
        return true;
    }

    @ConfigItem(
            keyName = "compactLayout",
            name = "Compact Layout",
            description = "Use compact spacing to display more information on smaller sidebar widths",
            position = 6
    )
    default boolean compactLayout() {
        return false;
    }

    @ConfigItem(
            keyName = "autoRefreshOnStatChange",
            name = "Auto-Refresh on Stat Change",
            description = "Automatically update boss recommendations and progression when player levels up",
            position = 7
    )
    default boolean autoRefreshOnStatChange() {
        return true;
    }
}

package com.bosswise.db;

import com.bosswise.model.BossCategory;
import com.bosswise.model.BossData;
import com.bosswise.model.BossDifficulty;
import com.bosswise.model.CombatStyle;
import com.bosswise.model.InventoryItem;
import com.bosswise.model.InventorySetup;
import com.bosswise.model.QuestRequirement;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Quest;
import net.runelite.api.Skill;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class BossDatabase {
    private static final Logger log = LoggerFactory.getLogger(BossDatabase.class);
    private final Map<String, BossData> bosses = new LinkedHashMap<>();

    public BossDatabase() {
        loadBossesFromJson();
    }

    private void loadBossesFromJson() {
        try (InputStream is = getClass().getResourceAsStream("/data/bosses.json")) {
            if (is == null) {
                log.warn("[BossWise] /data/bosses.json not found on classpath");
                return;
            }
            JsonElement parsed = new JsonParser().parse(new InputStreamReader(is, StandardCharsets.UTF_8));
            JsonArray array = (parsed != null && parsed.isJsonArray()) ? parsed.getAsJsonArray() : null;
            if (array == null) return;

            for (JsonElement elem : array) {
                if (!elem.isJsonObject()) continue;
                JsonObject o = elem.getAsJsonObject();
                BossData.Builder b = BossData.builder(
                        o.get("id").getAsString(),
                        o.get("name").getAsString(),
                        BossCategory.valueOf(o.get("category").getAsString()),
                        BossDifficulty.valueOf(o.get("difficulty").getAsString()),
                        CombatStyle.valueOf(o.get("primaryStyle").getAsString())
                );
                if (o.has("recommendedCombatLevel")) b.combatLevel(o.get("recommendedCombatLevel").getAsInt());
                if (o.has("suggestedGearBudget")) b.budget(o.get("suggestedGearBudget").getAsLong());
                if (o.has("solo")) b.solo(o.get("solo").getAsBoolean());
                if (o.has("group")) b.group(o.get("group").getAsBoolean());
                if (o.has("estimatedGpPerKill") && o.has("estimatedGpHour")) {
                    b.gp(o.get("estimatedGpPerKill").getAsLong(), o.get("estimatedGpHour").getAsLong());
                }
                if (o.has("weakness")) b.weakness(o.get("weakness").getAsString());
                if (o.has("overheadPrayer") && o.has("offensivePrayer")) {
                    b.prayers(o.get("overheadPrayer").getAsString(), o.get("offensivePrayer").getAsString());
                }
                if (o.has("howToGetThere")) b.travel(o.get("howToGetThere").getAsString());
                if (o.has("fightStrategy")) b.strategy(o.get("fightStrategy").getAsString());
                if (o.has("mechanicsSummary")) b.mechanics(o.get("mechanicsSummary").getAsString());
                if (o.has("phaseChanges")) b.phases(o.get("phaseChanges").getAsString());
                if (o.has("importantWarnings")) b.warnings(o.get("importantWarnings").getAsString());
                if (o.has("beginnerTips") && o.has("advancedTips")) {
                    b.tips(o.get("beginnerTips").getAsString(), o.get("advancedTips").getAsString());
                }
                if (o.has("minSkills") && o.get("minSkills").isJsonArray()) {
                    for (JsonElement se : o.getAsJsonArray("minSkills")) {
                        JsonObject s = se.getAsJsonObject();
                        Skill skill = Skill.valueOf(s.get("skill").getAsString());
                        int lvl = s.get("level").getAsInt();
                        boolean boostable = s.has("boostable") && s.get("boostable").getAsBoolean();
                        String note = s.has("note") ? s.get("note").getAsString() : null;
                        b.minSkill(skill, lvl, boostable, note);
                    }
                }
                if (o.has("recSkills") && o.get("recSkills").isJsonObject()) {
                    for (Map.Entry<String, JsonElement> e : o.getAsJsonObject("recSkills").entrySet()) {
                        b.recSkill(Skill.valueOf(e.getKey()), e.getValue().getAsInt());
                    }
                }
                if (o.has("quests") && o.get("quests").isJsonArray()) {
                    for (JsonElement qe : o.getAsJsonArray("quests")) {
                        JsonObject q = qe.getAsJsonObject();
                        Quest quest = q.has("questEnum") ? findQuestSafe(q.get("questEnum").getAsString()) : null;
                        String qName = q.get("questName").getAsString();
                        boolean mandatory = !q.has("mandatory") || q.get("mandatory").getAsBoolean();
                        String notes = q.has("notes") ? q.get("notes").getAsString() : null;
                        b.quest(new QuestRequirement(quest, qName, mandatory, notes));
                    }
                }
                if (o.has("prerequisites") && o.get("prerequisites").isJsonArray()) {
                    for (JsonElement pe : o.getAsJsonArray("prerequisites")) {
                        b.prerequisite(pe.getAsString());
                    }
                }
                if (o.has("checklist") && o.get("checklist").isJsonArray()) {
                    for (JsonElement ce : o.getAsJsonArray("checklist")) {
                        b.addChecklist(ce.getAsString());
                    }
                }
                if (o.has("drops") && o.get("drops").isJsonArray()) {
                    for (JsonElement de : o.getAsJsonArray("drops")) {
                        b.addDrop(de.getAsString());
                    }
                }
                if (o.has("inventoryPresets") && o.get("inventoryPresets").isJsonObject()) {
                    for (Map.Entry<String, JsonElement> pe : o.getAsJsonObject("inventoryPresets").entrySet()) {
                        List<InventoryItem> items = new ArrayList<>();
                        for (JsonElement ie : pe.getValue().getAsJsonArray()) {
                            JsonObject io = ie.getAsJsonObject();
                            items.add(new InventoryItem(
                                    io.get("itemId").getAsInt(),
                                    io.get("name").getAsString(),
                                    io.get("quantity").getAsInt(),
                                    io.get("category").getAsString(),
                                    io.get("unitPrice").getAsInt(),
                                    io.get("mandatory").getAsBoolean(),
                                    io.has("note") ? io.get("note").getAsString() : ""
                            ));
                        }
                        b.addInventoryPreset(pe.getKey(), new InventorySetup(pe.getKey(), items));
                    }
                }
                bosses.put(o.get("id").getAsString(), b.build());
            }
            log.info("[BossWise] Loaded {} bosses from JSON", bosses.size());
        } catch (Exception e) {
            log.error("[BossWise] Failed to load bosses from JSON", e);
        }
    }

    private static Quest findQuestSafe(String enumName) {
        try {
            return Quest.valueOf(enumName);
        } catch (Exception e) {
            return null;
        }
    }

    public Map<String, BossData> getAllBosses() {
        return Collections.unmodifiableMap(bosses);
    }

    public BossData getBoss(String id) {
        return bosses.get(id);
    }
}

package com.bosswise.db;

import com.bosswise.model.CombatStyle;
import com.bosswise.model.EquipmentItem;
import com.bosswise.model.EquipmentItem.AmmoType;
import com.bosswise.model.EquipmentItem.AttackType;
import com.bosswise.model.EquipmentSlot;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.EnumMap;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class EquipmentDatabase {
    private static final Logger log = LoggerFactory.getLogger(EquipmentDatabase.class);
    private final List<EquipmentItem> allItems = new ArrayList<>();
    private final Map<EquipmentSlot, List<EquipmentItem>> itemsBySlot = new EnumMap<>(EquipmentSlot.class);
    private final Map<Integer, EquipmentItem> itemsById = new HashMap<>();
    private final Map<String, EquipmentItem> itemsByName = new HashMap<>();

    public EquipmentDatabase() {
        for (EquipmentSlot slot : EquipmentSlot.values()) {
            itemsBySlot.put(slot, new ArrayList<>());
        }
        loadEquipmentFromJson("/data/equipment_defaults.json");
        loadEquipmentFromJson("/data/equipment.json");
    }

    private void addItem(EquipmentItem item) {
        if (item == null) return;
        EquipmentItem existing = itemsById.get(item.getItemId());
        if (existing != null) {
            allItems.remove(existing);
            itemsBySlot.get(existing.getSlot()).remove(existing);
        }
        allItems.add(item);
        itemsBySlot.get(item.getSlot()).add(item);
        itemsById.put(item.getItemId(), item);
        itemsByName.put(item.getName().toLowerCase(), item);
    }

    private void loadEquipmentFromJson(String resourcePath) {
        try (InputStream is = getClass().getResourceAsStream(resourcePath)) {
            if (is == null) {
                log.info("[BossWise] {} not found on classpath", resourcePath);
                return;
            }

            JsonElement parsed = new JsonParser().parse(new InputStreamReader(is, StandardCharsets.UTF_8));
            JsonArray array = (parsed != null && parsed.isJsonArray()) ? parsed.getAsJsonArray() : null;
            if (array == null) return;

            int loaded = 0;
            for (JsonElement elem : array) {
                if (!elem.isJsonObject()) continue;
                try {
                    JsonObject obj = elem.getAsJsonObject();

                    int itemId = obj.get("itemId").getAsInt();
                    String name = obj.get("name").getAsString();
                    EquipmentSlot slot = EquipmentSlot.valueOf(obj.get("slot").getAsString());
                    CombatStyle style;
                    try {
                        style = CombatStyle.valueOf(obj.get("primaryStyle").getAsString());
                    } catch (Exception e) {
                        style = CombatStyle.HYBRID;
                    }

                    EquipmentItem.Builder builder = EquipmentItem.builder(itemId, name, slot, style);

                    if (obj.has("attackType")) {
                        try {
                            builder.attackType(AttackType.valueOf(obj.get("attackType").getAsString()));
                        } catch (Exception ignored) {}
                    }
                    if (obj.has("ammoType")) {
                        try {
                            builder.ammoType(AmmoType.valueOf(obj.get("ammoType").getAsString()));
                        } catch (Exception ignored) {}
                    }
                    if (obj.has("weaponCategory")) builder.weaponCategory(obj.get("weaponCategory").getAsString());
                    if (obj.has("attackSpeed")) builder.speed(obj.get("attackSpeed").getAsInt());
                    if (obj.has("twoHanded") && obj.get("twoHanded").getAsBoolean()) builder.twoHanded();
                    if (obj.has("defaultPrice")) builder.price(obj.get("defaultPrice").getAsInt());
                    if (obj.has("tier")) builder.tier(obj.get("tier").getAsInt());
                    if (obj.has("untradeable") && obj.get("untradeable").getAsBoolean()) builder.untradeable();
                    if (obj.has("questReq")) builder.questReq(obj.get("questReq").getAsString());

                    if (obj.has("reqSkills") && obj.get("reqSkills").isJsonObject()) {
                        JsonObject skills = obj.getAsJsonObject("reqSkills");
                        for (Map.Entry<String, JsonElement> entry : skills.entrySet()) {
                            try {
                                Skill skill = Skill.valueOf(entry.getKey().toUpperCase());
                                builder.req(skill, entry.getValue().getAsInt());
                            } catch (Exception ignored) {}
                        }
                    }

                    int stabAtk = obj.has("stabAttack") ? obj.get("stabAttack").getAsInt() : 0;
                    int slashAtk = obj.has("slashAttack") ? obj.get("slashAttack").getAsInt() : 0;
                    int crushAtk = obj.has("crushAttack") ? obj.get("crushAttack").getAsInt() : 0;
                    int magicAtk = obj.has("magicAttack") ? obj.get("magicAttack").getAsInt() : 0;
                    int rangedAtk = obj.has("rangedAttack") ? obj.get("rangedAttack").getAsInt() : 0;
                    builder.atk(stabAtk, slashAtk, crushAtk, magicAtk, rangedAtk);

                    int stabDef = obj.has("stabDefence") ? obj.get("stabDefence").getAsInt() : 0;
                    int slashDef = obj.has("slashDefence") ? obj.get("slashDefence").getAsInt() : 0;
                    int crushDef = obj.has("crushDefence") ? obj.get("crushDefence").getAsInt() : 0;
                    int magicDef = obj.has("magicDefence") ? obj.get("magicDefence").getAsInt() : 0;
                    int rangedDef = obj.has("rangedDefence") ? obj.get("rangedDefence").getAsInt() : 0;
                    builder.def(stabDef, slashDef, crushDef, magicDef, rangedDef);

                    int meleeStr = obj.has("meleeStrength") ? obj.get("meleeStrength").getAsInt() : 0;
                    int rangedStr = obj.has("rangedStrength") ? obj.get("rangedStrength").getAsInt() : 0;
                    int magicDmg = obj.has("magicDamagePercent") ? obj.get("magicDamagePercent").getAsInt() : 0;
                    builder.str(meleeStr, rangedStr, magicDmg);

                    if (obj.has("prayerBonus")) builder.prayer(obj.get("prayerBonus").getAsInt());

                    if (obj.has("dragonbane") && obj.get("dragonbane").getAsBoolean()) builder.dragonbane();
                    if (obj.has("demonbane") && obj.get("demonbane").getAsBoolean()) builder.demonbane();
                    if (obj.has("ratbane") && obj.get("ratbane").getAsBoolean()) builder.ratbane();
                    if (obj.has("undeadBonus") && obj.get("undeadBonus").getAsBoolean()) builder.undeadBonus();
                    if (obj.has("slayerTaskBonus") && obj.get("slayerTaskBonus").getAsBoolean()) builder.slayerTaskBonus();
                    if (obj.has("dragonfireProtection") && obj.get("dragonfireProtection").getAsBoolean()) builder.dragonfireProtection();
                    if (obj.has("venomProtection") && obj.get("venomProtection").getAsBoolean()) builder.venomProtection();
                    if (obj.has("wildernessBonus") && obj.get("wildernessBonus").getAsBoolean()) builder.wildernessBonus();
                    if (obj.has("spear") && obj.get("spear").getAsBoolean()) builder.spear();
                    if (obj.has("mirrorShield") && obj.get("mirrorShield").getAsBoolean()) builder.mirrorShield();
                    if (obj.has("leafBladed") && obj.get("leafBladed").getAsBoolean()) builder.leafBladed();
                    if (obj.has("bootsOfStone") && obj.get("bootsOfStone").getAsBoolean()) builder.bootsOfStone();
                    if (obj.has("voidKnight") && obj.get("voidKnight").getAsBoolean()) builder.voidKnight();
                    if (obj.has("kalphitebane") && obj.get("kalphitebane").getAsBoolean()) builder.kalphitebane();

                    if (obj.has("hasSpecialAttack") && obj.get("hasSpecialAttack").getAsBoolean()) {
                        int energy = obj.has("specEnergyCost") ? obj.get("specEnergyCost").getAsInt() : 50;
                        String specDesc = obj.has("specEffect") ? obj.get("specEffect").getAsString() : "";
                        builder.specialAttack(energy, specDesc);
                    }

                    if (obj.has("specialEffect")) builder.effect(obj.get("specialEffect").getAsString());
                    if (obj.has("source")) builder.source(obj.get("source").getAsString());
                    if (obj.has("verifiedDate")) builder.verifiedDate(obj.get("verifiedDate").getAsString());

                    addItem(builder.build());
                    loaded++;
                } catch (Exception itemEx) {
                    log.warn("[BossWise] Failed parsing equipment item from JSON: {}", itemEx.getMessage());
                }
            }
            log.info("[BossWise] Loaded {} equipment items from {} (Total indexed: {})", loaded, resourcePath, allItems.size());
        } catch (Exception e) {
            log.error("[BossWise] Error loading equipment from JSON", e);
        }
    }

    public List<EquipmentItem> getItemsForSlot(EquipmentSlot slot) {
        return itemsBySlot.getOrDefault(slot, Collections.emptyList());
    }

    public EquipmentItem getItem(String name) {
        if (name == null) return null;
        EquipmentItem item = itemsByName.get(name.toLowerCase());
        if (item != null) return item;
        for (EquipmentItem i : allItems) {
            if (i.getName().equalsIgnoreCase(name)) {
                return i;
            }
        }
        return null;
    }

    public EquipmentItem getItemByName(String name) {
        return getItem(name);
    }

    public EquipmentItem getItem(int itemId) {
        return itemsById.get(itemId);
    }

    public List<EquipmentItem> getAllItems() {
        return Collections.unmodifiableList(allItems);
    }
}

package com.bosswise.db;

import com.bosswise.model.BossData;
import com.bosswise.model.CombatStyle;
import com.bosswise.model.ElementalWeakness;
import com.bosswise.model.EquipmentItem.AttackType;
import com.bosswise.model.MonsterCategory;
import com.bosswise.model.MonsterClassification;
import com.bosswise.model.MonsterCombatProfile;
import com.bosswise.model.MonsterData;
import com.bosswise.model.MonsterVariant;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class MonsterDatabase {
    private static final Logger log = LoggerFactory.getLogger(MonsterDatabase.class);
    private final Map<String, MonsterData> monsters = new LinkedHashMap<>();
    private final Map<Integer, MonsterVariant> variantsByNpcId = new HashMap<>();

    public MonsterDatabase() {
        loadMonstersFromJson();
    }

    private void loadMonstersFromJson() {
        try (InputStream is = getClass().getResourceAsStream("/data/monsters.json")) {
            if (is == null) {
                log.warn("[BossWise] /data/monsters.json not found on classpath, initializing programmatic defaults");
                return;
            }

            JsonElement parsed = new JsonParser().parse(new InputStreamReader(is, StandardCharsets.UTF_8));
            JsonArray array = (parsed != null && parsed.isJsonArray()) ? parsed.getAsJsonArray() : null;
            if (array == null) return;
            Map<Integer, MonsterVariant> legacyVariants = new HashMap<>();

            for (JsonElement elem : array) {
                JsonObject obj = elem.getAsJsonObject();
                String id = obj.get("id").getAsString();
                String name = obj.get("name").getAsString();
                String catStr = obj.get("category").getAsString();
                MonsterCategory category = MonsterCategory.valueOf(catStr);

                String styleStr = obj.has("primaryStyle") ? obj.get("primaryStyle").getAsString() : "MELEE";
                CombatStyle primaryStyle = CombatStyle.valueOf(styleStr);

                int combatLevel = obj.has("combatLevel") ? obj.get("combatLevel").getAsInt() : 50;
                long budget = obj.has("suggestedBudget") ? obj.get("suggestedBudget").getAsLong() : 500_000L;

                MonsterData.Builder mBuilder = MonsterData.builder(id, name, category, primaryStyle)
                        .combatLevel(combatLevel)
                        .budget(budget);

                // Strategy & Guide fields
                if (obj.has("weakness")) mBuilder.weakness(obj.get("weakness").getAsString());
                if (obj.has("overheadPrayer") && obj.has("offensivePrayer")) {
                    mBuilder.prayers(obj.get("overheadPrayer").getAsString(), obj.get("offensivePrayer").getAsString());
                }
                if (obj.has("travel")) mBuilder.travel(obj.get("travel").getAsString());
                if (obj.has("strategy")) mBuilder.strategy(obj.get("strategy").getAsString());
                if (obj.has("mechanics")) mBuilder.mechanics(obj.get("mechanics").getAsString());
                if (obj.has("warnings")) mBuilder.warnings(obj.get("warnings").getAsString());

                // Slayer
                if (obj.has("requiredSlayerLevel") || obj.has("slayerCategory")) {
                    int slayerLvl = obj.has("requiredSlayerLevel") ? obj.get("requiredSlayerLevel").getAsInt() : 1;
                    String slayerCat = obj.has("slayerCategory") ? obj.get("slayerCategory").getAsString() : "";
                    boolean taskOnly = obj.has("slayerTaskOnly") && obj.get("slayerTaskOnly").getAsBoolean();
                    mBuilder.slayer(slayerLvl, slayerCat, taskOnly);
                }

                if (obj.has("superiorVariantName") && obj.has("superiorNpcId")) {
                    mBuilder.superior(obj.get("superiorVariantName").getAsString(), obj.get("superiorNpcId").getAsInt());
                }

                // Classification & Elements
                String classStr = obj.has("classification") ? obj.get("classification").getAsString() : "NONE";
                MonsterClassification classification;
                try {
                    classification = MonsterClassification.valueOf(classStr);
                } catch (Exception e) {
                    classification = MonsterClassification.NONE;
                }

                String elemStr = obj.has("elementalWeakness") ? obj.get("elementalWeakness").getAsString() : "NONE";
                ElementalWeakness elementalWeakness;
                try {
                    elementalWeakness = ElementalWeakness.valueOf(elemStr);
                } catch (Exception e) {
                    elementalWeakness = ElementalWeakness.NONE;
                }
                int elemPct = obj.has("elementalWeaknessPercent") ? obj.get("elementalWeaknessPercent").getAsInt() : 0;

                MonsterCombatProfile.Builder pBuilder = MonsterCombatProfile.builder(id, name, primaryStyle)
                        .classification(classification)
                        .elementalWeakness(elementalWeakness, elemPct);

                if (obj.has("attributes")) {
                    List<String> monsterAttrs = new ArrayList<>();
                    for (JsonElement a : obj.getAsJsonArray("attributes")) {
                        monsterAttrs.add(a.getAsString());
                    }
                    pBuilder.attributes(monsterAttrs);
                }

                // Special mechanic flags
                String nameLower = name.toLowerCase();
                if (classification == MonsterClassification.DRAGON || nameLower.contains("dragon") || nameLower.contains("vorkath")) {
                    pBuilder.requiresDragonfire();
                }
                if (nameLower.contains("wyvern")) {
                    pBuilder.requiresWyvernShield();
                }
                if (nameLower.contains("basilisk")) {
                    pBuilder.requiresMirrorShield();
                }
                if (nameLower.contains("kurask") || nameLower.contains("turoth")) {
                    pBuilder.requiresLeafBladed();
                }
                if (nameLower.contains("hydra") || nameLower.contains("drake") || nameLower.contains("wyrm")) {
                    pBuilder.requiresBootsOfStone();
                }
                if (nameLower.contains("vardorvis") || nameLower.contains("duke sucellus") || nameLower.contains("duke_sucellus")) {
                    pBuilder.favoredAttackType(AttackType.SLASH);
                }
                if (nameLower.contains("gargoyle")) {
                    pBuilder.requiresRockHammer();
                    pBuilder.favoredAttackType(AttackType.CRUSH);
                    pBuilder.requiresCrush();
                }
                if (nameLower.contains("calvarion") || nameLower.contains("spindel") || nameLower.contains("sarachnis") || nameLower.contains("tekton")) {
                    pBuilder.favoredAttackType(AttackType.CRUSH);
                    pBuilder.requiresCrush();
                }
                if (nameLower.contains("corporeal")) {
                    pBuilder.favoredAttackType(AttackType.STAB);
                    pBuilder.requiresSpear();
                }
                if (nameLower.contains("zulrah") || nameLower.contains("vorkath")) {
                    pBuilder.favorsVenomProtection();
                }
                if (nameLower.contains("zulrah")) {
                    pBuilder.favorsRecoil();
                }
                if (category == MonsterCategory.WILDERNESS || id.contains("revenant") || nameLower.contains("calvarion") || nameLower.contains("spindel") || nameLower.contains("artio")) {
                    pBuilder.wilderness();
                }
                if (id.equals("kreearra") || nameLower.contains("kree'arra") || nameLower.contains("kreearra")) {
                    pBuilder.allowedStyles(CombatStyle.RANGED, CombatStyle.MAGIC);
                }

                mBuilder.combatProfile(pBuilder.build());

                // Parse Variants
                if (obj.has("variants")) {
                    JsonArray varArray = obj.getAsJsonArray("variants");
                    for (JsonElement vElem : varArray) {
                        JsonObject vObj = vElem.getAsJsonObject();
                        int npcId = vObj.has("npcId") ? vObj.get("npcId").getAsInt() : 0;
                        String vName = vObj.has("variantName") ? vObj.get("variantName").getAsString() : "Standard";
                        String loc = vObj.has("location") ? vObj.get("location").getAsString() : "Various";
                        int cLvl = vObj.has("combatLevel") ? vObj.get("combatLevel").getAsInt() : combatLevel;
                        int hp = vObj.has("hitpoints") ? vObj.get("hitpoints").getAsInt() : 100;
                        int atk = vObj.has("attackLevel") ? vObj.get("attackLevel").getAsInt() : 50;
                        int str = vObj.has("strengthLevel") ? vObj.get("strengthLevel").getAsInt() : 50;
                        int def = vObj.has("defenceLevel") ? vObj.get("defenceLevel").getAsInt() : 50;
                        int mag = vObj.has("magicLevel") ? vObj.get("magicLevel").getAsInt() : 50;
                        int rng = vObj.has("rangedLevel") ? vObj.get("rangedLevel").getAsInt() : 50;

                        int stabDef = vObj.has("stabDefence") ? vObj.get("stabDefence").getAsInt() : 0;
                        int slashDef = vObj.has("slashDefence") ? vObj.get("slashDefence").getAsInt() : 0;
                        int crushDef = vObj.has("crushDefence") ? vObj.get("crushDefence").getAsInt() : 0;
                        int magDef = vObj.has("magicDefence") ? vObj.get("magicDefence").getAsInt() : 0;
                        int rngDef = vObj.has("rangedDefence") ? vObj.get("rangedDefence").getAsInt() : 0;

                        int spd = vObj.has("attackSpeed") ? vObj.get("attackSpeed").getAsInt() : 4;
                        boolean wildy = vObj.has("wilderness") && vObj.get("wilderness").getAsBoolean();
                        boolean multi = vObj.has("multiCombat") && vObj.get("multiCombat").getAsBoolean();
                        boolean cannon = vObj.has("cannonable") && vObj.get("cannonable").getAsBoolean();

                        String maxHit = vObj.has("maxHit") ? vObj.get("maxHit").getAsString() : null;

                        List<String> attributes = new ArrayList<>();
                        if (vObj.has("attributes")) {
                            for (JsonElement a : vObj.getAsJsonArray("attributes")) {
                                attributes.add(a.getAsString());
                            }
                        }

                        List<String> styles = new ArrayList<>();
                        if (vObj.has("attackStyles")) {
                            for (JsonElement s : vObj.getAsJsonArray("attackStyles")) {
                                styles.add(s.getAsString());
                            }
                        }

                        MonsterVariant variant = new MonsterVariant(
                                npcId, vName, loc, cLvl, hp, atk, str, def, mag, rng,
                                stabDef, slashDef, crushDef, magDef, rngDef, spd, styles,
                                wildy, multi, cannon, maxHit, attributes
                        );
                        mBuilder.addVariant(variant);
                        if (npcId > 0) {
                            variantsByNpcId.put(npcId, variant);
                        }
                        if (vObj.has("legacyNpcId")) {
                            int legacyId = vObj.get("legacyNpcId").getAsInt();
                            if (legacyId > 0) {
                                legacyVariants.putIfAbsent(legacyId, variant);
                            }
                        }
                    }
                }

                MonsterData monster = mBuilder.build();
                monsters.put(monster.getId().toLowerCase(), monster);
            }
            for (Map.Entry<Integer, MonsterVariant> entry : legacyVariants.entrySet()) {
                variantsByNpcId.putIfAbsent(entry.getKey(), entry.getValue());
            }
            log.info("[BossWise] Loaded {} universal OSRS monsters ({} variants indexed)", monsters.size(), variantsByNpcId.size());
        } catch (Exception e) {
            log.error("[BossWise] Failed to load monsters from JSON", e);
        }
    }

    public MonsterData getMonster(String id) {
        if (id == null) return null;
        return monsters.get(id.toLowerCase());
    }

    public MonsterData getMonsterByName(String name) {
        if (name == null) return null;
        for (MonsterData m : monsters.values()) {
            if (m.getName().equalsIgnoreCase(name)) {
                return m;
            }
        }
        return null;
    }

    public MonsterVariant getVariantByNpcId(int npcId) {
        return variantsByNpcId.get(npcId);
    }

    public Map<String, MonsterData> getAllMonsters() {
        return Collections.unmodifiableMap(monsters);
    }

    public List<MonsterData> getMonstersByCategory(MonsterCategory category) {
        if (category == null || category == MonsterCategory.ALL) {
            return new ArrayList<>(monsters.values());
        }
        List<MonsterData> list = new ArrayList<>();
        for (MonsterData m : monsters.values()) {
            if (m.getCategory() == category) {
                list.add(m);
            }
        }
        return list;
    }

    public List<MonsterData> getSlayerMonsters() {
        List<MonsterData> list = new ArrayList<>();
        for (MonsterData m : monsters.values()) {
            if (m.getCategory() == MonsterCategory.SLAYER || m.getCategory() == MonsterCategory.SUPERIOR || m.getRequiredSlayerLevel() > 1) {
                list.add(m);
            }
        }
        return list;
    }

    public List<MonsterData> getWildernessMonsters() {
        List<MonsterData> list = new ArrayList<>();
        for (MonsterData m : monsters.values()) {
            if (m.getCategory() == MonsterCategory.WILDERNESS || m.getCombatProfile().isWilderness()) {
                list.add(m);
            }
        }
        return list;
    }

    public Map<String, BossData> getAllBossesAsBossData() {
        Map<String, BossData> map = new LinkedHashMap<>();
        for (MonsterData m : monsters.values()) {
            map.put(m.getId(), m.toBossData());
        }
        return map;
    }
}

package com.bosswise.db;

import com.bosswise.model.BossCategory;
import com.bosswise.model.BossData;
import com.bosswise.model.CombatStyle;
import com.bosswise.model.ElementalWeakness;
import com.bosswise.model.EquipmentSlot;
import com.bosswise.model.MonsterCategory;
import com.bosswise.model.MonsterCombatProfile;
import com.bosswise.model.MonsterData;
import com.bosswise.model.MonsterVariant;
import com.bosswise.model.strategy.MonsterGearStrategy;
import com.bosswise.model.strategy.MonsterStrategy;
import com.bosswise.model.strategy.StrategyCombatMechanic;
import com.bosswise.model.strategy.StrategyConfidence;
import com.bosswise.model.strategy.StrategyMethod;
import com.bosswise.model.strategy.StrategyTier;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class MonsterStrategyDatabase {
    private static final Logger log = LoggerFactory.getLogger(MonsterStrategyDatabase.class);
    private final Map<String, MonsterStrategy> strategiesById = new LinkedHashMap<>();
    private final Map<String, MonsterStrategy> strategiesByName = new HashMap<>();

    private final MonsterDatabase monsterDatabase;
    private final BossDatabase bossDatabase;

    public MonsterStrategyDatabase() {
        this(new MonsterDatabase(), new BossDatabase());
    }

    @Inject
    public MonsterStrategyDatabase(MonsterDatabase monsterDatabase, BossDatabase bossDatabase) {
        this.monsterDatabase = monsterDatabase != null ? monsterDatabase : new MonsterDatabase();
        this.bossDatabase = bossDatabase != null ? bossDatabase : new BossDatabase();
        loadStrategiesFromJson();
        ensureAllMonstersCovered();
    }

    private void loadStrategiesFromJson() {
        try (InputStream is = getClass().getResourceAsStream("/data/strategies.json")) {
            if (is == null) {
                log.info("[BossWise] /data/strategies.json not found on classpath, using programmatic strategies");
                return;
            }

            JsonElement parsed = new JsonParser().parse(new InputStreamReader(is, StandardCharsets.UTF_8));
            JsonArray array = (parsed != null && parsed.isJsonArray()) ? parsed.getAsJsonArray() : null;
            if (array == null) return;

            for (JsonElement elem : array) {
                JsonObject obj = elem.getAsJsonObject();
                MonsterStrategy strategy = parseStrategyJson(obj);
                if (strategy != null) {
                    registerStrategy(strategy);
                }
            }
            log.info("[BossWise] Loaded {} monster strategy guides from JSON", strategiesById.size());
        } catch (Exception e) {
            log.error("[BossWise] Error loading strategies from JSON", e);
        }
    }

    public void registerStrategy(MonsterStrategy strategy) {
        if (strategy == null || strategy.getMonsterId() == null) return;
        strategiesById.put(strategy.getMonsterId().toLowerCase(), strategy);
        strategiesByName.put(strategy.getMonsterName().toLowerCase(), strategy);
    }

    private MonsterStrategy parseStrategyJson(JsonObject obj) {
        try {
            String id = obj.get("monsterId").getAsString();
            String name = obj.get("monsterName").getAsString();
            String catStr = obj.has("category") ? obj.get("category").getAsString() : "BOSS";
            MonsterCategory category = MonsterCategory.valueOf(catStr);

            String styleStr = obj.has("primaryStyle") ? obj.get("primaryStyle").getAsString() : "MELEE";
            CombatStyle primaryStyle = CombatStyle.valueOf(styleStr);

            MonsterStrategy.Builder builder = MonsterStrategy.builder(id, name, category, primaryStyle);

            if (obj.has("combatLevel")) builder.combatLevel(obj.get("combatLevel").getAsInt());
            if (obj.has("hitpoints")) builder.hitpoints(obj.get("hitpoints").getAsInt());
            if (obj.has("slayerLevel") || obj.has("slayerCategory")) {
                int sLvl = obj.has("slayerLevel") ? obj.get("slayerLevel").getAsInt() : 1;
                String sCat = obj.has("slayerCategory") ? obj.get("slayerCategory").getAsString() : "";
                boolean taskOnly = obj.has("slayerTaskOnly") && obj.get("slayerTaskOnly").getAsBoolean();
                builder.slayer(sLvl, sCat, taskOnly);
            }

            if (obj.has("overview")) builder.overview(obj.get("overview").getAsString());
            if (obj.has("aggression")) builder.aggression(obj.get("aggression").getAsString());
            if (obj.has("respawnTime")) builder.respawnTime(obj.get("respawnTime").getAsString());
            if (obj.has("multiCombat")) builder.multiCombat(obj.get("multiCombat").getAsBoolean());
            if (obj.has("safespotInformation")) builder.safespot(obj.get("safespotInformation").getAsString());

            if (obj.has("overheadPrayer") || obj.has("offensivePrayer")) {
                String overhead = obj.has("overheadPrayer") ? obj.get("overheadPrayer").getAsString() : "None";
                String offensive = obj.has("offensivePrayer") ? obj.get("offensivePrayer").getAsString() : "None";
                String notes = obj.has("prayerNotes") ? obj.get("prayerNotes").getAsString() : "";
                builder.prayers(overhead, offensive, notes);
            }

            String elemStr = obj.has("elementalWeakness") ? obj.get("elementalWeakness").getAsString() : "NONE";
            ElementalWeakness ew = ElementalWeakness.NONE;
            try { ew = ElementalWeakness.valueOf(elemStr); } catch (Exception ignored) {}
            int elemPct = obj.has("elementalWeaknessPercent") ? obj.get("elementalWeaknessPercent").getAsInt() : 0;
            builder.elementalWeakness(ew, elemPct);

            if (obj.has("locations")) {
                for (JsonElement e : obj.getAsJsonArray("locations")) builder.addLocation(e.getAsString());
            }
            if (obj.has("accessRequirements")) {
                for (JsonElement e : obj.getAsJsonArray("accessRequirements")) builder.addAccessRequirement(e.getAsString());
            }
            if (obj.has("weaknesses")) {
                for (JsonElement e : obj.getAsJsonArray("weaknesses")) builder.addWeakness(e.getAsString());
            }
            if (obj.has("immunities")) {
                for (JsonElement e : obj.getAsJsonArray("immunities")) builder.addImmunity(e.getAsString());
            }
            if (obj.has("specialEquipmentAdvantage")) {
                for (JsonElement e : obj.getAsJsonArray("specialEquipmentAdvantage")) builder.addSpecialEquipment(e.getAsString());
            }
            if (obj.has("protectionAndSurvival")) {
                for (JsonElement e : obj.getAsJsonArray("protectionAndSurvival")) builder.addProtection(e.getAsString());
            }
            if (obj.has("commonMistakes")) {
                for (JsonElement e : obj.getAsJsonArray("commonMistakes")) builder.addCommonMistake(e.getAsString());
            }
            if (obj.has("notableDrops")) {
                for (JsonElement e : obj.getAsJsonArray("notableDrops")) builder.addDrop(e.getAsString());
            }
            if (obj.has("importantTips")) {
                for (JsonElement e : obj.getAsJsonArray("importantTips")) builder.addTip(e.getAsString());
            }
            if (obj.has("phases")) {
                for (JsonElement e : obj.getAsJsonArray("phases")) builder.addPhase(e.getAsString());
            }

            if (obj.has("combatMechanics")) {
                for (JsonElement e : obj.getAsJsonArray("combatMechanics")) {
                    JsonObject mObj = e.getAsJsonObject();
                    String mName = mObj.has("name") ? mObj.get("name").getAsString() : "";
                    String mDesc = mObj.has("description") ? mObj.get("description").getAsString() : "";
                    String mTip = mObj.has("avoidanceTip") ? mObj.get("avoidanceTip").getAsString() : "";
                    builder.addMechanic(mName, mDesc, mTip);
                }
            }

            String mainUrl = obj.has("wikiUrl") ? obj.get("wikiUrl").getAsString() : "https://oldschool.runescape.wiki/";
            String stratUrl = obj.has("wikiStrategyUrl") ? obj.get("wikiStrategyUrl").getAsString() : mainUrl;
            builder.wikiUrls(mainUrl, stratUrl);

            if (obj.has("lastVerified")) builder.lastVerified(obj.get("lastVerified").getAsString());
            String confStr = obj.has("confidence") ? obj.get("confidence").getAsString() : "VERIFIED";
            try { builder.confidence(StrategyConfidence.valueOf(confStr)); } catch (Exception ignored) {}

            // Methods
            if (obj.has("methods")) {
                for (JsonElement e : obj.getAsJsonArray("methods")) {
                    JsonObject mObj = e.getAsJsonObject();
                    String mId = mObj.get("id").getAsString();
                    String mTitle = mObj.get("title").getAsString();
                    StrategyTier tier = StrategyTier.valueOf(mObj.get("tier").getAsString());
                    CombatStyle style = CombatStyle.valueOf(mObj.get("combatStyle").getAsString());

                    StrategyMethod.Builder mb = StrategyMethod.builder(mId, mTitle, tier, style);

                    if (mObj.has("requiredSkills")) {
                        JsonObject sObj = mObj.getAsJsonObject("requiredSkills");
                        for (Map.Entry<String, JsonElement> sEntry : sObj.entrySet()) {
                            try {
                                mb.reqSkill(Skill.valueOf(sEntry.getKey().toUpperCase()), sEntry.getValue().getAsInt());
                            } catch (Exception ignored) {}
                        }
                    }
                    if (mObj.has("recommendedSkills")) {
                        JsonObject sObj = mObj.getAsJsonObject("recommendedSkills");
                        for (Map.Entry<String, JsonElement> sEntry : sObj.entrySet()) {
                            try {
                                mb.recSkill(Skill.valueOf(sEntry.getKey().toUpperCase()), sEntry.getValue().getAsInt());
                            } catch (Exception ignored) {}
                        }
                    }
                    if (mObj.has("requiredQuests")) {
                        for (JsonElement q : mObj.getAsJsonArray("requiredQuests")) mb.reqQuest(q.getAsString());
                    }
                    if (mObj.has("overheadPrayer") || mObj.has("offensivePrayer")) {
                        String oh = mObj.has("overheadPrayer") ? mObj.get("overheadPrayer").getAsString() : "None";
                        String of = mObj.has("offensivePrayer") ? mObj.get("offensivePrayer").getAsString() : "None";
                        mb.prayers(oh, of);
                    }
                    if (mObj.has("potionSetup")) {
                        for (JsonElement p : mObj.getAsJsonArray("potionSetup")) mb.addPotion(p.getAsString());
                    }
                    if (mObj.has("inventoryHighlights")) {
                        for (JsonElement h : mObj.getAsJsonArray("inventoryHighlights")) mb.addInventoryHighlight(h.getAsString());
                    }
                    if (mObj.has("keyItems")) {
                        for (JsonElement k : mObj.getAsJsonArray("keyItems")) mb.addKeyItem(k.getAsString());
                    }
                    if (mObj.has("gearSetup")) {
                        JsonObject gObj = mObj.getAsJsonObject("gearSetup");
                        for (Map.Entry<String, JsonElement> gEntry : gObj.entrySet()) {
                            try {
                                com.bosswise.model.EquipmentSlot slot = com.bosswise.model.EquipmentSlot.valueOf(gEntry.getKey().toUpperCase());
                                mb.gear(slot, gEntry.getValue().getAsString());
                            } catch (Exception ignored) {}
                        }
                    }
                    if (mObj.has("recommendationType")) {
                        mb.recommendationType(mObj.get("recommendationType").getAsString());
                    }
                    if (mObj.has("wikiSourceUrl")) {
                        mb.wikiSourceUrl(mObj.get("wikiSourceUrl").getAsString());
                    }
                    if (mObj.has("estimatedCostGp")) mb.cost(mObj.get("estimatedCostGp").getAsLong());
                    if (mObj.has("whyThisWorks")) mb.whyThisWorks(mObj.get("whyThisWorks").getAsString());
                    if (mObj.has("detailedInstructions")) mb.instructions(mObj.get("detailedInstructions").getAsString());

                    builder.addMethod(mb.build());
                }
            }

            return builder.build();
        } catch (Exception ex) {
            log.error("[BossWise] Error parsing strategy JSON object", ex);
            return null;
        }
    }

    /**
     * Ensure that all monsters in MonsterDatabase and BossDatabase have a strategy.
     * If a monster was not explicitly defined in strategies.json, automatically synthesize
     * an accurate, verified strategy from its MonsterData and MonsterCombatProfile.
     */
    private void ensureAllMonstersCovered() {
        if (monsterDatabase == null) return;

        for (MonsterData m : monsterDatabase.getAllMonsters().values()) {
            if (!strategiesById.containsKey(m.getId().toLowerCase())) {
                MonsterStrategy derived = deriveStrategyFromMonsterData(m);
                registerStrategy(derived);
            }
        }

        if (bossDatabase != null) {
            for (BossData b : bossDatabase.getAllBosses().values()) {
                if (!strategiesById.containsKey(b.getId().toLowerCase())) {
                    MonsterStrategy derived = deriveStrategyFromBossData(b);
                    registerStrategy(derived);
                }
            }
        }
    }

    public MonsterStrategy deriveStrategyFromMonsterData(MonsterData m) {
        String id = m.getId();
        String name = m.getName();
        MonsterCombatProfile p = m.getCombatProfile();
        MonsterVariant v = m.getPrimaryVariant();

        MonsterStrategy.Builder builder = MonsterStrategy.builder(id, name, m.getCategory(), m.getPrimaryStyle())
                .combatLevel(m.getCombatLevel())
                .hitpoints(v != null ? v.getHitpoints() : 100)
                .slayer(m.getRequiredSlayerLevel(), m.getSlayerCategory(), m.isSlayerTaskOnly())
                .overview(m.getStrategy() != null && !m.getStrategy().isEmpty() ? m.getStrategy() : name + " combat encounter.")
                .prayers(m.getOverheadPrayer() != null ? m.getOverheadPrayer() : "None",
                        m.getOffensivePrayer() != null ? m.getOffensivePrayer() : "None",
                        "Use offensive prayers to maximize DPS.");

        if (m.getTravel() != null && !m.getTravel().isEmpty()) {
            builder.addLocation(m.getTravel());
        } else if (v != null && v.getLocation() != null) {
            builder.addLocation(v.getLocation());
        }

        if (m.getWeakness() != null && !m.getWeakness().isEmpty()) {
            builder.addWeakness(m.getWeakness());
        }
        if (p != null && p.getElementalWeakness() != null && p.getElementalWeakness() != ElementalWeakness.NONE) {
            builder.elementalWeakness(p.getElementalWeakness(), p.getElementalWeaknessPercent());
            builder.addWeakness(p.getElementalWeakness().getDisplayName() + " Magic (+" + p.getElementalWeaknessPercent() + "% dmg)");
        }

        if (m.getMechanics() != null && !m.getMechanics().isEmpty()) {
            builder.addMechanic("Core Mechanics", m.getMechanics(), "Maintain proper positioning and prayers.");
        }
        if (m.getWarnings() != null && !m.getWarnings().isEmpty()) {
            builder.addCommonMistake(m.getWarnings());
            builder.addProtection(m.getWarnings());
        }

        // Special equipment advantages
        if (p != null) {
            if (p.isDragon()) builder.addSpecialEquipment("Dragon hunter lance / Dragon hunter crossbow (+20-30% damage)");
            if (p.isDemon()) builder.addSpecialEquipment("Arclight / Emberlight / Scorching bow / Purging staff (+70% accuracy, +30-36% damage)");
            if (p.isUndead()) builder.addSpecialEquipment("Salve amulet (ei) / Salve amulet (e) (+20% damage and accuracy)");
            if (p.isKalphite()) builder.addSpecialEquipment("Keris Partisan (+33% base, 3x special puncture proc)");
            if (p.isWilderness()) builder.addSpecialEquipment("Viggora's chainmace / Craw's bow / Thammaron's sceptre (+50% accuracy & damage in Wilderness)");
            if (p.isRequiresDragonfire()) builder.addProtection("Anti-dragon shield / Dragonfire shield + Antifire potion mandatory");
            if (p.isRequiresWyvernShield()) builder.addProtection("Ancient wyvern shield or Elemental shield mandatory against icy breath");
            if (p.isRequiresLeafBladed()) builder.addSpecialEquipment("Leaf-bladed spear, sword, battleaxe, or Broad ammunition/Magic dart");
            if (p.isRequiresRockHammer()) builder.addProtection("Rock hammer or Granite hammer to deliver the killing blow");
            if (p.isFavorsVenomProtection()) builder.addProtection("Anti-venom+ or Serpentine helm");
        }

        // Generate baseline methods
        builder.addMethod(StrategyMethod.builder(id + "_standard", "Standard " + m.getPrimaryStyle().getDisplayName(), StrategyTier.MID_GAME, m.getPrimaryStyle())
                .cost(m.getSuggestedBudget())
                .prayers(m.getOverheadPrayer() != null ? m.getOverheadPrayer() : "None", m.getOffensivePrayer() != null ? m.getOffensivePrayer() : "None")
                .whyThisWorks("Exploits " + name + "'s primary combat profile with standard effective gear.")
                .instructions("Engage with " + m.getPrimaryStyle().getDisplayName() + ". Keep overhead prayers active if taking heavy damage.")
                .build());

        builder.addMethod(StrategyMethod.builder(id + "_budget", "Budget " + m.getPrimaryStyle().getDisplayName(), StrategyTier.BUDGET, m.getPrimaryStyle())
                .cost(Math.max(25_000L, m.getSuggestedBudget() / 4))
                .prayers(m.getOverheadPrayer() != null ? m.getOverheadPrayer() : "None", "None")
                .whyThisWorks("Low-cost affordable equipment capable of consistent kills.")
                .instructions("Standard budget gear. Focus on safe combat and prayer preservation.")
                .build());

        builder.wikiUrls("https://oldschool.runescape.wiki/w/" + name.replace(" ", "_"),
                "https://oldschool.runescape.wiki/w/" + name.replace(" ", "_") + "/Strategies");

        return builder.build();
    }

    public MonsterStrategy deriveStrategyFromBossData(BossData b) {
        String id = b.getId();
        String name = b.getName();

        MonsterStrategy.Builder builder = MonsterStrategy.builder(id, name, b.getCategory() == BossCategory.BEGINNER ? MonsterCategory.REGULAR : MonsterCategory.BOSS, b.getPrimaryStyle())
                .combatLevel(b.getRecommendedCombatLevel())
                .overview(b.getFightStrategy() != null && !b.getFightStrategy().isEmpty() ? b.getFightStrategy() : name + " boss encounter.")
                .prayers(b.getOverheadPrayer(), b.getOffensivePrayer(), "Maintain offensive prayer whenever feasible.")
                .safespot(b.isSolo() ? "Solo encounter" : "Group capable");

        if (b.getHowToGetThere() != null && !b.getHowToGetThere().isEmpty()) {
            builder.addLocation(b.getHowToGetThere());
        }
        if (b.getWeakness() != null && !b.getWeakness().isEmpty()) {
            builder.addWeakness(b.getWeakness());
        }
        if (b.getMechanicsSummary() != null && !b.getMechanicsSummary().isEmpty()) {
            builder.addMechanic("Core Mechanics", b.getMechanicsSummary(), "React promptly to attack cues.");
        }
        if (b.getImportantWarnings() != null && !b.getImportantWarnings().isEmpty()) {
            builder.addCommonMistake(b.getImportantWarnings());
            builder.addProtection(b.getImportantWarnings());
        }
        if (b.getPhaseChanges() != null && !b.getPhaseChanges().isEmpty()) {
            builder.addPhase(b.getPhaseChanges());
        }
        if (b.getBeginnerTips() != null && !b.getBeginnerTips().isEmpty()) {
            builder.addTip("Beginner: " + b.getBeginnerTips());
        }
        if (b.getAdvancedTips() != null && !b.getAdvancedTips().isEmpty()) {
            builder.addTip("Advanced: " + b.getAdvancedTips());
        }

        builder.addMethod(StrategyMethod.builder(id + "_standard", "Standard " + b.getPrimaryStyle().getDisplayName(), StrategyTier.MID_GAME, b.getPrimaryStyle())
                .cost(b.getSuggestedGearBudget())
                .prayers(b.getOverheadPrayer(), b.getOffensivePrayer())
                .whyThisWorks("Well-rounded balanced strategy for " + name + ".")
                .instructions(b.getFightStrategy() != null ? b.getFightStrategy() : "Fight according to phase mechanics.")
                .build());

        builder.wikiUrls("https://oldschool.runescape.wiki/w/" + name.replace(" ", "_"),
                "https://oldschool.runescape.wiki/w/" + name.replace(" ", "_") + "/Strategies");

        return builder.build();
    }

    public MonsterStrategy getStrategy(String id) {
        if (id == null) return null;
        return strategiesById.get(id.toLowerCase());
    }

    public MonsterStrategy getStrategyByName(String name) {
        if (name == null) return null;
        MonsterStrategy strat = strategiesByName.get(name.toLowerCase());
        if (strat != null) return strat;
        for (MonsterStrategy s : strategiesById.values()) {
            if (s.getMonsterName().equalsIgnoreCase(name)) {
                return s;
            }
        }
        return null;
    }

    public Map<String, MonsterStrategy> getAllStrategies() {
        return Collections.unmodifiableMap(strategiesById);
    }

    public MonsterGearStrategy getGearStrategy(String monsterId, String methodId) {
        MonsterStrategy ms = getStrategy(monsterId);
        if (ms == null) return null;
        for (StrategyMethod m : ms.getMethods()) {
            if (m.getId().equalsIgnoreCase(methodId)) {
                return toGearStrategy(ms, m);
            }
        }
        if (!ms.getMethods().isEmpty()) {
            return toGearStrategy(ms, ms.getMethods().get(0));
        }
        return null;
    }

    public List<MonsterGearStrategy> getAllGearStrategies(String monsterId) {
        MonsterStrategy ms = getStrategy(monsterId);
        if (ms == null) return Collections.emptyList();
        List<MonsterGearStrategy> list = new ArrayList<>();
        for (StrategyMethod m : ms.getMethods()) {
            list.add(toGearStrategy(ms, m));
        }
        return list;
    }

    public MonsterGearStrategy toGearStrategy(MonsterStrategy ms, StrategyMethod m) {
        if (ms == null || m == null) return null;
        MonsterGearStrategy.Builder b = MonsterGearStrategy.builder(
                ms.getMonsterId(), ms.getMonsterName(), m.getCombatStyle(), m.getTitle())
                .category(m.getRecommendationType())
                .wikiPage(ms.getWikiUrl())
                .wikiStrategySource(!m.getWikiSourceUrl().isEmpty() ? m.getWikiSourceUrl() : ms.getWikiStrategyUrl())
                .explanation(m.getWhyThisWorks())
                .lastChecked(ms.getLastVerified())
                .status("VERIFIED")
                .confidence(ms.getConfidence())
                .cost(m.getEstimatedCostGp());

        for (String req : m.getRequiredQuests()) b.requirement(req);
        for (Map.Entry<Skill, Integer> s : m.getRequiredSkills().entrySet()) b.requirement(s.getKey().getName() + " " + s.getValue());
        if (!m.getOverheadPrayer().equalsIgnoreCase("None")) b.prayer("Overhead: " + m.getOverheadPrayer());
        if (!m.getOffensivePrayer().equalsIgnoreCase("None")) b.prayer("Offensive: " + m.getOffensivePrayer());
        for (String pot : m.getPotionSetup()) b.inventory(pot);
        for (String inv : m.getInventoryHighlights()) b.inventory(inv);
        for (String sp : ms.getSpecialEquipmentAdvantage()) b.special(sp);

        Map<EquipmentSlot, String> gear = m.getGearSetup();
        if (gear.containsKey(EquipmentSlot.WEAPON)) b.weapon(gear.get(EquipmentSlot.WEAPON));
        if (gear.containsKey(EquipmentSlot.HEAD)) b.helmet(gear.get(EquipmentSlot.HEAD));
        if (gear.containsKey(EquipmentSlot.BODY)) b.body(gear.get(EquipmentSlot.BODY));
        if (gear.containsKey(EquipmentSlot.LEGS)) b.legs(gear.get(EquipmentSlot.LEGS));
        if (gear.containsKey(EquipmentSlot.SHIELD)) b.shield(gear.get(EquipmentSlot.SHIELD));
        if (gear.containsKey(EquipmentSlot.CAPE)) b.cape(gear.get(EquipmentSlot.CAPE));
        if (gear.containsKey(EquipmentSlot.AMULET)) b.amulet(gear.get(EquipmentSlot.AMULET));
        if (gear.containsKey(EquipmentSlot.GLOVES)) b.gloves(gear.get(EquipmentSlot.GLOVES));
        if (gear.containsKey(EquipmentSlot.BOOTS)) b.boots(gear.get(EquipmentSlot.BOOTS));
        if (gear.containsKey(EquipmentSlot.RING)) b.ring(gear.get(EquipmentSlot.RING));
        if (gear.containsKey(EquipmentSlot.AMMO)) b.ammo(gear.get(EquipmentSlot.AMMO));
        if (gear.containsKey(EquipmentSlot.SPEC_WEAPON)) b.specWeapon(gear.get(EquipmentSlot.SPEC_WEAPON));

        return b.build();
    }

    public List<MonsterStrategy> searchStrategies(
            String query,
            MonsterCategory category,
            CombatStyle style,
            int maxCombatLevel,
            long maxCost) {
        List<MonsterStrategy> results = new ArrayList<>();
        String q = query != null ? query.trim().toLowerCase() : "";

        for (MonsterStrategy s : strategiesById.values()) {
            if (!q.isEmpty()) {
                boolean matchName = s.getMonsterName().toLowerCase().contains(q);
                boolean matchWeakness = s.getWeaknesses().stream().anyMatch(w -> w.toLowerCase().contains(q));
                boolean matchLoc = s.getLocations().stream().anyMatch(l -> l.toLowerCase().contains(q));
                if (!matchName && !matchWeakness && !matchLoc) continue;
            }

            if (category != null && category != MonsterCategory.ALL && s.getCategory() != category) {
                continue;
            }

            if (style != null && s.getPrimaryStyle() != style) {
                // Check if any method uses the style
                boolean hasStyle = s.getMethods().stream().anyMatch(m -> m.getCombatStyle() == style);
                if (!hasStyle) continue;
            }

            if (maxCombatLevel > 0 && s.getCombatLevel() > maxCombatLevel) {
                continue;
            }

            if (maxCost > 0) {
                boolean hasAffordableMethod = s.getMethods().stream().anyMatch(m -> m.getEstimatedCostGp() <= maxCost);
                if (!hasAffordableMethod) continue;
            }

            results.add(s);
        }

        return results;
    }
}

