    private final Map<EquipmentSlot, EquipmentItem> currentGear;
    private final OptimizedGearSetup recommendedSetup;
    private final CombatResult currentCombat;
    private final CombatResult recommendedCombat;
    private final long currentGearValue;
    private final long recommendedGearValue;
    private final List<String> missingProtections;
    private final List<SlotUpgrade> slotUpgrades;

    public CurrentGearComparison(
            Map<EquipmentSlot, EquipmentItem> currentGear,
            OptimizedGearSetup recommendedSetup,
            CombatResult currentCombat,
            CombatResult recommendedCombat,
            long currentGearValue,
            long recommendedGearValue,
            List<String> missingProtections,
            List<SlotUpgrade> slotUpgrades) {
        this.currentGear = currentGear != null ? currentGear : Collections.emptyMap();
        this.recommendedSetup = recommendedSetup;
        this.currentCombat = currentCombat;
        this.recommendedCombat = recommendedCombat;
        this.currentGearValue = currentGearValue;
        this.recommendedGearValue = recommendedGearValue;
        this.missingProtections = missingProtections != null ? missingProtections : Collections.emptyList();
        this.slotUpgrades = slotUpgrades != null ? slotUpgrades : Collections.emptyList();
    }

    public Map<EquipmentSlot, EquipmentItem> getCurrentGear() { return currentGear; }
    public OptimizedGearSetup getRecommendedSetup() { return recommendedSetup; }
    public CombatResult getCurrentCombat() { return currentCombat; }
    public CombatResult getRecommendedCombat() { return recommendedCombat; }
    public long getCurrentGearValue() { return currentGearValue; }
    public long getRecommendedGearValue() { return recommendedGearValue; }
    public List<String> getMissingProtections() { return missingProtections; }
    public List<SlotUpgrade> getSlotUpgrades() { return slotUpgrades; }

    public double getDpsDifference() {
        if (currentCombat == null || recommendedCombat == null) return 0.0;
        return recommendedCombat.getDps() - currentCombat.getDps();
    }

    public double getDpsPercentageImprovement() {
        if (currentCombat == null || recommendedCombat == null || currentCombat.getDps() <= 0) return 0.0;
        return ((recommendedCombat.getDps() - currentCombat.getDps()) / currentCombat.getDps()) * 100.0;
    }

    public int getMaxHitDifference() {
        if (currentCombat == null || recommendedCombat == null) return 0;
        return recommendedCombat.getMaxHit() - currentCombat.getMaxHit();
    }

    public double getAccuracyDifference() {
        if (currentCombat == null || recommendedCombat == null) return 0.0;
        return (recommendedCombat.getHitChance() - currentCombat.getHitChance()) * 100.0;
    }

    public long getCostDifference() {
        return Math.max(0, recommendedGearValue - currentGearValue);
    }

    public static class SlotUpgrade {
        private final EquipmentSlot slot;
        private final EquipmentItem currentItem;
        private final EquipmentItem upgradeItem;
        private final long costDifference;
        private final String impactDescription;

        public SlotUpgrade(
                EquipmentSlot slot,
                EquipmentItem currentItem,
                EquipmentItem upgradeItem,
                long costDifference,
                String impactDescription) {
            this.slot = slot;
            this.currentItem = currentItem;
            this.upgradeItem = upgradeItem;
            this.costDifference = costDifference;
            this.impactDescription = impactDescription != null ? impactDescription : "";
        }

        public EquipmentSlot getSlot() { return slot; }
        public EquipmentItem getCurrentItem() { return currentItem; }
        public EquipmentItem getUpgradeItem() { return upgradeItem; }
        public long getCostDifference() { return costDifference; }
        public String getImpactDescription() { return impactDescription; }
    }
}

package com.bosswise.model;

public class DeathRiskProfile {
    private final String locationType;
    private final long gravestoneFee;
    private final long retrievalServiceFee;
    private final long estimatedSupplyLoss;
    private final boolean pvpDangerous;
    private final String explanation;

    public DeathRiskProfile(
            String locationType,
            long gravestoneFee,
            long retrievalServiceFee,
            long estimatedSupplyLoss,
            boolean pvpDangerous,
            String explanation) {
        this.locationType = locationType != null ? locationType : "Standard Overworld";
        this.gravestoneFee = gravestoneFee;
        this.retrievalServiceFee = retrievalServiceFee;
        this.estimatedSupplyLoss = estimatedSupplyLoss;
        this.pvpDangerous = pvpDangerous;
        this.explanation = explanation != null ? explanation : "";
    }

    public static DeathRiskProfile forMonster(String monsterName, boolean isWilderness, long gearValue) {
        String n = monsterName != null ? monsterName.toLowerCase() : "";
        if (isWilderness || n.contains("wilderness") || n.contains("callisto") || n.contains("vet'ion")
                || n.contains("venenatis") || n.contains("chaos elemental") || n.contains("artio")
                || n.contains("spindel") || n.contains("calvar'ion") || n.contains("revenant")) {
            long pvpLoss = Math.min(gearValue, 500_000L) + 50_000L; // untradeable repair fees + supplies
            return new DeathRiskProfile(
                    "Wilderness (Dangerous PvP)",
                    0L,
                    0L,
                    pvpLoss,
                    true,
                    "Items above 3 kept on death are converted to coins for the killer. Untradeables broken."
            );
        } else if (n.contains("vorkath") || n.contains("zulrah") || n.contains("phantom muspah")
                || n.contains("the whisperer") || n.contains("vardorvis") || n.contains("duke sucellus")
                || n.contains("the leviathan") || n.contains("hydra") || n.contains("nex")) {
            return new DeathRiskProfile(
                    "Item Retrieval Service",
                    0L,
                    100_000L,
                    35_000L,
                    false,
                    "Flat 100,000 GP reclaim fee collected by the retrieval NPC outside the encounter."
            );
        } else if (n.contains("theatre of blood") || n.contains("tombs of amascut")) {
            return new DeathRiskProfile(
                    "Raid Wipe Chest",
                    0L,
                    100_000L,
                    45_000L,
                    false,
                    "Party wipe fee paid to the chest to recover untradeables and equipment."
            );
        } else {
            // Standard gravestone mechanics: items over 10M = 100K fee, 1M-10M = 10K fee, 100K-1M = 1K fee. Cap 500K
            long fee = Math.min(500_000L, (long) (gearValue * 0.005));
            return new DeathRiskProfile(
                    "Standard Gravestone (15 Min)",
                    fee,
                    0L,
                    20_000L,
                    false,
                    "Gravestone spawns for 15 minutes. Items over 100k incur a tiered recovery fee capped at 500k."
            );
        }
    }

    public String getLocationType() { return locationType; }
    public long getGravestoneFee() { return gravestoneFee; }
    public long getRetrievalServiceFee() { return retrievalServiceFee; }
    public long getEstimatedSupplyLoss() { return estimatedSupplyLoss; }
    public boolean isPvpDangerous() { return pvpDangerous; }
    public String getExplanation() { return explanation; }

    public long getTotalEstimatedDeathCost() {
        return gravestoneFee + retrievalServiceFee + estimatedSupplyLoss;
    }

    public String getFormattedTotalCost() {
        long total = getTotalEstimatedDeathCost();
        if (total >= 1_000_000) {
            return String.format("%.1fM GP", total / 1_000_000.0);
        } else if (total >= 1_000) {
            return String.format("%dK GP", total / 1_000);
        }
        return total + " GP";
    }
}

package com.bosswise.model;

import java.util.Collections;
import java.util.Map;

public class DpsComparisonResult {
    private final String monsterName;
    private final CombatStyle combatStyle;
    private final SetupEvaluation setupA;
    private final SetupEvaluation setupB;

    public DpsComparisonResult(
            String monsterName,
            CombatStyle combatStyle,
            SetupEvaluation setupA,
            SetupEvaluation setupB) {
        this.monsterName = monsterName != null ? monsterName : "Target Monster";
        this.combatStyle = combatStyle != null ? combatStyle : CombatStyle.MELEE;
        this.setupA = setupA;
        this.setupB = setupB;
    }

    public String getMonsterName() { return monsterName; }
    public CombatStyle getCombatStyle() { return combatStyle; }
    public SetupEvaluation getSetupA() { return setupA; }
    public SetupEvaluation getSetupB() { return setupB; }

    public double getDpsDifference() {
        if (setupA == null || setupB == null) return 0.0;
        return setupB.getDps() - setupA.getDps();
    }

    public double getDpsPercentageImprovement() {
        if (setupA == null || setupB == null || setupA.getDps() <= 0) return 0.0;
        return ((setupB.getDps() - setupA.getDps()) / setupA.getDps()) * 100.0;
    }

    public int getMaxHitDifference() {
        if (setupA == null || setupB == null) return 0;
        return setupB.getMaxHit() - setupA.getMaxHit();
    }

    public double getAccuracyDifference() {
        if (setupA == null || setupB == null) return 0.0;
        return (setupB.getHitChance() - setupA.getHitChance()) * 100.0;
    }

    public long getCostDifference() {
        if (setupA == null || setupB == null) return 0L;
        return setupB.getTotalPrice() - setupA.getTotalPrice();
    }

    public double getDpsPerMillionGp() {
        long costDiff = getCostDifference();
        if (costDiff <= 0) return 0.0;
        double dpsDiff = getDpsDifference();
        return (dpsDiff / (double) costDiff) * 1_000_000.0;
    }

    public String getVerdict() {
        double dpsDiff = getDpsDifference();
        long costDiff = getCostDifference();
        if (dpsDiff > 0.05) {
            if (costDiff <= 0) {
                return String.format("Setup B is +%.2f DPS (+%.1f%%) stronger and saves %s GP!",
                        dpsDiff, getDpsPercentageImprovement(), formatGp(Math.abs(costDiff)));
            } else {
                return String.format("Setup B yields +%.2f DPS (+%.1f%%) for %s GP extra (%.3f DPS/M GP).",
                        dpsDiff, getDpsPercentageImprovement(), formatGp(costDiff), getDpsPerMillionGp());
            }
        } else if (dpsDiff < -0.05) {
            return String.format("Setup A outperforms Setup B by +%.2f DPS.", Math.abs(dpsDiff));
        } else {
            return "Both setups provide essentially identical combat damage output.";
        }
    }

    private static String formatGp(long amount) {
        if (amount >= 1_000_000) {
            return String.format("%.1fM", amount / 1_000_000.0);
        } else if (amount >= 1_000) {
            return String.format("%dK", amount / 1_000);
        }
        return amount + " GP";
    }

    public static class SetupEvaluation {
        private final String name;
        private final Map<EquipmentSlot, EquipmentItem> equipment;
        private final CombatResult combatResult;
        private final long totalPrice;

        public SetupEvaluation(
                String name,
                Map<EquipmentSlot, EquipmentItem> equipment,
                CombatResult combatResult,
                long totalPrice) {
            this.name = name;
            this.equipment = equipment != null ? equipment : Collections.emptyMap();
            this.combatResult = combatResult;
            this.totalPrice = totalPrice;
        }

        public String getName() { return name; }
        public Map<EquipmentSlot, EquipmentItem> getEquipment() { return equipment; }
        public CombatResult getCombatResult() { return combatResult; }
        public long getTotalPrice() { return totalPrice; }

        public double getDps() {
            return (combatResult != null) ? combatResult.getDps() : 0.0;
        }

        public int getMaxHit() {
            return (combatResult != null) ? combatResult.getMaxHit() : 0;
        }

        public double getHitChance() {
            return (combatResult != null) ? combatResult.getHitChance() : 0.0;
        }

        public double getAttacksPerSecond() {
            if (combatResult == null || combatResult.getAttackSpeedTicks() <= 0) return 0.417; // 4 ticks = 2.4s = 0.417/s
            return 1.0 / (combatResult.getAttackSpeedTicks() * 0.6);
        }

        public long getAttackRoll() {
            return (combatResult != null) ? combatResult.getAttackRoll() : 0L;
        }

        public long getDefenceRoll() {
            return (combatResult != null) ? combatResult.getDefenceRoll() : 0L;
        }
    }
}

package com.bosswise.model;

public class DropRateCalculation {
    private final String itemName;
    private final String monsterName;
    private final double baseProbability;
    private final int expectedKills;
    private final int medianKills;
    private final int ninetyPercentKills;
    private final int ninetyNinePercentKills;
    private final double chanceAt10;
    private final double chanceAt50;
    private final double chanceAt100;
    private final double chanceAt500;
    private final double chanceAt1000;
    private final int guaranteedThreshold; // e.g. 50 for Vorkath head, 256 for KQ head, -1 if none
    private final String specialMechanicDescription;

    public DropRateCalculation(
            String itemName,
            String monsterName,
            double baseProbability,
            int guaranteedThreshold,
            String specialMechanicDescription) {
        this.itemName = itemName != null ? itemName : "Unique Drop";
        this.monsterName = monsterName != null ? monsterName : "Boss";
        this.baseProbability = Math.max(0.0000001, Math.min(1.0, baseProbability));
        this.guaranteedThreshold = guaranteedThreshold;
        this.specialMechanicDescription = specialMechanicDescription != null ? specialMechanicDescription : "";

        this.expectedKills = (int) Math.round(1.0 / this.baseProbability);
        this.medianKills = (int) Math.ceil(Math.log(0.5) / Math.log(1.0 - this.baseProbability));
        this.ninetyPercentKills = (int) Math.ceil(Math.log(0.1) / Math.log(1.0 - this.baseProbability));
        this.ninetyNinePercentKills = (int) Math.ceil(Math.log(0.01) / Math.log(1.0 - this.baseProbability));

        this.chanceAt10 = calculateChanceAtKc(10);
        this.chanceAt50 = calculateChanceAtKc(50);
        this.chanceAt100 = calculateChanceAtKc(100);
        this.chanceAt500 = calculateChanceAtKc(500);
        this.chanceAt1000 = calculateChanceAtKc(1000);
    }

    public double calculateChanceAtKc(int kc) {
        if (kc <= 0) return 0.0;
        if (guaranteedThreshold > 0 && kc >= guaranteedThreshold) {
            return 1.0; // 100% pity guarantee
        }
        return 1.0 - Math.pow(1.0 - baseProbability, kc);
    }

    public double calculateDryChanceAtKc(int kc) {
        if (guaranteedThreshold > 0 && kc >= guaranteedThreshold) {
            return 0.0;
        }
        return Math.max(0.0, 1.0 - calculateChanceAtKc(kc));
    }

    public String getItemName() { return itemName; }
    public String getMonsterName() { return monsterName; }
    public double getBaseProbability() { return baseProbability; }
    public int getExpectedKills() { return expectedKills; }
    public int getMedianKills() { return medianKills; }
    public int getNinetyPercentKills() { return ninetyPercentKills; }
    public int getNinetyNinePercentKills() { return ninetyNinePercentKills; }
    public double getChanceAt10() { return chanceAt10; }
    public double getChanceAt50() { return chanceAt50; }
    public double getChanceAt100() { return chanceAt100; }
    public double getChanceAt500() { return chanceAt500; }
    public double getChanceAt1000() { return chanceAt1000; }
    public int getGuaranteedThreshold() { return guaranteedThreshold; }
    public String getSpecialMechanicDescription() { return specialMechanicDescription; }

    public String getFormattedFraction() {
        return "1 in " + expectedKills;
    }
}

