package com.bosswise.model;

import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

public class InventorySetup {
    private final String tierName;
    private final List<InventoryItem> items;

    public InventorySetup(String tierName, List<InventoryItem> items) {
        this.tierName = tierName;
        this.items = new ArrayList<>(items);
    }

    public String getTierName() { return tierName; }
    public List<InventoryItem> getItems() { return items; }

    public long getTotalCost() {
        long sum = 0;
        for (InventoryItem item : items) {
            sum += item.getTotalCost();
        }
        return sum;
    }

    public int getUsedSlots() {
        int slots = 0;
        for (InventoryItem item : items) {
            if (item.getQuantity() <= 0) continue;
            String cat = item.getCategory() != null ? item.getCategory().toLowerCase() : "";
            String name = item.getName() != null ? item.getName().toLowerCase() : "";

            // Stackable categories: Rune, Ammo, Teleport tab, Rune pouch
            boolean isStackable = cat.contains("rune") || cat.contains("ammo") || name.contains("tab")
                    || name.contains("pouch") || name.contains("scroll") || name.contains("coins");

            if (isStackable) {
                slots += 1;
            } else {
                slots += item.getQuantity();
            }
        }
        return slots;
    }

    public boolean isValid() {
        return getUsedSlots() <= 28;
    }

    public int getRemainingSlots() {
        return Math.max(0, 28 - getUsedSlots());
    }

    public int getTotalHealAmount() {
        int total = 0;
        for (InventoryItem item : items) {
            String name = item.getName() != null ? item.getName().toLowerCase() : "";
            int qty = item.getQuantity();
            if (name.contains("anglerfish")) total += qty * 22;
            else if (name.contains("manta ray")) total += qty * 22;
            else if (name.contains("shark")) total += qty * 20;
            else if (name.contains("karambwan")) total += qty * 18;
            else if (name.contains("monkfish")) total += qty * 16;
            else if (name.contains("lobster")) total += qty * 12;
            else if (name.contains("saradomin brew")) total += qty * (16 * 4); // 4 doses
            else if (item.getCategory() != null && item.getCategory().equalsIgnoreCase("Food")) {
                total += qty * 16;
            }
        }
        return total;
    }

    public int getTotalPrayerRestore() {
        int total = 0;
        for (InventoryItem item : items) {
            String name = item.getName() != null ? item.getName().toLowerCase() : "";
            int qty = item.getQuantity();
            if (name.contains("prayer potion") || name.contains("super restore")) {
                total += qty * (31 * 4); // 4 doses @ 31 points avg
            } else if (name.contains("sanfew")) {
                total += qty * (31 * 4);
            }
        }
        return total;
    }

    public TripMetrics calculateTripMetrics(int bossHp, double playerDps, int bossMaxHit) {
        int slots = getUsedSlots();
        boolean valid = slots <= 28;
        long supplyCost = getTotalCost();

        double safeDps = Math.max(0.5, playerDps);
        int killTimeSeconds = (int) Math.ceil(bossHp / safeDps) + 15; // 15s transit/spawn delay
        if (killTimeSeconds <= 0) killTimeSeconds = 60;

        int totalHeal = getTotalHealAmount();
        int estimatedIncomingDamagePerKill = Math.min(totalHeal, Math.max(10, (int) (bossMaxHit * 1.5)));
        int killsByFood = (estimatedIncomingDamagePerKill > 0) ? Math.max(1, totalHeal / estimatedIncomingDamagePerKill) : 5;

        int totalPray = getTotalPrayerRestore();
        int prayerDrainPerKill = Math.max(5, (killTimeSeconds / 60) * 15); // ~15 prayer pts per minute
        int killsByPrayer = (prayerDrainPerKill > 0 && totalPray > 0) ? Math.max(1, totalPray / prayerDrainPerKill) : killsByFood;

        int estimatedKills = Math.min(killsByFood, killsByPrayer);
        if (estimatedKills > 30) estimatedKills = 30; // realistic cap per inventory trip
        if (estimatedKills <= 0) estimatedKills = 1;

        int totalTripSeconds = (estimatedKills * killTimeSeconds) + 120; // 2 min banking
        int tripDurationMinutes = (int) Math.ceil(totalTripSeconds / 60.0);

        long costPerKill = (estimatedKills > 0) ? (supplyCost / estimatedKills) : supplyCost;
        int ammoConsumed = (int) (killTimeSeconds * estimatedKills * 0.4); // approx shots

        return new TripMetrics(
                estimatedKills,
                tripDurationMinutes,
                supplyCost,
                costPerKill,
                totalHeal,
                totalPray,
                ammoConsumed,
                slots,
                valid
        );
    }
}

package com.bosswise.model;

public class LootDropItem {
    public enum DropRarity {
        UNIQUE("Unique", "#FF9800"),
        RARE("Rare", "#9C27B0"),
        VALUABLE("Valuable", "#4CAF50"),
        COMMON("Common", "#B0BEC5");

        private final String label;
        private final String hexColor;

        DropRarity(String label, String hexColor) {
            this.label = label;
            this.hexColor = hexColor;
        }

        public String getLabel() { return label; }
        public String getHexColor() { return hexColor; }
    }

    private final int itemId;
    private final String name;
    private final int quantity;
    private final long unitPrice;
    private final long totalValue;
    private final DropRarity rarity;

    public LootDropItem(int itemId, String name, int quantity, long unitPrice, DropRarity rarity) {
        this.itemId = itemId;
        this.name = name != null ? name : "Item #" + itemId;
        this.quantity = Math.max(1, quantity);
        this.unitPrice = Math.max(0, unitPrice);
        this.totalValue = (long) this.quantity * this.unitPrice;
        this.rarity = rarity != null ? rarity : classify(this.name, this.totalValue);
    }

    public static DropRarity classify(String name, long totalValue) {
        String n = name != null ? name.toLowerCase() : "";
        if (n.contains("pet") || n.contains("jar of") || n.contains("visage") || n.contains("tassets")
                || n.contains("chestplate") || n.contains("hilts") || n.contains("hilt")
                || n.contains("fang") || n.contains("shadow") || n.contains("bowfa")
                || n.contains("enhanced") || n.contains("vestige") || n.contains("scythe")
                || n.contains("twisted bow") || n.contains("head") && !n.contains("arrow")) {
            return DropRarity.UNIQUE;
        } else if (totalValue >= 500_000) {
            return DropRarity.RARE;
        } else if (totalValue >= 40_000) {
            return DropRarity.VALUABLE;
        }
        return DropRarity.COMMON;
    }

    public int getItemId() { return itemId; }
    public String getName() { return name; }
    public int getQuantity() { return quantity; }
    public long getUnitPrice() { return unitPrice; }
    public long getTotalValue() { return totalValue; }
    public DropRarity getRarity() { return rarity; }

    public String getFormattedTotalValue() {
        if (totalValue >= 1_000_000) {
            return String.format("%.2fM GP", totalValue / 1_000_000.0);
        } else if (totalValue >= 1_000) {
            return String.format("%dK GP", totalValue / 1_000);
        }
        return totalValue + " GP";
    }
}

package com.bosswise.model;

import java.time.Instant;
import java.time.ZoneId;
import java.time.format.DateTimeFormatter;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

public class LootSession {
    private static final DateTimeFormatter TIME_FMT = DateTimeFormatter.ofPattern("yyyy-MM-dd HH:mm")
            .withZone(ZoneId.systemDefault());

    private final String id;
    private final String monsterName;
    private final long startTime;
    private long endTime;
    private int kills;
    private final List<LootDropItem> drops = new ArrayList<>();
    private long estimatedSupplyCosts;

    public LootSession(String monsterName) {
        this.id = "session_" + System.currentTimeMillis();
        this.monsterName = monsterName != null ? monsterName : "Unknown Monster";
        this.startTime = System.currentTimeMillis();
        this.endTime = this.startTime;
        this.kills = 0;
        this.estimatedSupplyCosts = 0L;
    }

    public synchronized void recordKill(long supplyCostPerKill) {
        this.kills++;
        this.endTime = System.currentTimeMillis();
        this.estimatedSupplyCosts += Math.max(0, supplyCostPerKill);
    }

    public synchronized void addDrop(LootDropItem item) {
        if (item != null) {
            this.drops.add(item);
            this.endTime = System.currentTimeMillis();
        }
    }

    public synchronized void addDrops(List<LootDropItem> items) {
        if (items != null) {
            this.drops.addAll(items);
            this.endTime = System.currentTimeMillis();
        }
    }

    public String getId() { return id; }
    public String getMonsterName() { return monsterName; }
    public long getStartTime() { return startTime; }
    public long getEndTime() { return endTime; }
    public int getKills() { return kills; }
    public List<LootDropItem> getDrops() { return Collections.unmodifiableList(drops); }
    public long getEstimatedSupplyCosts() { return estimatedSupplyCosts; }

    public long getDurationSeconds() {
        return Math.max(1, (endTime - startTime) / 1000);
    }

    public String getFormattedDuration() {
        long sec = getDurationSeconds();
        long h = sec / 3600;
        long m = (sec % 3600) / 60;
        long s = sec % 60;
        if (h > 0) {
            return String.format("%dh %02dm %02ds", h, m, s);
        }
        return String.format("%02dm %02ds", m, s);
    }

    public String getFormattedStartTime() {
        return TIME_FMT.format(Instant.ofEpochMilli(startTime));
    }

    public long getTotalLootValue() {
        long sum = 0L;
        for (LootDropItem item : drops) {
            sum += item.getTotalValue();
        }
        return sum;
    }

    public long getNetProfit() {
        return getTotalLootValue() - estimatedSupplyCosts;
    }

    public long getGpPerKill() {
        if (kills <= 0) return 0L;
        return getTotalLootValue() / kills;
    }

    public long getProfitPerKill() {
        if (kills <= 0) return 0L;
        return getNetProfit() / kills;
    }

    public double getKillsPerHour() {
        double hours = getDurationSeconds() / 3600.0;
        if (hours <= 0) return 0.0;
        return kills / hours;
    }

    public long getProfitPerHour() {
        double hours = getDurationSeconds() / 3600.0;
        if (hours <= 0) return 0L;
        return (long) (getNetProfit() / hours);
    }

    public long getLootPerHour() {
        double hours = getDurationSeconds() / 3600.0;
        if (hours <= 0) return 0L;
        return (long) (getTotalLootValue() / hours);
    }

    public Map<LootDropItem.DropRarity, Integer> getRarityCounts() {
        Map<LootDropItem.DropRarity, Integer> counts = new HashMap<>();
        for (LootDropItem.DropRarity r : LootDropItem.DropRarity.values()) {
            counts.put(r, 0);
        }
        for (LootDropItem item : drops) {
            counts.put(item.getRarity(), counts.get(item.getRarity()) + 1);
        }
        return counts;
    }
}

