    private final int hitpoints;
    private final int attackLevel;
    private final int strengthLevel;
    private final int defenceLevel;
    private final int magicLevel;
    private final int rangedLevel;

    // Defensive bonuses
    private final int stabDefence;
    private final int slashDefence;
    private final int crushDefence;
    private final int magicDefence;
    private final int rangedDefence;

    // Combat attributes
    private final int attackSpeed;
    private final List<String> attackStyles;
    /** Max hit exactly as the wiki states it, e.g. "25 (Melee)" or "27 / 28 / 29 (phase 4)". */
    private final String maxHit;
    /** Wiki monster attributes: dragon, demon, undead, kalphite, leafy, golem, fiery, spectral, xerician... */
    private final List<String> attributes;
    private final boolean wilderness;
    private final boolean multiCombat;
    private final boolean cannonable;

    public MonsterVariant(
            int npcId,
            String variantName,
            String location,
            int combatLevel,
            int hitpoints,
            int attackLevel,
            int strengthLevel,
            int defenceLevel,
            int magicLevel,
            int rangedLevel,
            int stabDefence,
            int slashDefence,
            int crushDefence,
            int magicDefence,
            int rangedDefence,
            int attackSpeed,
            List<String> attackStyles,
            boolean wilderness,
            boolean multiCombat,
            boolean cannonable) {
        this(npcId, variantName, location, combatLevel, hitpoints, attackLevel, strengthLevel, defenceLevel,
                magicLevel, rangedLevel, stabDefence, slashDefence, crushDefence, magicDefence, rangedDefence,
                attackSpeed, attackStyles, wilderness, multiCombat, cannonable, null, null);
    }

    public MonsterVariant(
            int npcId,
            String variantName,
            String location,
            int combatLevel,
            int hitpoints,
            int attackLevel,
            int strengthLevel,
            int defenceLevel,
            int magicLevel,
            int rangedLevel,
            int stabDefence,
            int slashDefence,
            int crushDefence,
            int magicDefence,
            int rangedDefence,
            int attackSpeed,
            List<String> attackStyles,
            boolean wilderness,
            boolean multiCombat,
            boolean cannonable,
            String maxHit,
            List<String> attributes) {
        this.npcId = npcId;
        this.variantName = variantName != null ? variantName : "Standard";
        this.location = location != null ? location : "Various";
        this.combatLevel = combatLevel;
        this.hitpoints = hitpoints;
        this.attackLevel = attackLevel;
        this.strengthLevel = strengthLevel;
        this.defenceLevel = defenceLevel;
        this.magicLevel = magicLevel;
        this.rangedLevel = rangedLevel;
        this.stabDefence = stabDefence;
        this.slashDefence = slashDefence;
        this.crushDefence = crushDefence;
        this.magicDefence = magicDefence;
        this.rangedDefence = rangedDefence;
        this.attackSpeed = attackSpeed > 0 ? attackSpeed : 4;
        this.attackStyles = attackStyles != null ? Collections.unmodifiableList(attackStyles) : Collections.emptyList();
        this.wilderness = wilderness;
        this.multiCombat = multiCombat;
        this.cannonable = cannonable;
        this.maxHit = (maxHit != null && !maxHit.isEmpty()) ? maxHit : "Unknown";
        this.attributes = attributes != null ? Collections.unmodifiableList(attributes) : Collections.emptyList();
