    public long calculateTotalCost(List<InventoryItem> items) {
        if (items == null) return 0L;
        long sum = 0L;
        for (InventoryItem item : items) {
            sum += item.getTotalCost();
        }
        return sum;
    }
}

package com.bosswise.service;

import com.bosswise.db.BossDatabase;
import com.bosswise.db.MonsterDatabase;
import com.bosswise.model.BossData;
import com.bosswise.model.LootDropItem;
import com.bosswise.model.LootSession;
import com.bosswise.model.MonsterData;
import java.util.ArrayList;
import java.util.Collection;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import java.util.function.Consumer;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Client;
import net.runelite.api.NPC;
import net.runelite.client.events.NpcLootReceived;
import net.runelite.client.game.ItemStack;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class LootTrackerService {
    private static final Logger log = LoggerFactory.getLogger(LootTrackerService.class);

    private final GePriceService priceService;
    private final BossDatabase bossDatabase;
    private final MonsterDatabase monsterDatabase;
    private final Client client;

    private volatile LootSession activeSession = new LootSession("General Session");
    private final List<LootSession> sessionHistory = new CopyOnWriteArrayList<>();
    private final List<Consumer<LootSession>> sessionListeners = new CopyOnWriteArrayList<>();

    // Lifetime metrics
    private int lifetimeKills = 0;
    private long lifetimeLootValue = 0L;
    private long lifetimeSupplyCosts = 0L;

    @Inject
    public LootTrackerService(
            GePriceService priceService,
            BossDatabase bossDatabase,
            MonsterDatabase monsterDatabase,
            Client client) {
        this.priceService = priceService;
        this.bossDatabase = bossDatabase;
        this.monsterDatabase = monsterDatabase;
        this.client = client;
    }

    public void addSessionListener(Consumer<LootSession> listener) {
        if (listener != null) {
            sessionListeners.add(listener);
            listener.accept(activeSession);
        }
    }

    public void removeSessionListener(Consumer<LootSession> listener) {
        sessionListeners.remove(listener);
    }

    public LootSession getActiveSession() {
        return activeSession;
    }

    public List<LootSession> getSessionHistory() {
        return Collections.unmodifiableList(sessionHistory);
    }

    public synchronized void startNewSession(String monsterName) {
        if (activeSession.getKills() > 0 || !activeSession.getDrops().isEmpty()) {
            sessionHistory.add(activeSession);
        }
        activeSession = new LootSession(monsterName != null ? monsterName : "General Session");
        notifyListeners();
    }

    public synchronized void resetCurrentSession() {
        activeSession = new LootSession(activeSession.getMonsterName());
        notifyListeners();
    }

    public synchronized void clearAllHistory() {
        sessionHistory.clear();
        lifetimeKills = 0;
        lifetimeLootValue = 0L;
        lifetimeSupplyCosts = 0L;
        resetCurrentSession();
    }

    public synchronized void onNpcLoot(NPC npc, Collection<ItemStack> items) {
        if (npc == null || items == null || items.isEmpty()) {
            return;
        }

        String npcName = npc.getName();
        if (npcName == null) npcName = "Unknown NPC";

        // Estimate supply cost based on encounter tier
        long supplyCost = estimateSupplyCostForNpc(npcName);

        // Record the kill in the active session
        activeSession.recordKill(supplyCost);
        lifetimeKills++;
        lifetimeSupplyCosts += supplyCost;

        List<LootDropItem> drops = new ArrayList<>();
        for (ItemStack item : items) {
            int itemId = item.getId();
            int qty = item.getQuantity();

            long unitPrice = (priceService != null) ? priceService.getPrice(itemId, 0) : 0;
            String itemName = "Item #" + itemId;
            if (client != null && client.getItemDefinition(itemId) != null) {
                itemName = client.getItemDefinition(itemId).getName();
            }

            LootDropItem drop = new LootDropItem(itemId, itemName, qty, unitPrice, null);
            drops.add(drop);
            lifetimeLootValue += drop.getTotalValue();
        }

        activeSession.addDrops(drops);
        notifyListeners();
    }

    private long estimateSupplyCostForNpc(String npcName) {
        String lower = npcName.toLowerCase();
        if (lower.contains("vorkath") || lower.contains("zulrah") || lower.contains("muspah")) {
            return 8000L; // antifires, antivenom, super combat, dragon bolts
        } else if (lower.contains("corp") || lower.contains("nex") || lower.contains("chambers") || lower.contains("theatre")) {
            return 25000L; // brews, super restores, blood runes
        } else if (lower.contains("graardor") || lower.contains("kril") || lower.contains("kree") || lower.contains("zilyana")) {
            return 12000L;
        } else if (lower.contains("barrows")) {
            return 2500L; // prayer pots, spade, runes
        } else if (lower.contains("scurrius")) {
            return 1500L; // low food, prayer
        }
        return 800L; // standard slayer monster food
    }

    private void notifyListeners() {
        for (Consumer<LootSession> listener : sessionListeners) {
            try {
                listener.accept(activeSession);
            } catch (Exception ex) {
                log.error("Error notifying loot session listener", ex);
            }
        }
    }

    public int getLifetimeKills() { return lifetimeKills; }
    public long getLifetimeLootValue() { return lifetimeLootValue; }
    public long getLifetimeSupplyCosts() { return lifetimeSupplyCosts; }
    public long getLifetimeNetProfit() { return lifetimeLootValue - lifetimeSupplyCosts; }
}

package com.bosswise.service;

import com.bosswise.model.CombatStyle;
import com.bosswise.model.DeathRiskProfile;
import com.bosswise.model.MonsterCategory;
import com.bosswise.model.MonsterProfitProfile;
import com.google.gson.JsonArray;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class MonsterProfitService {
    public enum ProfitFilter {
        ALL("All Monsters"),
        BOSSES("Bosses & Demi-Bosses"),
        SLAYER("Slayer Monsters"),
        LOW_LEVEL("Low-Level & Early Game"),
        MELEE("Best for Melee"),
        RANGED("Best for Ranged"),
        MAGIC("Best for Magic"),
        AFK("Best AFK Options"),
        LOW_GEAR_COST("Budget-Friendly (<1M Gear)");

        private final String displayName;
        ProfitFilter(String displayName) { this.displayName = displayName; }
        public String getDisplayName() { return displayName; }
        @Override public String toString() { return displayName; }
    }

    public enum ProfitSort {
        NET_PROFIT_DESC("Highest Net Profit"),
        GP_PER_KILL_DESC("Highest GP Per Kill"),
        KILLS_PER_HR_DESC("Fastest Kills/Hour"),
        GEAR_COST_ASC("Lowest Gear Cost");

        private final String displayName;
        ProfitSort(String displayName) { this.displayName = displayName; }
        public String getDisplayName() { return displayName; }
        @Override public String toString() { return displayName; }
    }

    private static final Logger log = LoggerFactory.getLogger(MonsterProfitService.class);
    private final List<MonsterProfitProfile> profiles = new ArrayList<>();

    @Inject
    public MonsterProfitService() {
        loadProfilesFromJson();
    }

    private void loadProfilesFromJson() {
        try (InputStream is = getClass().getResourceAsStream("/data/profit_profiles.json")) {
            if (is == null) return;
            JsonElement parsed = new JsonParser().parse(new InputStreamReader(is, StandardCharsets.UTF_8));
            JsonArray arr = (parsed != null && parsed.isJsonArray()) ? parsed.getAsJsonArray() : null;
            if (arr == null) return;
            for (JsonElement elem : arr) {
                if (!elem.isJsonObject()) continue;
                JsonObject o = elem.getAsJsonObject();
                JsonObject dro = o.has("deathRisk") && o.get("deathRisk").isJsonObject()
                        ? o.getAsJsonObject("deathRisk") : null;
                DeathRiskProfile dr = dro != null ? new DeathRiskProfile(
                        dro.get("locationType").getAsString(),
                        dro.get("gravestoneFee").getAsLong(),
                        dro.get("retrievalServiceFee").getAsLong(),
                        dro.get("estimatedSupplyLoss").getAsLong(),
                        dro.get("pvpDangerous").getAsBoolean(),
                        dro.get("explanation").getAsString()
                ) : null;
                profiles.add(new MonsterProfitProfile(
                        o.get("monsterId").getAsString(),
                        o.get("name").getAsString(),
                        MonsterCategory.valueOf(o.get("category").getAsString()),
                        CombatStyle.valueOf(o.get("primaryStyle").getAsString()),
                        o.get("combatLevel").getAsInt(),
                        o.get("gpPerKill").getAsLong(),
                        o.get("killsPerHour").getAsInt(),
                        o.get("conservativeGpPerHour").getAsLong(),
                        o.get("optimisticGpPerHour").getAsLong(),
                        o.get("supplyCostPerHour").getAsLong(),
                        o.get("ammoCostPerHour").getAsLong(),
                        o.get("minGearInvestment").getAsLong(),
                        o.get("afkSuitable").getAsBoolean(),
                        o.get("killTimeSeconds").getAsInt(),
                        o.get("respawnSeconds").getAsInt(),
                        dr,
                        o.has("assumptions") ? o.get("assumptions").getAsString() : ""
                ));
            }
        } catch (Exception e) {
            log.error("[BossWise] Failed to load profit profiles from JSON", e);
        }
    }

    public List<MonsterProfitProfile> getAllProfiles() {
        return Collections.unmodifiableList(profiles);
    }

    public MonsterProfitProfile getProfile(String id) {
        if (id == null) return null;
        for (MonsterProfitProfile p : profiles) {
            if (p.getMonsterId().equalsIgnoreCase(id) || p.getMonsterName().equalsIgnoreCase(id)) {
                return p;
            }
        }
        return null;
    }

    public List<MonsterProfitProfile> getFilteredProfiles(ProfitFilter filter, ProfitSort sort) {
        List<MonsterProfitProfile> result = new ArrayList<>();

        for (MonsterProfitProfile p : profiles) {
            boolean match = true;
            if (filter != null) {
                switch (filter) {
                    case BOSSES:
                        match = (p.getCategory() == MonsterCategory.BOSS || p.getCategory() == MonsterCategory.RAID || p.getCategory() == MonsterCategory.DEMI_BOSS);
                        break;
                    case SLAYER:
                        match = (p.getCategory() == MonsterCategory.SLAYER || p.getCategory() == MonsterCategory.SUPERIOR);
                        break;
                    case LOW_LEVEL:
                        match = (p.getCombatLevel() <= 160 || p.getMinGearInvestment() <= 500000);
                        break;
                    case MELEE:
                        match = (p.getPrimaryStyle() == CombatStyle.MELEE);
                        break;
                    case RANGED:
                        match = (p.getPrimaryStyle() == CombatStyle.RANGED);
                        break;
                    case MAGIC:
                        match = (p.getPrimaryStyle() == CombatStyle.MAGIC);
                        break;
                    case AFK:
                        match = p.isAfkSuitable();
                        break;
                    case LOW_GEAR_COST:
                        match = (p.getMinGearInvestment() <= 1000000);
                        break;
                    case ALL:
                    default:
                        match = true;
                        break;
                }
            }
            if (match) {
                result.add(p);
            }
        }

        if (sort != null) {
            switch (sort) {
                case GP_PER_KILL_DESC:
                    result.sort(Comparator.comparingLong(MonsterProfitProfile::getGpPerKill).reversed());
                    break;
                case KILLS_PER_HR_DESC:
                    result.sort(Comparator.comparingInt(MonsterProfitProfile::getKillsPerHour).reversed());
                    break;
                case GEAR_COST_ASC:
                    result.sort(Comparator.comparingLong(MonsterProfitProfile::getMinGearInvestment));
                    break;
                case NET_PROFIT_DESC:
                default:
                    result.sort(Comparator.comparingLong(MonsterProfitProfile::getNetProfitPerHour).reversed());
                    break;
            }
        }

        return result;
    }
}

package com.bosswise.service;

import com.bosswise.db.BossDatabase;
import com.bosswise.db.MonsterDatabase;
import com.bosswise.db.MonsterStrategyDatabase;
import com.bosswise.model.BossData;
import com.bosswise.model.CombatStyle;
import com.bosswise.model.InventorySetup;
import com.bosswise.model.MonsterData;
import com.bosswise.model.OptimizedGearSetup;
import com.bosswise.model.PlayerAccount;
import com.bosswise.model.strategy.MonsterStrategy;
import com.bosswise.model.strategy.PersonalizedStrategyScore;
import com.bosswise.model.strategy.StrategyMethod;
import com.bosswise.model.strategy.StrategyTier;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
public class MonsterStrategyService {
    private final MonsterStrategyDatabase strategyDatabase;
    private final GearOptimizerService gearOptimizerService;
    private final InventoryBuilderService inventoryBuilderService;
    private final MonsterDatabase monsterDatabase;
    private final BossDatabase bossDatabase;

    @Inject
    public MonsterStrategyService(
            MonsterStrategyDatabase strategyDatabase,
            GearOptimizerService gearOptimizerService,
            InventoryBuilderService inventoryBuilderService,
            MonsterDatabase monsterDatabase,
            BossDatabase bossDatabase) {
        this.strategyDatabase = strategyDatabase;
        this.gearOptimizerService = gearOptimizerService;
        this.inventoryBuilderService = inventoryBuilderService;
        this.monsterDatabase = monsterDatabase;
        this.bossDatabase = bossDatabase;
    }

    /**
     * Personalize all available strategy methods for a monster given the player's account and budget.
     */
    public List<PersonalizedStrategyScore> personalize(MonsterStrategy strategy, PlayerAccount account, long userBudget) {
        if (strategy == null || strategy.getMethods().isEmpty()) {
            return Collections.emptyList();
        }

        PlayerAccount acc = account != null ? account : PlayerAccount.createDefault();
        List<PersonalizedStrategyScore> scoredList = new ArrayList<>();

        for (StrategyMethod method : strategy.getMethods()) {
            List<String> missing = new ArrayList<>();
            boolean meetsAll = true;

            // Check skills
            for (Map.Entry<Skill, Integer> req : method.getRequiredSkills().entrySet()) {
                int playerLvl = acc.getSkillLevel(req.getKey());
                if (playerLvl < req.getValue()) {
                    meetsAll = false;
                    missing.add(req.getKey().getName() + " " + req.getValue() + " (Current: " + playerLvl + ")");
                }
            }

            // Check Slayer requirement if applicable
            if (strategy.getSlayerLevel() > 1) {
                int playerSlayer = acc.getSkillLevel(Skill.SLAYER);
                if (playerSlayer < strategy.getSlayerLevel()) {
                    meetsAll = false;
                    missing.add("Slayer " + strategy.getSlayerLevel() + " (Current: " + playerSlayer + ")");
                }
            }

            // Check quests
            for (String quest : method.getRequiredQuests()) {
                if (!acc.hasCompletedQuest(quest)) {
                    meetsAll = false;
                    missing.add("Quest: " + quest);
                }
            }

            // Calculate base viability score
            double score = 100.0;

            // Combat style affinity based on player levels
            if (method.getCombatStyle() == CombatStyle.RANGED) {
                int range = acc.getSkillLevel(Skill.RANGED);
                score += (range - 70) * 2.0;
                if (acc.getSkillLevel(Skill.PRAYER) >= 74) score += 15.0; // Rigour unlock
            } else if (method.getCombatStyle() == CombatStyle.MAGIC) {
                int mage = acc.getSkillLevel(Skill.MAGIC);
                score += (mage - 70) * 2.0;
                if (acc.getSkillLevel(Skill.PRAYER) >= 77) score += 15.0; // Augury
            } else {
                int atk = acc.getSkillLevel(Skill.ATTACK);
                int str = acc.getSkillLevel(Skill.STRENGTH);
                score += ((atk + str) / 2.0 - 70) * 2.0;
                if (acc.getSkillLevel(Skill.PRAYER) >= 70) score += 15.0; // Piety
            }

            // Budget adjustment
            if (userBudget > 0) {
                if (method.getEstimatedCostGp() <= userBudget) {
                    score += 25.0;
                } else {
                    double deficitRatio = (double) method.getEstimatedCostGp() / Math.max(1L, userBudget);
                    score -= Math.min(80.0, (deficitRatio - 1.0) * 30.0);
                }
            }

            // Tier weight
            score += method.getTier().getSortOrder() * 10.0;

            if (!meetsAll) {
                score -= 100.0; // Penalty for missing requirements
            }

            scoredList.add(new PersonalizedStrategyScore(
                    method, score, meetsAll, missing,
                    false, false, false, false, false, ""
            ));
        }

        // Sort by score descending
        scoredList.sort((a, b) -> Double.compare(b.getScore(), a.getScore()));

        // Assign special badges: Best Overall, Best Budget, Best DPS, Best Survival, Best Value
        PersonalizedStrategyScore bestOverall = null;
        PersonalizedStrategyScore bestBudget = null;
        PersonalizedStrategyScore bestDps = null;
        PersonalizedStrategyScore bestSurvival = null;
        PersonalizedStrategyScore bestValue = null;

        for (PersonalizedStrategyScore s : scoredList) {
            if (s.isMeetsAllRequirements() && bestOverall == null) {
                bestOverall = s;
                break;
            }
        }
        if (bestOverall == null && !scoredList.isEmpty()) {
            bestOverall = scoredList.get(0);
        }

        // Find Best Budget
        long lowestCost = Long.MAX_VALUE;
        for (PersonalizedStrategyScore s : scoredList) {
            if (s.getMethod().getEstimatedCostGp() < lowestCost) {
                lowestCost = s.getMethod().getEstimatedCostGp();
                bestBudget = s;
            }
        }

        // Find Best DPS (highest tier among viable)
        int highestTier = -1;
        for (PersonalizedStrategyScore s : scoredList) {
            if (s.isMeetsAllRequirements() && s.getMethod().getTier().getSortOrder() > highestTier) {
                highestTier = s.getMethod().getTier().getSortOrder();
                bestDps = s;
            }
        }
        if (bestDps == null && !scoredList.isEmpty()) {
            bestDps = scoredList.get(0);
        }

        // Find Best Survival (Ranged/Magic or High Defence)
        for (PersonalizedStrategyScore s : scoredList) {
            if (s.getMethod().getCombatStyle() == CombatStyle.RANGED || s.getMethod().getTitle().toLowerCase().contains("safespot") || s.getMethod().getTier() == StrategyTier.HIGH_LEVEL) {
                bestSurvival = s;
                break;
            }
        }
        if (bestSurvival == null && !scoredList.isEmpty()) {
            bestSurvival = scoredList.get(0);
        }

        // Best Value (Mid-Game or Best Value tier)
        for (PersonalizedStrategyScore s : scoredList) {
            if (s.getMethod().getTier() == StrategyTier.MID_GAME || s.getMethod().getTier() == StrategyTier.BEGINNER) {
                bestValue = s;
                break;
            }
        }
        if (bestValue == null && !scoredList.isEmpty()) {
            bestValue = scoredList.get(0);
        }

        // Re-construct with badges and explanations
        List<PersonalizedStrategyScore> finalized = new ArrayList<>();
        for (PersonalizedStrategyScore s : scoredList) {
            boolean isBo = s == bestOverall;
            boolean isBb = s == bestBudget;
            boolean isBd = s == bestDps;
            boolean isBs = s == bestSurvival;
            boolean isBv = s == bestValue;

            StringBuilder reason = new StringBuilder();
            if (isBo) {
                reason.append("Best overall match for your combat stats (");
                reason.append(s.getMethod().getCombatStyle().getDisplayName()).append("). ");
            }
            if (isBb) {
                reason.append("Most affordable setup with minimal financial barrier. ");
            }
            if (isBd) {
                reason.append("Maximal damage output potential. ");
            }
            if (isBs) {
                reason.append("Provides highest survivability and defensive safety. ");
            }
            if (isBv) {
                reason.append("Best performance-to-cost efficiency ratio. ");
            }
            if (!s.isMeetsAllRequirements()) {
                reason.append("Locked: Missing ").append(s.getMissingRequirements().size()).append(" requirements.");
            } else if (reason.length() == 0) {
                reason.append("Viable alternative method for ").append(strategy.getMonsterName()).append(".");
            }

            finalized.add(new PersonalizedStrategyScore(
                    s.getMethod(), s.getScore(), s.isMeetsAllRequirements(),
                    s.getMissingRequirements(), isBo, isBb, isBd, isBs, isBv,
                    reason.toString().trim()
            ));
        }

        return finalized;
    }

    /**
     * Interoperate with GearOptimizerService to generate authoritative calculated gear setup.
     */
    public OptimizedGearSetup getCalculatedGearSetup(StrategyMethod method, MonsterStrategy strategy, PlayerAccount account, long budget) {
        if (gearOptimizerService == null || strategy == null || method == null) return null;

        BossData boss = bossDatabase != null ? bossDatabase.getBoss(strategy.getMonsterId()) : null;
        MonsterData monster = monsterDatabase != null ? monsterDatabase.getMonster(strategy.getMonsterId()) : null;

        if (boss == null && monster != null) {
            boss = monster.toBossData();
        }

        String tierName = method.getTitle();
        CombatStyle style = method.getCombatStyle();
        long loadoutBudget = budget > 0 ? budget : method.getEstimatedCostGp();

        return gearOptimizerService.generateSetup(
                tierName, boss, monster, null, style,
                loadoutBudget > 0 ? loadoutBudget : 10_000_000L,
                account != null ? account : PlayerAccount.createDefault(),
                GearOptimizerService.PriorityMode.BALANCED,
                false
        );
    }

    /**
     * Interoperate with InventoryBuilderService to generate matched inventory recommendations.
     */
    public InventorySetup getCalculatedInventorySetup(StrategyMethod method, MonsterStrategy strategy, PlayerAccount account) {
        if (inventoryBuilderService == null || strategy == null || method == null) return null;

        BossData boss = bossDatabase != null ? bossDatabase.getBoss(strategy.getMonsterId()) : null;
        if (boss == null && monsterDatabase != null) {
            MonsterData m = monsterDatabase.getMonster(strategy.getMonsterId());
            if (m != null) boss = m.toBossData();
        }

        if (boss == null) return null;

        return inventoryBuilderService.getInventorySetup(
                boss,
                method.getTier().getDisplayName()
        );
    }

    public MonsterStrategyDatabase getStrategyDatabase() {
        return strategyDatabase;
    }
}

package com.bosswise.service;

import com.bosswise.model.CombatStyle;
import com.bosswise.model.MonsterCombatProfile;
import com.bosswise.model.PlayerAccount;
import com.bosswise.model.PrayerPlan;
import java.util.ArrayList;
import java.util.Arrays;
import java.util.List;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
public class PrayerPotionOptimizerService {
    private final GePriceService priceService;

    @Inject
    public PrayerPotionOptimizerService(GePriceService priceService) {
        this.priceService = priceService;
    }

    public List<PrayerPlan> evaluatePrayerPlans(
            MonsterCombatProfile profile,
            PlayerAccount account,
            CombatStyle style,
            int totalPrayerBonus) {

        int prayLvl = account != null ? account.getRealLevel(Skill.PRAYER) : 70;
        int restorePerDose = (int) Math.floor(7 + (prayLvl * 0.25));
        int restorePerPot = restorePerDose * 4;

        long prayPotPrice = priceService != null ? priceService.getPrice(139, 9500) : 9500;
        long superCombatPrice = priceService != null ? priceService.getPrice(12695, 12500) : 12500;
        long divineCombatPrice = priceService != null ? priceService.getPrice(23685, 18500) : 18500;

        String defOverhead = (profile != null && profile.getOverheadPrayer() != null && !profile.getOverheadPrayer().equalsIgnoreCase("None"))
                ? profile.getOverheadPrayer()
                : "Protect from Melee";

        List<PrayerPlan> plans = new ArrayList<>();

        // 1. Full Max Power (Piety / Rigour / Augury + Overhead + Divine Potions)
        String maxOffensive;
        double maxDmg;
        double maxAcc;
        double baseOffDrain;

        if (style == CombatStyle.RANGED) {
            if (prayLvl >= 74) {
                maxOffensive = "Rigour (+23% Str, +20% Acc)";
                maxDmg = 1.23; maxAcc = 1.20; baseOffDrain = 40.0;
            } else if (prayLvl >= 44) {
                maxOffensive = "Eagle Eye (+15% Str, +15% Acc)";
                maxDmg = 1.15; maxAcc = 1.15; baseOffDrain = 20.0;
            } else {
                maxOffensive = "Hawk Eye (+10% Str, +10% Acc)";
                maxDmg = 1.10; maxAcc = 1.10; baseOffDrain = 10.0;
            }
        } else if (style == CombatStyle.MAGIC) {
            if (prayLvl >= 77) {
                maxOffensive = "Augury (+25% Acc, +25% Def)";
                maxDmg = 1.04; maxAcc = 1.25; baseOffDrain = 40.0;
            } else if (prayLvl >= 45) {
                maxOffensive = "Mystic Might (+15% Acc)";
                maxDmg = 1.0; maxAcc = 1.15; baseOffDrain = 20.0;
            } else {
                maxOffensive = "Mystic Lore (+10% Acc)";
                maxDmg = 1.0; maxAcc = 1.10; baseOffDrain = 10.0;
            }
        } else {
            if (prayLvl >= 70) {
                maxOffensive = "Piety (+23% Str, +20% Acc, +25% Def)";
                maxDmg = 1.23; maxAcc = 1.20; baseOffDrain = 40.0;
            } else if (prayLvl >= 60) {
                maxOffensive = "Chivalry (+18% Str, +15% Acc, +20% Def)";
                maxDmg = 1.18; maxAcc = 1.15; baseOffDrain = 40.0;
            } else if (prayLvl >= 31) {
                maxOffensive = "Ultimate Strength (+15% Str)";
                maxDmg = 1.15; maxAcc = 1.0; baseOffDrain = 20.0;
            } else {
                maxOffensive = "Superhuman Strength (+10% Str)";
                maxDmg = 1.10; maxAcc = 1.0; baseOffDrain = 10.0;
            }
        }

        // Full Power Plan
        double totalBaseDrainFull = baseOffDrain + 20.0; // Offensive + Defensive overhead
        double drainPerMinFull = totalBaseDrainFull / (1.0 + (totalPrayerBonus / 30.0));
        double potsPerHourFull = (drainPerMinFull * 60.0) / (double) restorePerPot;
        long prayCostFull = (long) (potsPerHourFull * prayPotPrice);
        long potCostFull = (divineCombatPrice * 3); // ~3 pots per hour for divine (1 dose per 5 min = 12 doses = 3 pots)

        plans.add(new PrayerPlan(
                "Maximum Power & DPS",
                maxOffensive,
                defOverhead,
                maxDmg, maxAcc,
                drainPerMinFull,
                potsPerHourFull,
                prayCostFull,
                "Divine Potion (Maintained +15% stats)",
                potCostFull,
                Arrays.asList("Highest kill speed and accuracy.", "Drinks Divine potions every 5 minutes.", "High prayer consumption.")
        ));

        // 2. Balanced / Value Plan (15% Prayer + Overhead + Regular Super Combat)
        String balOffensive = (prayLvl >= 31) ? "15% Damage Prayer" : "10% Damage Prayer";
        double balBaseDrain = 20.0 + 20.0;
        double drainPerMinBal = balBaseDrain / (1.0 + (totalPrayerBonus / 30.0));
        double potsPerHourBal = (drainPerMinBal * 60.0) / (double) restorePerPot;
        long prayCostBal = (long) (potsPerHourBal * prayPotPrice);
        long potCostBal = superCombatPrice * 2;

        plans.add(new PrayerPlan(
                "Balanced & Value",
                balOffensive,
                defOverhead,
                1.15, 1.10,
                drainPerMinBal,
                potsPerHourBal,
                prayCostBal,
                "Regular Super Potion",
                potCostBal,
                Arrays.asList("30% lower prayer potion consumption than Piety/Rigour.", "Drinks standard potions every 7-10 minutes.")
        ));

        // 3. Ultra-Conservative / Camping Plan (Defensive Overhead Only)
        double drainPerMinCons = 20.0 / (1.0 + (totalPrayerBonus / 30.0));
        double potsPerHourCons = (drainPerMinCons * 60.0) / (double) restorePerPot;
        long prayCostCons = (long) (potsPerHourCons * prayPotPrice);

        plans.add(new PrayerPlan(
                "Sustain & Camping",
                "None (Conserve Prayer)",
                defOverhead,
                1.0, 1.0,
                drainPerMinCons,
                potsPerHourCons,
                prayCostCons,
                "Combat Potion",
                potCostBal,
                Arrays.asList("No offensive prayer drain. Minimizes trip banking.", "Triples trip length at the cost of ~15% DPS.")
        ));

        return plans;
    }
}

package com.bosswise.service;

import com.bosswise.model.WatchlistItem;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;
import java.util.concurrent.CopyOnWriteArrayList;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.config.ConfigManager;

@Singleton
public class PriceWatcherService {
    private final GePriceService priceService;
    private final ConfigManager configManager;
    private final List<WatchlistItem> watchlist = new CopyOnWriteArrayList<>();

    @Inject
    public PriceWatcherService(GePriceService priceService, ConfigManager configManager) {
        this.priceService = priceService;
        this.configManager = configManager;
        initDefaultWatchlist();
    }

    private void initDefaultWatchlist() {
        // High impact bossing items
        addItem(26219, "Osmumten's fang", 12500000, 11000000);
        addItem(25865, "Bow of faerdhinen", 115000000, 105000000);
        addItem(21012, "Dragon hunter crossbow", 58000000, 52000000);
        addItem(11832, "Bandos chestplate", 28000000, 25000000);
        addItem(13576, "Dragon warhammer", 26000000, 22000000);
    }

    public List<WatchlistItem> getWatchlist() {
        return Collections.unmodifiableList(watchlist);
    }

    public synchronized void addItem(int itemId, String name, long defaultPrice, long targetPrice) {
        for (WatchlistItem item : watchlist) {
            if (item.getItemId() == itemId) {
                item.setTargetPrice(targetPrice);
                return;
            }
        }
        long livePrice = (priceService != null) ? priceService.getPrice(itemId, defaultPrice) : defaultPrice;
        watchlist.add(new WatchlistItem(itemId, name, livePrice, targetPrice));
    }

    public synchronized void removeItem(int itemId) {
        watchlist.removeIf(item -> item.getItemId() == itemId);
    }

    public synchronized void updateTargetPrice(int itemId, long newTarget) {
        for (WatchlistItem item : watchlist) {
            if (item.getItemId() == itemId) {
                item.setTargetPrice(newTarget);
                break;
            }
        }
    }

    public synchronized void refreshPrices() {
        if (priceService == null) return;
        for (WatchlistItem item : watchlist) {
            long live = priceService.getPrice(item.getItemId(), item.getCurrentPrice());
            if (live > 0) {
                item.setCurrentPrice(live);
            }
        }
    }
}

package com.bosswise.service;

import com.bosswise.db.BossDatabase;
import com.bosswise.model.BossData;
import com.bosswise.model.BossEligibility;
import com.bosswise.model.BossEligibilityStatus;
import com.bosswise.model.PlayerAccount;
import com.bosswise.model.ProgressionGoal;
import com.bosswise.model.QuestRequirement;
import com.bosswise.model.SkillRequirement;
import java.util.ArrayList;
import java.util.Collections;
import java.util.Comparator;
import java.util.HashSet;
import java.util.List;
import java.util.Set;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.api.Skill;

@Singleton
public class ProgressionService {
    private final BossDatabase bossDatabase;
    private final BossRecommendationEngine recommendationEngine;

    @Inject
    public ProgressionService(BossDatabase bossDatabase, BossRecommendationEngine recommendationEngine) {
        this.bossDatabase = bossDatabase;
        this.recommendationEngine = recommendationEngine;
    }

    public List<ProgressionGoal> generateRoadmap(PlayerAccount account) {
        if (account == null) {
            account = PlayerAccount.createDefault();
        }

        List<ProgressionGoal> goals = new ArrayList<>();
        Set<String> seenGoals = new HashSet<>();

        // 1. Scan for missing quest unlocks on ALMOST_READY or high-value bosses
        for (BossData boss : bossDatabase.getAllBosses().values()) {
            for (QuestRequirement qReq : boss.getQuestRequirements()) {
                if (qReq.isMandatory() && !account.isQuestCompleted(qReq.getQuest(), qReq.getQuestName())) {
                    String key = "QUEST_" + qReq.getQuestName();
                    if (!seenGoals.contains(key)) {
                        seenGoals.add(key);
                        goals.add(new ProgressionGoal(
                                key,
                                ProgressionGoal.GoalType.QUEST,
                                "Complete " + qReq.getQuestName(),
                                "Unlocks access to " + boss.getName() + " and vital endgame gear.",
                                0, 1, false,
                                1, boss.getName()
                        ));
                    }
                }
            }
        }

        // 2. Scan for missing skill requirements
        for (BossData boss : bossDatabase.getAllBosses().values()) {
            BossEligibility el = recommendationEngine.evaluateEligibility(boss, account);
            if (el.getStatus() == BossEligibilityStatus.ALMOST_READY) {
                for (SkillRequirement req : boss.getMinimumSkillRequirements()) {
                    int cur = account.getRealLevel(req.getSkill());
                    if (cur < req.getLevel()) {
                        String key = "SKILL_" + req.getSkill().getName() + "_" + req.getLevel();
                        if (!seenGoals.contains(key)) {
                            seenGoals.add(key);
                            goals.add(new ProgressionGoal(
                                    key,
                                    ProgressionGoal.GoalType.SKILL,
                                    "Train " + req.getSkill().getName() + " (" + cur + " -> " + req.getLevel() + ")",
                                    "Required entry level for " + boss.getName() + ".",
                                    cur, req.getLevel(), false,
                                    2, boss.getName()
                            ));
                        }
                    }
                }
            }
        }

        // 3. High-impact milestone unlocks
        int prayer = account.getRealLevel(Skill.PRAYER);
        if (prayer < 70) {
            goals.add(new ProgressionGoal(
                    "PRAYER_PIETY",
                    ProgressionGoal.GoalType.SKILL,
                    "Train Prayer to 70 for Piety",
                    "Piety grants +25% Defence, +23% Strength, and +20% Attack bonus.",
                    prayer, 70, false,
                    2, "All Melee Bosses"
            ));
        }

        int slayer = account.getRealLevel(Skill.SLAYER);
        if (slayer < 85) {
            goals.add(new ProgressionGoal(
                    "SLAYER_85",
                    ProgressionGoal.GoalType.SKILL,
                    "Train Slayer to 85 for Abyssal Sire",
                    "Unlocks Abyssal Demons, Abyssal Whip, and Abyssal Sire.",
                    slayer, 85, false,
                    3, "Abyssal Sire"
            ));
        } else if (slayer < 87) {
            goals.add(new ProgressionGoal(
                    "SLAYER_87",
                    ProgressionGoal.GoalType.SKILL,
                    "Train Slayer to 87 for Kraken",
                    "Unlocks Cave Krakens and Trident of the Seas.",
                    slayer, 87, false,
                    3, "Kraken"
            ));
        } else if (slayer < 95) {
            goals.add(new ProgressionGoal(
                    "SLAYER_95",
                    ProgressionGoal.GoalType.SKILL,
                    "Train Slayer to 95 for Alchemical Hydra",
                    "Unlocks Alchemical Hydra and Hydra's Claw (Ferocious Gloves).",
                    slayer, 95, false,
                    3, "Alchemical Hydra"
            ));
        }

        int ranged = account.getRealLevel(Skill.RANGED);
        if (ranged < 75) {
            goals.add(new ProgressionGoal(
                    "RANGED_75",
                    ProgressionGoal.GoalType.SKILL,
                    "Train Ranged to 75 for Toxic Blowpipe",
                    "Enables Toxic Blowpipe, Dragon Hunter Crossbow, and higher boss DPS.",
                    ranged, 75, false,
                    2, "Vorkath, Zulrah, ToA"
            ));
        }

        // Sort by priority (lowest number = highest priority)
        goals.sort(Comparator.comparingInt(ProgressionGoal::getPriority));

        return Collections.unmodifiableList(goals);
    }
}

