package com.bosswise.service;

import com.bosswise.model.CombatStyle;
import com.bosswise.model.EquipmentItem;
import com.bosswise.model.EquipmentSlot;
import com.bosswise.model.MonsterCombatProfile;
import java.util.Map;
import javax.inject.Singleton;

@Singleton
public class SpecialEffectService {

    public static class CombatMultipliers {
        private final double accuracyMultiplier;
        private final double damageMultiplier;
        private final int flatMaxHitBonus;
        private final String effectSummary;

        public CombatMultipliers(double accuracyMultiplier, double damageMultiplier, int flatMaxHitBonus, String effectSummary) {
            this.accuracyMultiplier = accuracyMultiplier;
            this.damageMultiplier = damageMultiplier;
            this.flatMaxHitBonus = flatMaxHitBonus;
            this.effectSummary = effectSummary != null ? effectSummary : "";
        }

        public double getAccuracyMultiplier() { return accuracyMultiplier; }
        public double getDamageMultiplier() { return damageMultiplier; }
        public int getFlatMaxHitBonus() { return flatMaxHitBonus; }
        public String getEffectSummary() { return effectSummary; }
    }

    public CombatMultipliers getMeleeMultipliers(
            Map<EquipmentSlot, EquipmentItem> equipment,
            MonsterCombatProfile profile,
            boolean onSlayerTask) {

        double accMult = 1.0;
        double dmgMult = 1.0;
        int flatBonus = 0;
        StringBuilder notes = new StringBuilder();

        EquipmentItem weapon = equipment.get(EquipmentSlot.WEAPON);
        EquipmentItem neck = equipment.get(EquipmentSlot.AMULET);
        EquipmentItem helm = equipment.get(EquipmentSlot.HEAD);

        // 1. Undead vs Slayer Stacking Rule: Salve does NOT stack with Slayer helm
        boolean salveApplied = false;
        if (profile != null && profile.isUndead() && neck != null) {
            String neckName = neck.getName().toLowerCase();
            if (neckName.contains("salve amulet (ei)") || neckName.contains("salve amulet(ei)") ||
                neckName.contains("salve amulet (e)") || neckName.contains("salve amulet(e)")) {
                accMult *= 1.20;
                dmgMult *= 1.20;
                salveApplied = true;
                notes.append("Salve (e) active (+20% acc/dmg). ");
            } else if (neckName.contains("salve amulet")) {
                accMult *= 1.15;
                dmgMult *= 1.15;
                salveApplied = true;
                notes.append("Salve active (+15% acc/dmg). ");
            }
        }

        // 2. Slayer Helm (only if Salve didn't take priority)
        if (!salveApplied && onSlayerTask && helm != null) {
            String helmName = helm.getName().toLowerCase();
            if (helmName.contains("slayer helmet") || helmName.contains("black mask")) {
                accMult *= (7.0 / 6.0); // +16.67%
                dmgMult *= (7.0 / 6.0);
                notes.append("Slayer helm active (+16.67% acc/dmg). ");
            }
        }

        // 3. Void Knight Melee (Stacks with Salve!)
        if (isFullVoid(equipment, "melee")) {
            accMult *= 1.10;
            dmgMult *= 1.10;
            notes.append("Void Knight Melee active (+10% acc/dmg). ");
        }

        // 4. Weapon Target Multipliers
        if (weapon != null && profile != null) {
            String weaponName = weapon.getName().toLowerCase();

            // Dragonbane
            if (profile.isDragon() && weapon.isDragonbane()) {
                accMult *= 1.20;
                dmgMult *= 1.20;
                notes.append("Dragonbane (DHL) active (+20% acc/dmg). ");
            }

            // Demonbane
            if (profile.isDemon() && weapon.isDemonbane()) {
                if (weaponName.contains("emberlight")) {
                    accMult *= 1.70;
                    dmgMult *= 1.70;
                    notes.append("Emberlight active (+70% acc, +70% dmg). ");
                } else if (weaponName.contains("darklight")) {
                    accMult *= 1.60;
                    dmgMult *= 1.60;
                    notes.append("Darklight active (+60% acc, +60% dmg). ");
                } else {
                    accMult *= 1.70;
                    dmgMult *= 1.70;
                    notes.append("Arclight active (+70% acc, +70% dmg). ");
                }
            }

            // Kalphitebane
            if (profile.isKalphite() && (weaponName.contains("keris") || weapon.isKalphitebane())) {
                // Keris Partisan provides +33% pierce damage with 1/51 proc chance of 3x damage
                accMult *= 1.0;
                dmgMult *= 1.372; // Effective average expected damage multiplier
                notes.append("Keris Partisan active (+37.2% expected dmg). ");
            }

            // Ratbane
            if (profile.isRat() && weapon.isRatbane()) {
                flatBonus += 10;
                notes.append("Bone mace active (+10 flat max hit). ");
            }

            // Wilderness Weapons
            if (profile.isWilderness() && weapon.isWildernessBonus()) {
                accMult *= 1.50;
                dmgMult *= 1.50;
                notes.append("Wilderness buff active (+50% acc/dmg). ");
            }
        }

        return new CombatMultipliers(accMult, dmgMult, flatBonus, notes.toString().trim());
    }

    public CombatMultipliers getRangedMultipliers(
            Map<EquipmentSlot, EquipmentItem> equipment,
            MonsterCombatProfile profile,
            boolean onSlayerTask) {

        double accMult = 1.0;
        double dmgMult = 1.0;
        int flatBonus = 0;
        StringBuilder notes = new StringBuilder();

        EquipmentItem weapon = equipment.get(EquipmentSlot.WEAPON);
        EquipmentItem neck = equipment.get(EquipmentSlot.AMULET);
        EquipmentItem helm = equipment.get(EquipmentSlot.HEAD);

        // 1. Salve vs Slayer
        boolean salveApplied = false;
        if (profile != null && profile.isUndead() && neck != null) {
            String neckName = neck.getName().toLowerCase();
            if (neckName.contains("salve amulet (ei)") || neckName.contains("salve amulet(ei)")) {
                accMult *= 1.20;
                dmgMult *= 1.20;
                salveApplied = true;
                notes.append("Salve (ei) active (+20% ranged acc/dmg). ");
            } else if (neckName.contains("salve amulet (i)") || neckName.contains("salve amulet(i)")) {
                accMult *= 1.15;
                dmgMult *= 1.15;
                salveApplied = true;
                notes.append("Salve (i) active (+15% ranged acc/dmg). ");
            }
        }

        if (!salveApplied && onSlayerTask && helm != null) {
            String helmName = helm.getName().toLowerCase();
            if (helmName.contains("slayer helmet (i)") || helmName.contains("slayer helm (i)") || helmName.contains("black mask (i)")) {
                accMult *= 1.15;
                dmgMult *= 1.15;
                notes.append("Slayer helm (i) active (+15% ranged acc/dmg). ");
            }
        }

        // 2. Void Knight Ranged
        if (isFullVoid(equipment, "ranged")) {
            boolean isElite = isEliteVoid(equipment);
            accMult *= 1.10;
            dmgMult *= (isElite ? 1.125 : 1.10);
            notes.append(isElite ? "Elite Void Ranged (+10% acc, +12.5% dmg). " : "Void Ranged (+10% acc/dmg). ");
        }

        // 3. Crystal Armour with Bowfa
        if (weapon != null && weapon.getName().toLowerCase().contains("faerdhinen")) {
            EquipmentItem body = equipment.get(EquipmentSlot.BODY);
            EquipmentItem legs = equipment.get(EquipmentSlot.LEGS);
            EquipmentItem head = equipment.get(EquipmentSlot.HEAD);

            double crystalAtk = 1.0;
            double crystalStr = 1.0;
            if (body != null && body.getName().contains("Crystal")) { crystalAtk += 0.15; crystalStr += 0.075; }
            if (legs != null && legs.getName().contains("Crystal")) { crystalAtk += 0.10; crystalStr += 0.050; }
            if (head != null && head.getName().contains("Crystal")) { crystalAtk += 0.05; crystalStr += 0.025; }

            accMult *= crystalAtk;
            dmgMult *= crystalStr;
            notes.append(String.format("Crystal armour scaling (Atk: +%.1f%%, Dmg: +%.1f%%). ", (crystalAtk - 1.0) * 100, (crystalStr - 1.0) * 100));
        }

        // 4. Weapon Target Multipliers
        if (weapon != null && profile != null) {
            String weaponName = weapon.getName().toLowerCase();

            // Dragonbane (DHCB)
            if (profile.isDragon() && weapon.isDragonbane()) {
                accMult *= 1.30;
                dmgMult *= 1.30;
                notes.append("Dragon hunter crossbow (+30% acc/dmg). ");
            }

            // Demonbane (Scorching bow)
            if (profile.isDemon() && (weapon.isDemonbane() || weaponName.contains("scorching"))) {
                accMult *= 1.30;
                dmgMult *= 1.30;
                notes.append("Scorching bow (+30% acc/dmg). ");
            }

            // Wilderness (Webweaver bow)
            if (profile.isWilderness() && weapon.isWildernessBonus()) {
                accMult *= 1.50;
                dmgMult *= 1.50;
                notes.append("Webweaver bow wildy buff (+50% acc/dmg). ");
            }

            // Ratbane
            if (profile.isRat() && weapon.isRatbane()) {
                flatBonus += 10;
                notes.append("Bone shortbow (+10 flat max hit). ");
            }
        }

        return new CombatMultipliers(accMult, dmgMult, flatBonus, notes.toString().trim());
    }

    public CombatMultipliers getMagicMultipliers(
            Map<EquipmentSlot, EquipmentItem> equipment,
            MonsterCombatProfile profile,
            boolean onSlayerTask) {

        double accMult = 1.0;
        double dmgMult = 1.0;
        int flatBonus = 0;
        StringBuilder notes = new StringBuilder();

        EquipmentItem weapon = equipment.get(EquipmentSlot.WEAPON);
        EquipmentItem neck = equipment.get(EquipmentSlot.AMULET);
        EquipmentItem helm = equipment.get(EquipmentSlot.HEAD);

        // 1. Salve vs Slayer
        boolean salveApplied = false;
        if (profile != null && profile.isUndead() && neck != null) {
            String neckName = neck.getName().toLowerCase();
            if (neckName.contains("salve amulet (ei)") || neckName.contains("salve amulet(ei)")) {
                accMult *= 1.20;
                dmgMult *= 1.20;
                salveApplied = true;
                notes.append("Salve (ei) active (+20% magic acc/dmg). ");
            } else if (neckName.contains("salve amulet (i)") || neckName.contains("salve amulet(i)")) {
                accMult *= 1.15;
                dmgMult *= 1.15;
                salveApplied = true;
                notes.append("Salve (i) active (+15% magic acc/dmg). ");
            }
        }

        if (!salveApplied && onSlayerTask && helm != null) {
            String helmName = helm.getName().toLowerCase();
            if (helmName.contains("slayer helmet (i)") || helmName.contains("slayer helm (i)") || helmName.contains("black mask (i)")) {
                accMult *= 1.15;
                dmgMult *= 1.15;
                notes.append("Slayer helm (i) active (+15% magic acc/dmg). ");
            }
        }

        // 2. Void Knight Magic
        if (isFullVoid(equipment, "magic")) {
            boolean isElite = isEliteVoid(equipment);
            accMult *= 1.45;
            dmgMult *= (isElite ? 1.025 : 1.0);
            notes.append(isElite ? "Elite Void Magic (+45% acc, +2.5% dmg). " : "Void Magic (+45% acc). ");
        }

        // 3. Weapon Specifics (Purging staff, Accursed sceptre)
        if (weapon != null && profile != null) {
            String weaponName = weapon.getName().toLowerCase();
            if (profile.isDemon() && (weapon.isDemonbane() || weaponName.contains("purging"))) {
                accMult *= 1.30;
                dmgMult *= 1.30;
                notes.append("Purging staff (+30% acc/dmg vs demons). ");
            }
            if (profile.isWilderness() && weapon.isWildernessBonus()) {
                accMult *= 1.50;
                dmgMult *= 1.50;
                notes.append("Accursed sceptre wildy buff (+50% acc/dmg). ");
            }
            if (profile.isRat() && weapon.isRatbane()) {
                flatBonus += 10;
                notes.append("Bone staff (+10 flat max hit). ");
            }
        }

        return new CombatMultipliers(accMult, dmgMult, flatBonus, notes.toString().trim());
    }

    private boolean isFullVoid(Map<EquipmentSlot, EquipmentItem> equipment, String style) {
        EquipmentItem body = equipment.get(EquipmentSlot.BODY);
        EquipmentItem legs = equipment.get(EquipmentSlot.LEGS);
        EquipmentItem gloves = equipment.get(EquipmentSlot.GLOVES);
        EquipmentItem helm = equipment.get(EquipmentSlot.HEAD);

        if (body == null || legs == null || gloves == null || helm == null) return false;

        boolean hasBody = body.getName().contains("Void knight top") || body.getName().contains("Elite void top");
        boolean hasLegs = legs.getName().contains("Void knight robe") || legs.getName().contains("Elite void robe");
        boolean hasGloves = gloves.getName().contains("Void knight gloves");

        if (!hasBody || !hasLegs || !hasGloves) return false;

        String helmName = helm.getName().toLowerCase();
        if ("melee".equalsIgnoreCase(style)) return helmName.contains("void melee helm");
        if ("ranged".equalsIgnoreCase(style)) return helmName.contains("void ranger helm");
        if ("magic".equalsIgnoreCase(style)) return helmName.contains("void mage helm");

        return false;
    }

    private boolean isEliteVoid(Map<EquipmentSlot, EquipmentItem> equipment) {
        EquipmentItem body = equipment.get(EquipmentSlot.BODY);
        EquipmentItem legs = equipment.get(EquipmentSlot.LEGS);
        return body != null && legs != null &&
               body.getName().contains("Elite void top") &&
               legs.getName().contains("Elite void robe");
    }
}

package com.bosswise.service;

import com.bosswise.model.WikiMetadata;
import com.bosswise.model.WikiMetadata.VerificationStatus;
import com.google.gson.Gson;
import java.io.IOException;
import java.io.Reader;
import java.io.Writer;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.AtomicInteger;
import java.util.stream.Stream;
import javax.inject.Inject;
import javax.inject.Singleton;
import net.runelite.client.util.Filepath;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class WikiCacheService {
    private static final Logger log = LoggerFactory.getLogger(WikiCacheService.class);
    private static final long DEFAULT_TTL_MS = 7L * 24 * 60 * 60 * 1000L; // 7 days

    private final Map<String, CacheEntry> memoryCache = new ConcurrentHashMap<>();
    private volatile Filepath diskCacheDir;
    private final Gson gson;

    private final AtomicInteger cacheHits = new AtomicInteger(0);
    private final AtomicInteger cacheMisses = new AtomicInteger(0);

    public static class CacheEntry {
        public String key;
        public String content;
        public long timestamp;
        public long ttlMs;
        public String revisionId;
        public String sourceUrl;
        public double confidence;

        public CacheEntry() {}

        public CacheEntry(String key, String content, long ttlMs, String revisionId, String sourceUrl, double confidence) {
            this.key = key;
            this.content = content;
            this.timestamp = System.currentTimeMillis();
            this.ttlMs = ttlMs;
            this.revisionId = revisionId;
            this.sourceUrl = sourceUrl;
            this.confidence = confidence;
        }

        public boolean isExpired() {
            return (System.currentTimeMillis() - timestamp) > ttlMs;
        }
    }

    @Inject
    public WikiCacheService(Gson gson) {
        this.gson = gson != null ? gson.newBuilder().setPrettyPrinting().create() : null;
    }

    public WikiCacheService(Filepath cacheDir, Gson gson) {
        this.gson = gson != null ? gson.newBuilder().setPrettyPrinting().create() : null;
        setCacheDir(cacheDir);
    }

    public void setCacheDir(Filepath cacheDir) {
        this.diskCacheDir = cacheDir;
        if (cacheDir != null) {
            try {
                if (!cacheDir.exists()) {
                    cacheDir.createDirectories();
                }
            } catch (Exception ex) {
                log.warn("[BossWise] Could not create wiki cache dir: {}", ex.getMessage());
            }
        }
    }

    public String get(String rawKey) {
        if (rawKey == null) return null;
        String key = sanitizeKey(rawKey);

        // 1. Check memory cache
        CacheEntry entry = memoryCache.get(key);
        if (entry != null) {
            if (!entry.isExpired()) {
                cacheHits.incrementAndGet();
                return entry.content;
            } else {
                memoryCache.remove(key);
            }
        }

        // 2. Check disk cache
        Filepath dir = diskCacheDir;
        if (gson != null && dir != null && dir.exists()) {
            Filepath file = dir.joinSegment(key + ".json");
            if (file.exists() && file.isFile()) {
                try (Reader reader = file.openReader()) {
                    CacheEntry diskEntry = gson.fromJson(reader, CacheEntry.class);
                    if (diskEntry != null && !diskEntry.isExpired()) {
                        memoryCache.put(key, diskEntry);
                        cacheHits.incrementAndGet();
                        return diskEntry.content;
                    } else {
                        file.deleteIfExists();
                    }
                } catch (Exception ex) {
                    log.debug("[BossWise] Error reading disk cache for {}: {}", key, ex.getMessage());
                }
            }
        }

        cacheMisses.incrementAndGet();
        return null;
    }

    public void put(String rawKey, String content, String revisionId, String sourceUrl, double confidence) {
        if (rawKey == null || content == null) return;
        String key = sanitizeKey(rawKey);
        CacheEntry entry = new CacheEntry(key, content, DEFAULT_TTL_MS, revisionId, sourceUrl, confidence);

        memoryCache.put(key, entry);

        Filepath dir = diskCacheDir;
        if (gson != null && dir != null && dir.exists()) {
            try {
                Filepath file = dir.joinSegment(key + ".json");
                try (Writer writer = file.openWriter()) {
                    gson.toJson(entry, writer);
                }
            } catch (Exception ex) {
                log.debug("[BossWise] Failed to persist wiki entry {}: {}", key, ex.getMessage());
            }
        }
    }

    public WikiMetadata getMetadata(String rawKey) {
        String key = sanitizeKey(rawKey);
        CacheEntry entry = memoryCache.get(key);
        if (entry != null) {
            return new WikiMetadata(
                    entry.sourceUrl != null ? entry.sourceUrl : "https://oldschool.runescape.wiki/w/" + rawKey,
                    entry.timestamp,
                    entry.isExpired() ? VerificationStatus.PARTIALLY_VERIFIED : VerificationStatus.VERIFIED,
                    entry.confidence,
                    entry.revisionId != null ? entry.revisionId : "cached",
                    "Loaded from BossWise local cache"
            );
        }
        return WikiMetadata.offlineFallback(rawKey);
    }

    public void clear() {
        memoryCache.clear();
        Filepath dir = diskCacheDir;
        if (dir != null && dir.exists()) {
            try (Stream<Filepath> entries = dir.walk(1)) {
                entries.filter(p -> p.isFile() && p.getFileName().endsWith(".json"))
                        .forEach(p -> {
                            try {
                                p.deleteIfExists();
                            } catch (IOException ignored) {}
                        });
            } catch (IOException ex) {
                log.debug("[BossWise] Error clearing disk cache: {}", ex.getMessage());
            }
        }
    }

    public int getCacheHits() { return cacheHits.get(); }
    public int getCacheMisses() { return cacheMisses.get(); }
    public int getMemoryCacheSize() { return memoryCache.size(); }

    private String sanitizeKey(String key) {
        return key.toLowerCase().trim().replaceAll("[^a-z0-9_-]", "_");
    }
}

package com.bosswise.service;

import com.bosswise.db.EquipmentDatabase;
import com.bosswise.db.MonsterDatabase;
import com.bosswise.model.EquipmentItem;
import com.bosswise.model.MonsterCombatProfile;
import com.bosswise.model.MonsterData;
import com.bosswise.model.WikiMetadata;
import com.bosswise.model.WikiMetadata.VerificationStatus;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.io.IOException;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.Map;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import java.util.regex.Matcher;
import java.util.regex.Pattern;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.Call;
import okhttp3.Callback;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class WikiDataService {
    private static final Logger log = LoggerFactory.getLogger(WikiDataService.class);
    private static final String WIKI_API_ENDPOINT = "https://oldschool.runescape.wiki/api.php";
    public static final String USER_AGENT = "BossWise-RuneLite-Plugin/1.0.0 (https://github.com/WizardOfAus666/bosswise)";

    private final OkHttpClient httpClient;
    private final WikiCacheService cacheService;
    private final EquipmentDatabase equipmentDatabase;
    private final MonsterDatabase monsterDatabase;
    private final ScheduledExecutorService scheduler;

    private long nextRequestTime = 0L;
    private static final long MIN_REQUEST_INTERVAL_MS = 500L; // 2 requests per second maximum

    @Inject
    public WikiDataService(
            OkHttpClient httpClient,
            WikiCacheService cacheService,
            EquipmentDatabase equipmentDatabase,
            MonsterDatabase monsterDatabase,
            ScheduledExecutorService scheduler) {
        this.httpClient = httpClient;
        this.cacheService = cacheService;
        this.equipmentDatabase = equipmentDatabase;
        this.monsterDatabase = monsterDatabase;
        this.scheduler = scheduler;
    }

    /**
     * Asynchronously query monster information from the OSRS Wiki.
     * Returns cached or bundled baseline on failure/offline.
     */
    public CompletableFuture<MonsterCombatProfile> fetchMonsterProfile(String monsterName) {
        CompletableFuture<MonsterCombatProfile> future = new CompletableFuture<>();

        if (monsterName == null || monsterName.trim().isEmpty()) {
            future.complete(null);
            return future;
        }

        // 1. Check local cache
        String cacheKey = "monster_" + monsterName;
        String cachedWikitext = cacheService.get(cacheKey);
        if (cachedWikitext != null) {
            MonsterCombatProfile profile = parseMonsterWikitext(monsterName, cachedWikitext);
            if (profile != null) {
                future.complete(profile);
                return future;
            }
        }

        // 2. Fetch asynchronously via ScheduledExecutorService (rate-limited without blocking)
        if (scheduler == null || httpClient == null) {
            future.complete(getFallbackMonsterProfile(monsterName));
            return future;
        }
        long delayMs = reserveDelayMs();
        scheduler.schedule(() -> {
            try {
                String url = WIKI_API_ENDPOINT + "?action=parse&prop=wikitext&page="
                        + URLEncoder.encode(monsterName, StandardCharsets.UTF_8)
                        + "&format=json";

                Request request = new Request.Builder()
                        .url(url)
                        .header("User-Agent", USER_AGENT)
                        .header("Accept", "application/json")
                        .build();

                httpClient.newCall(request).enqueue(new Callback() {
                    @Override
                    public void onFailure(Call call, IOException e) {
                        log.debug("[BossWise] Wiki fetch failed for {}: {}", monsterName, e.getMessage());
                        future.complete(getFallbackMonsterProfile(monsterName));
                    }

                    @Override
                    public void onResponse(Call call, Response response) {
                        try {
                            if (!response.isSuccessful() || response.body() == null) {
                                future.complete(getFallbackMonsterProfile(monsterName));
                                return;
                            }

                            String jsonString = response.body().string();
                            JsonObject json = new JsonParser().parse(jsonString).getAsJsonObject();
                            if (json.has("parse") && json.getAsJsonObject("parse").has("wikitext")) {
                                String wikitext = json.getAsJsonObject("parse")
                                        .getAsJsonObject("wikitext")
                                        .get("*").getAsString();

                                cacheService.put(
                                        cacheKey,
                                        wikitext,
                                        "live-fetch",
                                        "https://oldschool.runescape.wiki/w/" + URLEncoder.encode(monsterName, StandardCharsets.UTF_8),
                                        1.0
                                );

                                MonsterCombatProfile profile = parseMonsterWikitext(monsterName, wikitext);
                                future.complete(profile != null ? profile : getFallbackMonsterProfile(monsterName));
                            } else {
                                future.complete(getFallbackMonsterProfile(monsterName));
                            }
                        } catch (Exception ex) {
                            log.debug("[BossWise] Error parsing wiki response for {}: {}", monsterName, ex.getMessage());
                            future.complete(getFallbackMonsterProfile(monsterName));
                        } finally {
                            response.close();
                        }
                    }
                });
            } catch (Exception ex) {
                log.debug("[BossWise] Execution error fetching {}: {}", monsterName, ex.getMessage());
                future.complete(getFallbackMonsterProfile(monsterName));
            }
        }, delayMs, TimeUnit.MILLISECONDS);

        return future;
    }

    /**
     * Fallback to internal bundled MonsterDatabase profile
     */
    public MonsterCombatProfile getFallbackMonsterProfile(String monsterName) {
        if (monsterDatabase != null && monsterName != null) {
            MonsterData data = monsterDatabase.getMonsterByName(monsterName);
            if (data != null && data.getCombatProfile() != null) {
                return data.getCombatProfile();
            }
        }
        String id = monsterName != null ? monsterName.toLowerCase().replace(" ", "_") : "target";
        String name = monsterName != null ? monsterName : "Target";
        return MonsterCombatProfile.builder(id, name, com.bosswise.model.CombatStyle.MELEE).build();
    }

    /**
     * Parse infobox parameters from OSRS Wiki wikitext.
     */
    public MonsterCombatProfile parseMonsterWikitext(String monsterName, String wikitext) {
        if (wikitext == null) return null;

        try {
            boolean isDragon = wikitext.contains("attribute = dragon") || wikitext.contains("attribute = fiery");
            boolean isDemon = wikitext.contains("attribute = demon");
            boolean isUndead = wikitext.contains("attribute = undead");
            boolean isKalphite = wikitext.contains("attribute = kalphite");

            String id = monsterName != null ? monsterName.toLowerCase().replace(" ", "_") : "target";
            String name = monsterName != null ? monsterName : "Target";

            MonsterCombatProfile.Builder builder = MonsterCombatProfile.builder(
                    id,
                    name,
                    com.bosswise.model.CombatStyle.MELEE
            );

            if (isDragon) builder.dragon();
            if (isDemon) builder.demon();
            if (isUndead) builder.undead();
            if (isKalphite) builder.kalphite();

            return builder.build();
        } catch (Exception ex) {
            log.debug("[BossWise] Error parsing monster wikitext: {}", ex.getMessage());
            return null;
        }
    }

    public WikiMetadata getMonsterMetadata(String monsterName) {
        return cacheService.getMetadata("monster_" + monsterName);
    }

    private int extractInt(String wikitext, String param, int defaultValue) {
        Pattern pattern = Pattern.compile("\\|\\s*" + Pattern.quote(param) + "\\s*=\\s*([+-]?\\d+)", Pattern.CASE_INSENSITIVE);
        Matcher matcher = pattern.matcher(wikitext);
        if (matcher.find()) {
            try {
                return Integer.parseInt(matcher.group(1));
            } catch (NumberFormatException ignored) {}
        }
        return defaultValue;
    }

    private synchronized long reserveDelayMs() {
        long now = System.currentTimeMillis();
        long scheduledAt = Math.max(now, nextRequestTime);
        nextRequestTime = scheduledAt + MIN_REQUEST_INTERVAL_MS;
        return scheduledAt - now;
    }
}

package com.bosswise.service;

import com.bosswise.db.MonsterStrategyDatabase;
import com.bosswise.model.strategy.MonsterStrategy;
import com.bosswise.model.strategy.StrategyConfidence;
import com.google.gson.JsonObject;
import com.google.gson.JsonParser;
import java.net.URLEncoder;
import java.nio.charset.StandardCharsets;
import java.util.concurrent.CompletableFuture;
import java.util.concurrent.ScheduledExecutorService;
import java.util.concurrent.TimeUnit;
import javax.inject.Inject;
import javax.inject.Singleton;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import org.slf4j.Logger;
import org.slf4j.LoggerFactory;

@Singleton
public class WikiStrategyRefreshService {
    private static final Logger log = LoggerFactory.getLogger(WikiStrategyRefreshService.class);
    private static final String WIKI_API_ENDPOINT = "https://oldschool.runescape.wiki/api.php";
    private static final String USER_AGENT = WikiDataService.USER_AGENT;

    private final OkHttpClient httpClient;
    private final WikiCacheService cacheService;
    private final MonsterStrategyDatabase strategyDatabase;
    private final ScheduledExecutorService scheduler;

    private long nextRequestTime = 0L;
    private static final long MIN_REQUEST_INTERVAL_MS = 500L;

    @Inject
    public WikiStrategyRefreshService(
            OkHttpClient httpClient,
            WikiCacheService cacheService,
            MonsterStrategyDatabase strategyDatabase,
            ScheduledExecutorService scheduler) {
        this.httpClient = httpClient;
        this.cacheService = cacheService;
        this.strategyDatabase = strategyDatabase;
        this.scheduler = scheduler;
    }

    /**
     * Refresh a monster strategy asynchronously from the OSRS Wiki.
     */
    public CompletableFuture<MonsterStrategy> refreshStrategy(String monsterName) {
        CompletableFuture<MonsterStrategy> future = new CompletableFuture<>();

        if (monsterName == null || monsterName.trim().isEmpty()) {
            future.complete(null);
            return future;
        }

        MonsterStrategy local = strategyDatabase.getStrategyByName(monsterName);
        String cacheKey = "strat_" + monsterName.toLowerCase().replace(" ", "_");

        // Check cache first
        String cached = cacheService.get(cacheKey);
        if (cached != null) {
            future.complete(local);
            return future;
        }

        if (scheduler == null || httpClient == null) {
            future.complete(local);
            return future;
        }
        long delayMs = reserveDelayMs();
        scheduler.schedule(() -> {
            try {
                String pageTitle = monsterName.replace(" ", "_") + "/Strategies";
                String url = WIKI_API_ENDPOINT + "?action=parse&prop=wikitext&page="
                        + URLEncoder.encode(pageTitle, StandardCharsets.UTF_8)
                        + "&format=json";

                Request request = new Request.Builder()
                        .url(url)
                        .header("User-Agent", USER_AGENT)
                        .header("Accept", "application/json")
                        .build();

                try (Response response = httpClient.newCall(request).execute()) {
                    if (response.isSuccessful() && response.body() != null) {
                        String body = response.body().string();
                        JsonObject json = new JsonParser().parse(body).getAsJsonObject();

                        if (json.has("parse") && json.getAsJsonObject("parse").has("wikitext")) {
                            String wikitext = json.getAsJsonObject("parse")
                                    .getAsJsonObject("wikitext")
                                    .get("*").getAsString();

                            cacheService.put(
                                    cacheKey,
                                    wikitext,
                                    "live-wiki-refresh",
                                    "https://oldschool.runescape.wiki/w/" + pageTitle,
                                    1.0
                            );
                            log.info("[BossWise] Successfully refreshed strategy from Wiki for {}", monsterName);
                        }
                    }
                } catch (Exception ex) {
                    log.debug("[BossWise] Wiki strategy fetch failed for {}: {}", monsterName, ex.getMessage());
                }

                // Return local strategy (preserved last-known-good)
                future.complete(local);
            } catch (Exception e) {
                log.debug("[BossWise] Exception during wiki strategy refresh: {}", e.getMessage());
                future.complete(local);
            }
        }, delayMs, TimeUnit.MILLISECONDS);

        return future;
    }

    private synchronized long reserveDelayMs() {
        long now = System.currentTimeMillis();
        long scheduledAt = Math.max(now, nextRequestTime);
        nextRequestTime = scheduledAt + MIN_REQUEST_INTERVAL_MS;
        return scheduledAt - now;
    }
}

