import com.bosswise.service.ProgressionService;
import com.bosswise.ui.components.GoldButton;
import com.bosswise.ui.components.ScrollablePanel;
import com.bosswise.ui.components.StatProgressBar;
import com.bosswise.ui.components.VerticalPanel;
import com.bosswise.ui.components.WrapText;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.ArrayList;
import java.util.Collections;
import java.util.HashSet;
import java.util.List;
import java.util.Map;
import java.util.Set;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;

public class ProgressionPanel extends JPanel {
    private final AccountScannerService accountScanner;
    private final ProgressionService progressionService;
    private final GearRoadmapService gearRoadmapService;
    private final CombatAchievementService combatAchievementService;
    private final CollectionLogService collectionLogService;
    private final CurrentGearScannerService currentGearScanner;

    private final ScrollablePanel goalsContainer = new ScrollablePanel();
    private final Set<String> markedComplete = new HashSet<>();

    private String currentSubTab = "UNLOCKS"; // UNLOCKS, GEAR, ACHIEVEMENTS, LOG
    private final List<GoldButton> subTabButtons = new ArrayList<>();

    public ProgressionPanel(AccountScannerService accountScanner, ProgressionService progressionService) {
        this(accountScanner, progressionService,
                new GearRoadmapService(new com.bosswise.db.EquipmentDatabase(), new com.bosswise.service.GearOptimizerService(new com.bosswise.db.EquipmentDatabase(), new com.bosswise.service.GePriceService(null)), new com.bosswise.service.GePriceService(null)),
                new CombatAchievementService(null),
                new CollectionLogService(null),
                new CurrentGearScannerService(null, new com.bosswise.db.EquipmentDatabase(), new com.bosswise.service.GePriceService(null)));
    }

    public ProgressionPanel(
            AccountScannerService accountScanner,
            ProgressionService progressionService,
            GearRoadmapService gearRoadmapService,
            CombatAchievementService combatAchievementService,
            CollectionLogService collectionLogService,
            CurrentGearScannerService currentGearScanner) {

        this.accountScanner = accountScanner;
        this.progressionService = progressionService;
        this.gearRoadmapService = gearRoadmapService;
        this.combatAchievementService = combatAchievementService;
        this.collectionLogService = collectionLogService;
        this.currentGearScanner = currentGearScanner;

        setLayout(new BorderLayout());
        setBackground(BossWiseDesign.BG_DARK);

        JPanel header = new JPanel();
        header.setLayout(new BoxLayout(header, BoxLayout.Y_AXIS));
        header.setBackground(BossWiseDesign.PANEL_BG);
        header.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

        WrapText title = new WrapText("PROGRESSION & GOALS", BossWiseDesign.getHeaderFont(), BossWiseDesign.GOLD);
        header.add(title);

        WrapText sub = new WrapText("Roadmaps, achievements, wishlist & log", BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_MUTED);
        header.add(sub);
        header.add(Box.createRigidArea(new Dimension(0, 6)));

        // Sub-tabs row
        JPanel tabRow = new JPanel(new GridLayout(1, 4, 2, 0));
        tabRow.setOpaque(false);
        addSubTabBtn(tabRow, "Unlocks", "UNLOCKS");
        addSubTabBtn(tabRow, "Gear", "GEAR");
        addSubTabBtn(tabRow, "CA Tiers", "ACHIEVEMENTS");
        addSubTabBtn(tabRow, "Coll Log", "LOG");
        header.add(tabRow);

        add(header, BorderLayout.NORTH);

        goalsContainer.setLeftAlignChildren(true);
        goalsContainer.setLayout(new BoxLayout(goalsContainer, BoxLayout.Y_AXIS));
        goalsContainer.setBackground(BossWiseDesign.BG_DARK);
        goalsContainer.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

        JScrollPane scroll = new JScrollPane(goalsContainer);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setBackground(BossWiseDesign.BG_DARK);
        scroll.getViewport().setBackground(BossWiseDesign.BG_DARK);

        add(scroll, BorderLayout.CENTER);

        refreshRoadmap();
    }

    private void addSubTabBtn(JPanel parent, String label, String tabKey) {
        GoldButton btn = new GoldButton(label);
        btn.setFont(BossWiseDesign.getBadgeFont());
        btn.setPreferredSize(new Dimension(50, 22));
        btn.setMargin(new java.awt.Insets(1, 1, 1, 1));
        btn.setActive(this.currentSubTab.equalsIgnoreCase(tabKey));
        btn.addActionListener(e -> {
            this.currentSubTab = tabKey;
            for (GoldButton b : subTabButtons) {
                b.setActive(b == btn);
            }
            refreshRoadmap();
        });
        subTabButtons.add(btn);
        parent.add(btn);
    }

    public void refreshRoadmap() {
        goalsContainer.removeAll();

        PlayerAccount account = (accountScanner != null) ? accountScanner.getCurrentAccount() : PlayerAccount.createDefault();
        if (account == null) account = PlayerAccount.createDefault();

        switch (currentSubTab.toUpperCase()) {
            case "GEAR":
                renderGearRoadmap(account);
                break;
            case "ACHIEVEMENTS":
                renderCombatAchievements();
                break;
            case "LOG":
                renderCollectionLog();
                break;
            case "UNLOCKS":
            default:
                renderBossUnlocks(account);
                break;
        }

        goalsContainer.revalidate();
        goalsContainer.repaint();
    }

    private void renderBossUnlocks(PlayerAccount account) {
        List<ProgressionGoal> goals = progressionService.generateRoadmap(account);
        if (goals.isEmpty()) {
            JLabel empty = new JLabel("All major boss prerequisites completed!", JLabel.CENTER);
            empty.setFont(BossWiseDesign.getHeaderFont());
            empty.setForeground(BossWiseDesign.STATUS_READY);
            empty.setAlignmentX(CENTER_ALIGNMENT);
            goalsContainer.add(empty);
            return;
        }

        int index = 1;
        for (ProgressionGoal goal : goals) {
            VerticalPanel card = new VerticalPanel();
            card.setBackground(BossWiseDesign.CARD_BG);
            card.setBorder(BossWiseDesign.BORDER_CARD_SLIM);

            JPanel top = new JPanel(new BorderLayout(4, 0));
            top.setOpaque(false);
            WrapText numLbl = new WrapText(index++ + ". " + goal.getTitle(), BossWiseDesign.getBoldFont(), markedComplete.contains(goal.getId()) ? BossWiseDesign.TEXT_MUTED : BossWiseDesign.TEXT_PRIMARY);
            top.add(numLbl, BorderLayout.CENTER);

            JCheckBox check = new JCheckBox();
            check.setOpaque(false);
            check.setSelected(markedComplete.contains(goal.getId()));
            check.addActionListener(e -> {
                if (check.isSelected()) markedComplete.add(goal.getId());
                else markedComplete.remove(goal.getId());
                refreshRoadmap();
            });
            top.add(check, BorderLayout.EAST);
            card.add(top);
            card.add(Box.createVerticalStrut(2));

            WrapText descLbl = new WrapText(goal.getDescription(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
            card.add(descLbl);
            card.add(Box.createVerticalStrut(4));

            StatProgressBar bar = new StatProgressBar(goal.getCurrentProgress(), goal.getTargetProgress());
            if (markedComplete.contains(goal.getId())) {
                bar.setFillColor(BossWiseDesign.STATUS_READY);
            }
            card.add(bar);

            goalsContainer.add(card);
            goalsContainer.add(Box.createVerticalStrut(6));
        }
    }

    private void renderGearRoadmap(PlayerAccount account) {
        // Savings Goal Progress Card
        if (gearRoadmapService != null) {
            VerticalPanel goalCard = new VerticalPanel();
            goalCard.setBackground(BossWiseDesign.CARD_BG);
            goalCard.setBorder(BossWiseDesign.BORDER_GOLD);

            JLabel gTitle = new JLabel("SAVINGS GOAL: " + gearRoadmapService.getSavingsGoalTargetName().toUpperCase());
            gTitle.setFont(BossWiseDesign.getBoldFont());
            gTitle.setForeground(BossWiseDesign.GOLD);
            goalCard.add(gTitle);
            goalCard.add(Box.createVerticalStrut(2));

            long goalGp = gearRoadmapService.getSavingsGoalGp();
            long currentGp = 6_500_000L; // sample account balance or configurable
            double prog = gearRoadmapService.getSavingsProgress(currentGp);
            JLabel progLbl = new JLabel(String.format("Saved: %s / %s GP (%.0f%%)",
                    formatGp(currentGp), formatGp(goalGp), prog * 100.0));
            progLbl.setFont(BossWiseDesign.getSmallFont());
            progLbl.setForeground(BossWiseDesign.STATUS_READY);
            goalCard.add(progLbl);
            goalCard.add(Box.createVerticalStrut(4));

            StatProgressBar bar = new StatProgressBar((int) (currentGp / 1000), (int) (goalGp / 1000));
            bar.setFillColor(BossWiseDesign.GOLD);
            goalCard.add(bar);

            goalsContainer.add(goalCard);
            goalsContainer.add(Box.createVerticalStrut(6));

            // Ranked Gear Upgrade Steps (Feature 9)
            Map<com.bosswise.model.EquipmentSlot, EquipmentItem> curGear = (currentGearScanner != null)
                    ? currentGearScanner.getCurrentEquipment()
                    : Collections.emptyMap();

            List<GearRoadmapStep> steps = gearRoadmapService.generateRoadmap(account, curGear, CombatStyle.MELEE, null);
            for (GearRoadmapStep step : steps) {
                VerticalPanel stepCard = new VerticalPanel();
                stepCard.setBackground(BossWiseDesign.CARD_BG);
                stepCard.setBorder(BossWiseDesign.BORDER_CARD_SLIM);

                JPanel top = new JPanel(new BorderLayout(4, 0));
                top.setOpaque(false);
                JLabel rankLbl = new JLabel("#" + step.getPriorityRank() + " " + step.getSlot().getDisplayName().toUpperCase());
                rankLbl.setFont(BossWiseDesign.getBadgeFont());
                rankLbl.setForeground(BossWiseDesign.GOLD);
                top.add(rankLbl, BorderLayout.WEST);

                JLabel cost = new JLabel("+" + step.getFormattedUpgradeCost());
                cost.setFont(BossWiseDesign.getBoldFont());
                cost.setForeground(step.isCanEquipNow() ? BossWiseDesign.STATUS_READY : BossWiseDesign.STATUS_ALMOST);
                top.add(cost, BorderLayout.EAST);
                stepCard.add(top);
                stepCard.add(Box.createVerticalStrut(2));

                WrapText title = new WrapText(step.getCurrentItem().getName() + " \u2192 " + step.getSuggestedItem().getName(),
                        BossWiseDesign.getBoldFont(), BossWiseDesign.TEXT_PRIMARY);
                stepCard.add(title);
                stepCard.add(Box.createVerticalStrut(2));

                WrapText reason = new WrapText(step.getReason(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
                stepCard.add(reason);

                if (!step.getRequirements().isEmpty()) {
                    WrapText reqs = new WrapText("Requires: " + String.join(", ", step.getRequirements()),
                            BossWiseDesign.getSmallFont(), BossWiseDesign.STATUS_LOCKED);
                    stepCard.add(reqs);
                }

                goalsContainer.add(stepCard);
                goalsContainer.add(Box.createVerticalStrut(6));
            }
        }
    }

    private void renderCombatAchievements() {
        if (combatAchievementService == null) return;

        // Tiers Progress Overview Card
        VerticalPanel progCard = new VerticalPanel();
        progCard.setBackground(BossWiseDesign.CARD_BG);
        progCard.setBorder(BossWiseDesign.BORDER_GOLD);

        JLabel caTitle = new JLabel("COMBAT ACHIEVEMENTS: " + String.format("%.0f%% COMPLETE", combatAchievementService.getTotalCompletionPercent()));
        caTitle.setFont(BossWiseDesign.getBoldFont());
        caTitle.setForeground(BossWiseDesign.GOLD);
        progCard.add(caTitle);
        progCard.add(Box.createVerticalStrut(4));

        for (CaTier tier : CaTier.values()) {
            double pct = combatAchievementService.getTierCompletionPercent(tier);
            JLabel tLbl = new JLabel(String.format("%s: %.0f%%", tier.getDisplayName(), pct));
            tLbl.setFont(BossWiseDesign.getSmallFont());
            tLbl.setForeground(Color.decode(tier.getHexColor()));
            progCard.add(tLbl);
        }
        goalsContainer.add(progCard);
        goalsContainer.add(Box.createVerticalStrut(6));

        // Task List
        for (CombatAchievementTask task : combatAchievementService.getAllTasks()) {
            VerticalPanel card = new VerticalPanel();
            card.setBackground(BossWiseDesign.CARD_BG);
            card.setBorder(BossWiseDesign.BORDER_CARD_SLIM);

            JPanel top = new JPanel(new BorderLayout(4, 0));
            top.setOpaque(false);
            JLabel name = new JLabel(task.getBossName() + ": " + task.getTaskName());
            name.setFont(BossWiseDesign.getBoldFont());
            name.setForeground(Color.decode(task.getTier().getHexColor()));
            top.add(name, BorderLayout.CENTER);

            JCheckBox chk = new JCheckBox();
            chk.setOpaque(false);
            chk.setSelected(task.isCompleted());
            chk.addActionListener(e -> {
                combatAchievementService.setTaskCompleted(task.getTaskName(), chk.isSelected());
                refreshRoadmap();
            });
            top.add(chk, BorderLayout.EAST);
            card.add(top);
            card.add(Box.createVerticalStrut(2));

            WrapText desc = new WrapText(task.getDescription(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
            card.add(desc);

            if (!task.getStrategyTip().isEmpty()) {
                WrapText tip = new WrapText("Tip: " + task.getStrategyTip(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_MUTED);
                card.add(tip);
            }

            goalsContainer.add(card);
            goalsContainer.add(Box.createVerticalStrut(4));
        }
    }

    private void renderCollectionLog() {
        if (collectionLogService == null) return;

        VerticalPanel logCard = new VerticalPanel();
        logCard.setBackground(BossWiseDesign.CARD_BG);
        logCard.setBorder(BossWiseDesign.BORDER_GOLD);

        JLabel lTitle = new JLabel("COLLECTION LOG: " + String.format("%.0f%% COMPLETED", collectionLogService.getTotalCompletionPercent()));
        lTitle.setFont(BossWiseDesign.getBoldFont());
        lTitle.setForeground(BossWiseDesign.GOLD);
        logCard.add(lTitle);
        logCard.add(Box.createVerticalStrut(2));

        JLabel count = new JLabel(collectionLogService.getTotalObtainedCount() + " / " + collectionLogService.getAllEntries().size() + " Uniques Unlocked");
        count.setFont(BossWiseDesign.getSmallFont());
        count.setForeground(BossWiseDesign.STATUS_READY);
        logCard.add(count);

        goalsContainer.add(logCard);
        goalsContainer.add(Box.createVerticalStrut(6));

        for (CollectionLogEntry entry : collectionLogService.getAllEntries()) {
            JPanel card = new JPanel(new BorderLayout(4, 0));
            card.setBackground(BossWiseDesign.CARD_BG);
            card.setBorder(BossWiseDesign.BORDER_CARD_SLIM);
            card.setMaximumSize(new Dimension(BossWiseDesign.USABLE_WIDTH, 42));

            JPanel left = new JPanel();
            left.setLayout(new BoxLayout(left, BoxLayout.Y_AXIS));
            left.setOpaque(false);

            JLabel name = new JLabel(entry.getItemName());
            name.setFont(BossWiseDesign.getBoldFont());
            name.setForeground(entry.isObtained() ? BossWiseDesign.STATUS_READY : BossWiseDesign.TEXT_PRIMARY);
            left.add(name);

            JLabel sub = new JLabel(entry.getEncounterName() + " (" + entry.getDropRate() + ")");
            sub.setFont(BossWiseDesign.getSmallFont());
            sub.setForeground(BossWiseDesign.TEXT_MUTED);
            left.add(sub);
            card.add(left, BorderLayout.CENTER);

            JCheckBox chk = new JCheckBox();
            chk.setOpaque(false);
            chk.setSelected(entry.isObtained());
            chk.addActionListener(e -> {
                collectionLogService.setItemObtained(entry.getItemName(), chk.isSelected());
                refreshRoadmap();
            });
            card.add(chk, BorderLayout.EAST);

            goalsContainer.add(card);
            goalsContainer.add(Box.createVerticalStrut(4));
        }
    }

    private String formatGp(long amount) {
        if (amount >= 1_000_000) return String.format("%.1fM", amount / 1_000_000.0);
        if (amount >= 1_000) return String.format("%dK", amount / 1_000);
        return String.valueOf(amount);
    }
}

package com.bosswise.ui;

import com.bosswise.config.BossWiseConfig;
import com.bosswise.scanner.AccountScannerService;
import com.bosswise.ui.components.GoldButton;
import com.bosswise.ui.components.ScrollablePanel;
import com.bosswise.ui.components.VerticalPanel;
import com.bosswise.ui.components.WrapText;
import java.awt.BorderLayout;
import java.awt.Dimension;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JCheckBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.ScrollPaneConstants;

public class SettingsPanel extends JPanel {
    private final BossWiseConfig config;
    private final AccountScannerService accountScanner;
    private final Runnable onSettingsChanged;

    public SettingsPanel(BossWiseConfig config, AccountScannerService accountScanner, Runnable onSettingsChanged) {
        this.config = config;
        this.accountScanner = accountScanner;
        this.onSettingsChanged = onSettingsChanged;

        setLayout(new BorderLayout());
        setBackground(BossWiseDesign.BG_DARK);

        ScrollablePanel content = new ScrollablePanel();
        content.setLeftAlignChildren(true);
        content.setLayout(new BoxLayout(content, BoxLayout.Y_AXIS));
        content.setBackground(BossWiseDesign.BG_DARK);
        content.setBorder(BorderFactory.createEmptyBorder(6, 6, 6, 6));

        // Header
        JLabel title = new JLabel("BOSSWISE SETTINGS");
        title.setFont(BossWiseDesign.getHeaderFont());
        title.setForeground(BossWiseDesign.GOLD);
        content.add(title);
        content.add(Box.createRigidArea(new Dimension(0, 6)));

        // Action: Scan Account Now
        VerticalPanel scanCard = new VerticalPanel();
        scanCard.setBackground(BossWiseDesign.CARD_BG);
        scanCard.setBorder(BossWiseDesign.BORDER_CARD);

        JLabel scanTitle = new JLabel("ACCOUNT SCAN");
        scanTitle.setFont(BossWiseDesign.getHeaderFont());
        scanTitle.setForeground(BossWiseDesign.GOLD);
        scanCard.add(scanTitle);
        scanCard.add(Box.createVerticalStrut(3));

        WrapText scanDesc = new WrapText("Instantly re-scan your combat stats and quest states from the active client session.", BossWiseDesign.getRegularFont(), BossWiseDesign.TEXT_SECONDARY);
        scanCard.add(scanDesc);
        scanCard.add(Box.createVerticalStrut(6));

        GoldButton scanBtn = new GoldButton("Scan Now");
        scanBtn.setPreferredSize(new Dimension(85, 26));
        scanBtn.setFont(BossWiseDesign.getBoldFont());
        scanBtn.addActionListener(e -> {
            accountScanner.scanAccount();
            if (onSettingsChanged != null) onSettingsChanged.run();
        });
        scanCard.add(scanBtn);
        content.add(scanCard);
        content.add(Box.createRigidArea(new Dimension(0, 8)));

        // Preferences Card
        VerticalPanel prefCard = new VerticalPanel();
        prefCard.setBackground(BossWiseDesign.CARD_BG);
        prefCard.setBorder(BossWiseDesign.BORDER_CARD);

        JLabel prefTitle = new JLabel("DISPLAY PREFERENCES");
        prefTitle.setFont(BossWiseDesign.getHeaderFont());
        prefTitle.setForeground(BossWiseDesign.GOLD);
        prefCard.add(prefTitle);
        prefCard.add(Box.createVerticalStrut(6));

        JCheckBox showLocked = new JCheckBox("Show Locked Bosses", config.showLockedBosses());
        styleCheck(showLocked);
        prefCard.add(showLocked);
        prefCard.add(Box.createVerticalStrut(4));

        JCheckBox showGroup = new JCheckBox("Show Group / Raid Encounters", config.showGroupBosses());
        styleCheck(showGroup);
        prefCard.add(showGroup);
        prefCard.add(Box.createVerticalStrut(4));

        JCheckBox autoRefresh = new JCheckBox("Auto-Refresh On Stat Changes", config.autoRefreshOnStatChange());
        styleCheck(autoRefresh);
        prefCard.add(autoRefresh);

        content.add(prefCard);
        content.add(Box.createRigidArea(new Dimension(0, 8)));

        // Plugin Hub Compliance Information
        VerticalPanel infoCard = new VerticalPanel();
        infoCard.setBackground(BossWiseDesign.CARD_BG);
        infoCard.setBorder(BossWiseDesign.BORDER_CARD);

        JLabel infoTitle = new JLabel("HUB COMPLIANCE");
        infoTitle.setFont(BossWiseDesign.getHeaderFont());
        infoTitle.setForeground(BossWiseDesign.STATUS_READY);
        infoCard.add(infoTitle);
        infoCard.add(Box.createVerticalStrut(4));

        WrapText compTxt = new WrapText("BossWise is an informational assistant. It does not automate gameplay, perform automated clicks, or alter the game client. All data is retrieved through official RuneLite client APIs.", BossWiseDesign.getRegularFont(), BossWiseDesign.TEXT_SECONDARY);
        infoCard.add(compTxt);

        content.add(infoCard);

        JScrollPane scroll = new JScrollPane(content);
        scroll.setBorder(null);
        scroll.setHorizontalScrollBarPolicy(ScrollPaneConstants.HORIZONTAL_SCROLLBAR_NEVER);
        scroll.setVerticalScrollBarPolicy(ScrollPaneConstants.VERTICAL_SCROLLBAR_AS_NEEDED);
        scroll.getVerticalScrollBar().setUnitIncrement(16);
        scroll.setBackground(BossWiseDesign.BG_DARK);
        scroll.getViewport().setBackground(BossWiseDesign.BG_DARK);

        add(scroll, BorderLayout.CENTER);
    }

    private void styleCheck(JCheckBox cb) {
        cb.setFont(BossWiseDesign.getRegularFont());
        cb.setForeground(BossWiseDesign.TEXT_PRIMARY);
        cb.setOpaque(false);
        cb.setFocusPainted(false);
    }
}

package com.bosswise.ui;

import com.bosswise.model.CombatStyle;
import com.bosswise.model.SlayerTaskInfo;
import com.bosswise.model.SlayerTaskInfo.TaskLocation;
import com.bosswise.service.SlayerTaskService;
import com.bosswise.ui.components.GoldButton;
import com.bosswise.ui.components.StatusBadge;
import com.bosswise.ui.components.VerticalPanel;
import com.bosswise.ui.components.WrapText;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.GridLayout;
import java.util.List;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JComboBox;
import javax.swing.JLabel;
import javax.swing.JPanel;
import javax.swing.JScrollPane;
import javax.swing.JTextField;

public class SlayerPanel extends JPanel {
    private final SlayerTaskService slayerTaskService;

    private final JComboBox<String> taskCombo = new JComboBox<>();
    private final JTextField remainingField = new JTextField("140", 4);
    private final JPanel contentPanel = new VerticalPanel();

    public SlayerPanel(SlayerTaskService slayerTaskService) {
        this.slayerTaskService = slayerTaskService;

        setLayout(new BorderLayout());
        setBackground(BossWiseDesign.BG_DARK);

        JPanel topContainer = new JPanel();
        topContainer.setLayout(new BoxLayout(topContainer, BoxLayout.Y_AXIS));
        topContainer.setBackground(BossWiseDesign.PANEL_BG);
        topContainer.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, 1, 0, BossWiseDesign.BORDER_COLOR),
                BorderFactory.createEmptyBorder(6, 6, 6, 6)
        ));

        JLabel title = new JLabel("SLAYER ASSISTANT");
        title.setFont(BossWiseDesign.getHeaderFont());
        title.setForeground(BossWiseDesign.GOLD);
        topContainer.add(title);

        WrapText sub = new WrapText("Task locations, gear, XP rates & superiors", BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_MUTED);
        topContainer.add(sub);
        topContainer.add(Box.createRigidArea(new Dimension(0, 6)));

        // Task selector row
        List<String> tasks = slayerTaskService.getAllTaskNames();
        for (String t : tasks) {
            taskCombo.addItem(t);
        }
        taskCombo.setMaximumSize(new Dimension(BossWiseDesign.USABLE_WIDTH, 26));
        taskCombo.setFont(BossWiseDesign.getRegularFont());
        taskCombo.setBackground(BossWiseDesign.CARD_BG);
        taskCombo.setForeground(BossWiseDesign.TEXT_PRIMARY);
        taskCombo.addActionListener(e -> renderTaskDetails());
        topContainer.add(taskCombo);
        topContainer.add(Box.createRigidArea(new Dimension(0, 4)));

        // Remaining & Detect row
        JPanel countRow = new JPanel(new BorderLayout(4, 0));
        countRow.setOpaque(false);

        JPanel leftCount = new JPanel(new FlowLayout(FlowLayout.LEFT, 4, 0));
        leftCount.setOpaque(false);
        JLabel remLabel = new JLabel("Remaining:");
        remLabel.setFont(BossWiseDesign.getSmallFont());
        remLabel.setForeground(BossWiseDesign.TEXT_SECONDARY);
        leftCount.add(remLabel);

        remainingField.setFont(BossWiseDesign.getSmallFont());
        remainingField.setBackground(BossWiseDesign.CARD_BG);
        remainingField.setForeground(BossWiseDesign.GOLD);
        remainingField.setCaretColor(BossWiseDesign.GOLD);
        remainingField.addActionListener(e -> renderTaskDetails());
        leftCount.add(remainingField);
        countRow.add(leftCount, BorderLayout.WEST);

        GoldButton detectBtn = new GoldButton("Detect Task");
        detectBtn.setFont(BossWiseDesign.getBadgeFont());
        detectBtn.setPreferredSize(new Dimension(85, 22));
        detectBtn.addActionListener(e -> {
            String current = slayerTaskService.detectCurrentSlayerTask();
            int amount = slayerTaskService.detectRemainingKills();
            taskCombo.setSelectedItem(current);
            remainingField.setText(String.valueOf(amount));
            renderTaskDetails();
        });
        countRow.add(detectBtn, BorderLayout.EAST);

        topContainer.add(countRow);
        add(topContainer, BorderLayout.NORTH);

        JScrollPane scrollPane = new JScrollPane(contentPanel);
        scrollPane.setHorizontalScrollBarPolicy(JScrollPane.HORIZONTAL_SCROLLBAR_NEVER);
        scrollPane.setBorder(BorderFactory.createEmptyBorder());
        scrollPane.getVerticalScrollBar().setUnitIncrement(16);
        add(scrollPane, BorderLayout.CENTER);

        renderTaskDetails();
    }

    private void renderTaskDetails() {
        contentPanel.removeAll();

        String selectedTask = (String) taskCombo.getSelectedItem();
        if (selectedTask == null) selectedTask = "Gargoyles";

        SlayerTaskInfo task = slayerTaskService.getTask(selectedTask);
        if (task == null) {
            contentPanel.revalidate();
            contentPanel.repaint();
            return;
        }

        int remaining = 140;
        try {
            remaining = Integer.parseInt(remainingField.getText().trim());
        } catch (NumberFormatException ignored) {}

        int estMinutes = task.estimateTaskDurationMinutes(remaining);

        // 1. Task Summary Card
        JPanel summaryCard = new JPanel();
        summaryCard.setLayout(new BoxLayout(summaryCard, BoxLayout.Y_AXIS));
        summaryCard.setBackground(BossWiseDesign.CARD_BG);
        summaryCard.setBorder(BossWiseDesign.BORDER_GOLD);
        summaryCard.setAlignmentX(LEFT_ALIGNMENT);

        JLabel tName = new JLabel(task.getTaskName() + " (Level " + task.getSlayerLevelReq() + ")");
        tName.setFont(BossWiseDesign.getHeaderFont());
        tName.setForeground(BossWiseDesign.GOLD);
        summaryCard.add(tName);
        summaryCard.add(Box.createRigidArea(new Dimension(0, 4)));

        JLabel rates = new JLabel(String.format("XP: %dK/hr  |  Profit: %dK/hr",
                task.getEstimatedXpPerHour() / 1000, task.getEstimatedGpPerHour() / 1000));
        rates.setFont(BossWiseDesign.getBoldFont());
        rates.setForeground(BossWiseDesign.TEXT_PRIMARY);
        summaryCard.add(rates);

        WrapText duration = new WrapText(String.format("Estimated Time: %d mins (%d kills remaining)", estMinutes, remaining), BossWiseDesign.getSmallFont(), BossWiseDesign.STATUS_READY);
        summaryCard.add(duration);

        WrapText styleRec = new WrapText("Style: " + task.getRecommendedStyle().name() + "  |  Weapon: " + task.getRecommendedWeapon(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
        summaryCard.add(styleRec);

        contentPanel.add(summaryCard);
        contentPanel.add(Box.createRigidArea(new Dimension(0, 6)));

        // 2. Locations Comparison Card
        JPanel locCard = new JPanel();
        locCard.setLayout(new BoxLayout(locCard, BoxLayout.Y_AXIS));
        locCard.setBackground(BossWiseDesign.CARD_BG);
        locCard.setBorder(BossWiseDesign.BORDER_CARD_SLIM);
        locCard.setAlignmentX(LEFT_ALIGNMENT);

        JLabel lTitle = new JLabel("LOCATION COMPARISON");
        lTitle.setFont(BossWiseDesign.getBoldFont());
        lTitle.setForeground(BossWiseDesign.GOLD);
        locCard.add(lTitle);
        locCard.add(Box.createRigidArea(new Dimension(0, 4)));

        for (TaskLocation loc : task.getLocations()) {
            JPanel item = new JPanel();
            item.setLayout(new BoxLayout(item, BoxLayout.Y_AXIS));
            item.setOpaque(false);
            item.setBorder(BorderFactory.createMatteBorder(0, 0, 1, 0, BossWiseDesign.BORDER_SUBTLE));

            JLabel name = new JLabel(loc.getName());
            name.setFont(BossWiseDesign.getBoldFont());
            name.setForeground(BossWiseDesign.TEXT_PRIMARY);
            item.add(name);

            String badges = (loc.isCannonable() ? "[Cannon] " : "") +
                    (loc.isMultiCombat() ? "[Multi] " : "[Single] ") +
                    (loc.isPrayerRestoreBonus() ? "[Prayer Restore] " : "") +
                    (loc.isSlayerXpBonus() ? "[+10% XP] " : "");
            JLabel b = new JLabel(badges);
            b.setFont(BossWiseDesign.getSmallFont());
            b.setForeground(BossWiseDesign.STATUS_INFO);
            item.add(b);

            JLabel desc = new JLabel("<html><body style='width: 170px;'>" + loc.getDescription() + "</body></html>");
            desc.setFont(BossWiseDesign.getSmallFont());
            desc.setForeground(BossWiseDesign.TEXT_MUTED);
            item.add(desc);
            item.add(Box.createRigidArea(new Dimension(0, 4)));

            locCard.add(item);
        }
        contentPanel.add(locCard);
        contentPanel.add(Box.createRigidArea(new Dimension(0, 6)));

        // 3. Superior Slayer Monster Card
        JPanel supCard = new JPanel();
        supCard.setLayout(new BoxLayout(supCard, BoxLayout.Y_AXIS));
        supCard.setBackground(BossWiseDesign.CARD_BG);
        supCard.setBorder(BossWiseDesign.BORDER_CARD_SLIM);
        supCard.setAlignmentX(LEFT_ALIGNMENT);

        JLabel sTitle = new JLabel("SUPERIOR SLAYER VARIANT");
        sTitle.setFont(BossWiseDesign.getBoldFont());
        sTitle.setForeground(new Color(0x9C, 0x27, 0xB0)); // Purple
        supCard.add(sTitle);
        supCard.add(Box.createRigidArea(new Dimension(0, 4)));

        WrapText sName = new WrapText(task.getSuperiorVariantName(), BossWiseDesign.getBoldFont(), BossWiseDesign.TEXT_PRIMARY);
        supCard.add(sName);

        JLabel drops = new JLabel("<html><body style='width: 170px;'>Drops: " + task.getSuperiorUniqueDrops() + "</body></html>");
        drops.setFont(BossWiseDesign.getSmallFont());
        drops.setForeground(BossWiseDesign.STATUS_READY);
        supCard.add(drops);

        contentPanel.add(supCard);
        contentPanel.add(Box.createRigidArea(new Dimension(0, 6)));

        // 4. Strategy & Warning Card
        JPanel stratCard = new JPanel();
        stratCard.setLayout(new BoxLayout(stratCard, BoxLayout.Y_AXIS));
        stratCard.setBackground(BossWiseDesign.CARD_BG);
        stratCard.setBorder(BossWiseDesign.BORDER_CARD_SLIM);
        stratCard.setMaximumSize(new Dimension(BossWiseDesign.USABLE_WIDTH, 100));

        JLabel stTitle = new JLabel("TASK STRATEGY");
        stTitle.setFont(BossWiseDesign.getBoldFont());
        stTitle.setForeground(BossWiseDesign.GOLD);
        stratCard.add(stTitle);
        stratCard.add(Box.createRigidArea(new Dimension(0, 4)));

        JLabel notes = new JLabel("<html><body style='width: 170px;'>" + task.getStrategyNotes() + "</body></html>");
        notes.setFont(BossWiseDesign.getSmallFont());
        notes.setForeground(BossWiseDesign.TEXT_SECONDARY);
        stratCard.add(notes);

        contentPanel.add(stratCard);

        contentPanel.revalidate();
        contentPanel.repaint();
    }
}

package com.bosswise.ui.components;

import com.bosswise.model.BossData;
import com.bosswise.model.BossEligibility;
import com.bosswise.service.GearOptimizerService;
import com.bosswise.ui.BossWiseDesign;
import java.awt.BorderLayout;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.GridLayout;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.BoxLayout;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class BossCard extends JPanel {
    private final BossData boss;
    private final BossEligibility eligibility;
    private boolean hovered = false;

    public BossCard(
            BossData boss,
            BossEligibility eligibility,
            Consumer<BossData> onGearClick,
            Consumer<BossData> onGuideClick) {
        this.boss = boss;
        this.eligibility = eligibility;

        setLayout(new BorderLayout(6, 6));
        setAlignmentX(LEFT_ALIGNMENT);
        setBackground(BossWiseDesign.CARD_BG);
        setBorder(BorderFactory.createEmptyBorder(6, 8, 6, 8));
        setOpaque(false);

        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                hovered = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hovered = false;
                repaint();
            }
        });

        // Top Row: Title + Status Badge
        JPanel topRow = new JPanel(new BorderLayout(4, 0));
        topRow.setOpaque(false);

        WrapText titleLabel = new WrapText(boss.getName(), BossWiseDesign.getHeaderFont(), BossWiseDesign.TEXT_PRIMARY);
        titleLabel.setToolTipText(boss.getName());
        topRow.add(titleLabel, BorderLayout.CENTER);

        StatusBadge statusBadge = new StatusBadge(eligibility.getStatus());
        topRow.add(statusBadge, BorderLayout.EAST);

        add(topRow, BorderLayout.NORTH);

        // Center Content: Metadata & Score
        JPanel centerPanel = new JPanel();
        centerPanel.setLayout(new BoxLayout(centerPanel, BoxLayout.Y_AXIS));
        centerPanel.setOpaque(false);

        // Tag row: Difficulty + Combat Style + Rec CB (wraps gracefully if needed)
        JPanel tagRow = new JPanel(new WrapLayout(WrapLayout.LEFT, 3, 2));
        tagRow.setOpaque(false);

        tagRow.add(createTag(boss.getDifficulty().getDisplayName(), boss.getDifficulty().getBadgeColor()));
        tagRow.add(createTag(boss.getPrimaryStyle().getDisplayName(), BossWiseDesign.TEXT_SECONDARY));
        tagRow.add(createTag("Cb " + boss.getRecommendedCombatLevel() + "+", BossWiseDesign.TEXT_MUTED));

        centerPanel.add(tagRow);
        centerPanel.add(Box.createRigidArea(new Dimension(0, 3)));

        // Economics & Suitability Score Row
        JPanel econRow = new JPanel(new BorderLayout(4, 0));
        econRow.setOpaque(false);
        econRow.setBorder(BorderFactory.createEmptyBorder(1, 2, 1, 2));

        String gpStr = "~" + GearOptimizerService.formatGp(boss.getEstimatedGpHour()) + "/hr";
        JLabel gpLabel = new JLabel(gpStr);
        gpLabel.setFont(BossWiseDesign.getBoldFont());
        gpLabel.setForeground(BossWiseDesign.GOLD);
        econRow.add(gpLabel, BorderLayout.WEST);

        JLabel scoreLabel = new JLabel("Match: " + eligibility.getRecommendationScore() + "%");
        scoreLabel.setFont(BossWiseDesign.getBoldFont());
        scoreLabel.setForeground(eligibility.isReady() ? BossWiseDesign.STATUS_READY : (eligibility.isAlmostReady() ? BossWiseDesign.STATUS_ALMOST : BossWiseDesign.STATUS_LOCKED));
        econRow.add(scoreLabel, BorderLayout.EAST);

        centerPanel.add(econRow);

        // Missing requirements warning if not READY
        if (!eligibility.isReady() && !eligibility.getMissingRequirements().isEmpty()) {
            VerticalPanel missingPanel = new VerticalPanel();
            missingPanel.setOpaque(false);
            missingPanel.setBorder(BorderFactory.createEmptyBorder(3, 2, 3, 2));

            WrapText missingHeader = new WrapText("Requirements needed:", BossWiseDesign.getSmallFont(), BossWiseDesign.STATUS_LOCKED);
            missingPanel.add(missingHeader);

            int shown = 0;
            for (String req : eligibility.getMissingRequirements()) {
                if (shown++ >= 2) {
                    JLabel moreLabel = new JLabel("+ " + (eligibility.getMissingRequirements().size() - 2) + " more...");
                    moreLabel.setFont(BossWiseDesign.getSmallFont());
                    moreLabel.setForeground(BossWiseDesign.TEXT_MUTED);
                    missingPanel.add(moreLabel);
                    break;
                }
                WrapText reqLabel = new WrapText("• " + req, BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
                missingPanel.add(reqLabel);
            }
            centerPanel.add(missingPanel);
        }

        add(centerPanel, BorderLayout.CENTER);

        // Bottom Actions: "Gear" and "Guide"
        JPanel bottomRow = new JPanel(new GridLayout(1, 2, 4, 0));
        bottomRow.setOpaque(false);
        bottomRow.setBorder(BorderFactory.createEmptyBorder(4, 0, 0, 0));

        GoldButton gearBtn = new GoldButton("Gear");
        gearBtn.setFont(BossWiseDesign.getBoldFont());
        gearBtn.setToolTipText("Optimize Gear Setup for " + boss.getName());
        gearBtn.addActionListener(e -> {
            if (onGearClick != null) onGearClick.accept(boss);
        });
        bottomRow.add(gearBtn);

        GoldButton guideBtn = new GoldButton("Guide");
        guideBtn.setFont(BossWiseDesign.getBoldFont());
        guideBtn.setToolTipText("Open Strategy Guide for " + boss.getName());
        guideBtn.addActionListener(e -> {
            if (onGuideClick != null) onGuideClick.accept(boss);
        });
        bottomRow.add(guideBtn);

        add(bottomRow, BorderLayout.SOUTH);
    }

    private JPanel createTag(String text, Color textColor) {
        JPanel tag = new JPanel(new FlowLayout(FlowLayout.CENTER, 6, 2));
        tag.setBackground(BossWiseDesign.PANEL_BG);
        tag.setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createLineBorder(BossWiseDesign.BORDER_SUBTLE, 1),
                BorderFactory.createEmptyBorder(1, 4, 1, 4)
        ));
        JLabel lbl = new JLabel(text);
        lbl.setFont(BossWiseDesign.getSmallFont());
        lbl.setForeground(textColor);
        tag.add(lbl);
        return tag;
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);

        int w = getWidth();
        int h = getHeight();

        // Background card
        g2.setColor(hovered ? BossWiseDesign.CARD_HOVER : BossWiseDesign.CARD_BG);
        g2.fillRoundRect(0, 0, w - 1, h - 1, 10, 10);

        // Border
        g2.setColor(hovered ? BossWiseDesign.GOLD : BossWiseDesign.BORDER_COLOR);
        g2.drawRoundRect(0, 0, w - 1, h - 1, 10, 10);

        g2.dispose();
        super.paintComponent(g);
    }
}

package com.bosswise.ui.components;

import com.bosswise.model.EquipmentItem;
import com.bosswise.model.EquipmentSlot;
import com.bosswise.service.GearOptimizerService;
import com.bosswise.ui.BossWiseDesign;
import java.awt.BorderLayout;
import java.awt.Dimension;
import java.util.List;
import java.util.function.Consumer;
import javax.swing.BorderFactory;
import javax.swing.Box;
import javax.swing.JLabel;
import javax.swing.JPanel;

public class EquipmentSlotRow extends VerticalPanel {
    private final EquipmentSlot slot;
    private final EquipmentItem item;
    private final long price;
    private final String reason;

    public EquipmentSlotRow(EquipmentSlot slot, EquipmentItem item, long price, String reason, Consumer<EquipmentSlot> onUpgradeClick) {
        this(slot, item, price, reason, null, onUpgradeClick);
    }

    public EquipmentSlotRow(EquipmentSlot slot, EquipmentItem item, long price, String reason, List<String> missingRequirements, Consumer<EquipmentSlot> onUpgradeClick) {
        this.slot = slot;
        this.item = item;
        this.price = price;
        this.reason = reason;

        setBackground(BossWiseDesign.CARD_BG);
        setOpaque(true);
        setBorder(BorderFactory.createCompoundBorder(
                BorderFactory.createMatteBorder(0, 0, 1, 0, BossWiseDesign.BORDER_SUBTLE),
                BorderFactory.createEmptyBorder(5, 7, 5, 7)
        ));

        // Line 1: Slot name (Left) and Price (Right)
        JPanel line1 = new JPanel(new BorderLayout(4, 0)) {
            @Override
            public Dimension getMaximumSize() {
                return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
            }
        };
        line1.setOpaque(false);
        line1.setAlignmentX(LEFT_ALIGNMENT);

        JLabel slotLabel = new JLabel(slot.getDisplayName().toUpperCase());
        slotLabel.setFont(BossWiseDesign.getBadgeFont());
        slotLabel.setForeground(BossWiseDesign.GOLD);
        line1.add(slotLabel, BorderLayout.WEST);

        String priceStr;
        if (item == null) {
            priceStr = "-";
        } else if (item.isUntradeable()) {
            priceStr = "Free / Quest";
        } else {
            priceStr = GearOptimizerService.formatGp(price) + " GP";
        }

        JLabel priceLabel = new JLabel(priceStr);
        priceLabel.setFont(BossWiseDesign.getBadgeFont());
        priceLabel.setForeground(item != null && item.isUntradeable() ? BossWiseDesign.STATUS_READY : BossWiseDesign.GOLD);
        line1.add(priceLabel, BorderLayout.EAST);
        add(line1);
        add(Box.createVerticalStrut(2));

        // Line 2: Item Name (snug, wrapping, never clipped)
        String itemName = (item != null) ? item.getName() : "None / Empty";
        WrapText nameText = new WrapText(itemName, BossWiseDesign.getBoldFont(), (item != null) ? BossWiseDesign.TEXT_PRIMARY : BossWiseDesign.TEXT_MUTED);
        nameText.setToolTipText(itemName);
        add(nameText);

        // Missing Requirements (if any)
        if (missingRequirements != null && !missingRequirements.isEmpty()) {
            add(Box.createVerticalStrut(2));
            for (String req : missingRequirements) {
                WrapText reqText = new WrapText("⚠ " + req, BossWiseDesign.getSmallFont(), BossWiseDesign.STATUS_LOCKED);
                add(reqText);
            }
        }

        // Line 3: Reason / Stats if present (snug, wrapping, never clipped)
        if (reason != null && !reason.trim().isEmpty()) {
            add(Box.createVerticalStrut(2));
            WrapText reasonText = new WrapText(reason.trim(), BossWiseDesign.getSmallFont(), BossWiseDesign.TEXT_SECONDARY);
            add(reasonText);
        }
    }
}

package com.bosswise.ui.components;

import com.bosswise.ui.BossWiseDesign;
import java.awt.BasicStroke;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.JButton;

public class GoldButton extends JButton {
    private boolean hover = false;
    private boolean pressed = false;
    private boolean active = false;

    public GoldButton(String text) {
        super(text);
        setFont(BossWiseDesign.getBoldFont());
        setForeground(BossWiseDesign.GOLD);
        setContentAreaFilled(false);
        setFocusPainted(false);
        setBorderPainted(false);
        setMargin(new java.awt.Insets(1, 2, 1, 2));
        setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
        setPreferredSize(new Dimension(90, 28));

        addMouseListener(new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent e) {
                hover = true;
                repaint();
            }

            @Override
            public void mouseExited(MouseEvent e) {
                hover = false;
                repaint();
            }

            @Override
            public void mousePressed(MouseEvent e) {
                pressed = true;
                repaint();
            }

            @Override
            public void mouseReleased(MouseEvent e) {
                pressed = false;
                repaint();
            }
        });
    }

    public void setActive(boolean active) {
        this.active = active;
        if (active) {
            setForeground(BossWiseDesign.TEXT_PRIMARY);
        } else {
            setForeground(BossWiseDesign.GOLD);
        }
        repaint();
    }

    public boolean isActive() {
        return active;
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        int w = getWidth();
        int h = getHeight();

        // Background
        if (active) {
            g2.setColor(BossWiseDesign.GOLD_BG);
        } else if (pressed) {
            g2.setColor(BossWiseDesign.CARD_BG);
        } else if (hover) {
            g2.setColor(BossWiseDesign.CARD_HOVER);
        } else {
            g2.setColor(BossWiseDesign.PANEL_BG);
        }
        g2.fillRoundRect(0, 0, w - 1, h - 1, 8, 8);

        // Border
        if (active) {
            g2.setColor(BossWiseDesign.GOLD);
            g2.setStroke(new BasicStroke(1.5f));
        } else if (hover) {
            g2.setColor(BossWiseDesign.GOLD_HOVER);
            g2.setStroke(new BasicStroke(1.2f));
        } else {
            g2.setColor(BossWiseDesign.BORDER_COLOR);
            g2.setStroke(new BasicStroke(1.0f));
        }
        g2.drawRoundRect(0, 0, w - 1, h - 1, 8, 8);

        g2.dispose();
        super.paintComponent(g);
    }
}

package com.bosswise.ui.components;

import java.awt.Dimension;
import java.awt.LayoutManager;
import java.awt.Rectangle;
import javax.swing.JPanel;
import javax.swing.Scrollable;

/**
 * A JPanel that implements {@link Scrollable} and forces its width to track
 * the viewport width of its enclosing {@link javax.swing.JScrollPane}.
 * This prevents horizontal scrolling and ensures child components never clip horizontally.
 */
public class ScrollablePanel extends JPanel implements Scrollable {

    public ScrollablePanel() {
        super();
    }

    public ScrollablePanel(LayoutManager layout) {
        super(layout);
    }

    private boolean leftAlignChildren = false;

    /**
     * When enabled, every child added is forced to LEFT alignment so BoxLayout never offsets
     * cards to the right because of mixed alignmentX values.
     */
    public void setLeftAlignChildren(boolean leftAlignChildren) {
        this.leftAlignChildren = leftAlignChildren;
    }

    @Override
    protected void addImpl(java.awt.Component comp, Object constraints, int index) {
        if (leftAlignChildren && comp instanceof javax.swing.JComponent) {
            ((javax.swing.JComponent) comp).setAlignmentX(LEFT_ALIGNMENT);
        }
        super.addImpl(comp, constraints, index);
    }

    @Override
    public Dimension getPreferredScrollableViewportSize() {
        return getPreferredSize();
    }

    @Override
    public int getScrollableUnitIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 16;
    }

    @Override
    public int getScrollableBlockIncrement(Rectangle visibleRect, int orientation, int direction) {
        return 32;
    }

    @Override
    public boolean getScrollableTracksViewportWidth() {
        // Crucial: forces panel width to strictly follow the scrollpane viewport width
        return true;
    }

    @Override
    public boolean getScrollableTracksViewportHeight() {
        return false;
    }
}

package com.bosswise.ui.components;

import com.bosswise.ui.BossWiseDesign;
import java.awt.Color;
import java.awt.Dimension;
import java.awt.Graphics;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import javax.swing.JComponent;

public class StatProgressBar extends JComponent {
    private int current;
    private int target;
    private Color fillColor = BossWiseDesign.GOLD;

    public StatProgressBar(int current, int target) {
        this.current = current;
        this.target = Math.max(1, target);
        setPreferredSize(new Dimension(140, 20));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 22));
        setAlignmentX(LEFT_ALIGNMENT);
    }

    public void setValues(int current, int target) {
        this.current = current;
        this.target = Math.max(1, target);
        repaint();
    }

    public void setFillColor(Color color) {
        this.fillColor = color;
        repaint();
    }

    @Override
    protected void paintComponent(Graphics g) {
        Graphics2D g2 = (Graphics2D) g.create();
        g2.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
        g2.setRenderingHint(RenderingHints.KEY_TEXT_ANTIALIASING, RenderingHints.VALUE_TEXT_ANTIALIAS_ON);

        int w = getWidth();
        int h = getHeight();

        // Track background
        g2.setColor(BossWiseDesign.BORDER_COLOR);
        g2.fillRoundRect(0, 0, w - 1, h - 1, 10, 10);

        // Fill bar
        double pct = Math.min(1.0, Math.max(0.0, (double) current / target));
        int fillW = (int) Math.round((w - 1) * pct);

        if (fillW > 0) {
            g2.setColor(fillColor);
            g2.fillRoundRect(0, 0, fillW, h - 1, 10, 10);
        }

        // Outer border
        g2.setColor(BossWiseDesign.BORDER_SUBTLE);
        g2.drawRoundRect(0, 0, w - 1, h - 1, 10, 10);

        // Text centered
        g2.setFont(BossWiseDesign.getBadgeFont());
        g2.setColor(new Color(0xFF, 0xFD, 0xF5));
        String label = current + " / " + target + " (" + (int)(pct * 100) + "%)";
        int textW = g2.getFontMetrics().stringWidth(label);
        int textX = (w - textW) / 2;
        int textY = ((h - g2.getFontMetrics().getHeight()) / 2) + g2.getFontMetrics().getAscent();
        g2.drawString(label, textX, textY);

        g2.dispose();
    }
}

