package com.bosswise.ui.components;

import java.awt.Component;
import java.awt.Dimension;
import javax.swing.BoxLayout;
import javax.swing.JComponent;
import javax.swing.JPanel;

/**
 * Vertical BoxLayout stack whose children are all left-aligned and stretched to full width.
 *
 * <p>BoxLayout misplaces children when their alignmentX values differ (JLabel defaults to
 * LEFT, JPanel/Box fillers to CENTER): left-aligned children start at the centre line and
 * run off the right edge. Forcing a single alignment removes that offset. Height is capped
 * at the preferred height so the stack never stretches vertically.</p>
 */
public class VerticalPanel extends ScrollablePanel {
    public VerticalPanel() {
        super();
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setLeftAlignChildren(true);
        setAlignmentX(LEFT_ALIGNMENT);
    }

    @Override
    protected void addImpl(Component comp, Object constraints, int index) {
        if (comp instanceof JComponent) {
            ((JComponent) comp).setAlignmentX(LEFT_ALIGNMENT);
        }
        super.addImpl(comp, constraints, index);
    }

    @Override
    public Dimension getMinimumSize() {
        return new Dimension(0, super.getMinimumSize().height);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }
}

package com.bosswise.ui.components;

import java.awt.Component;
import java.awt.Container;
import java.awt.Dimension;
import java.awt.FlowLayout;
import java.awt.Insets;

/**
 * A FlowLayout that calculates preferred size by wrapping components to fit
 * within the target container's available width rather than expanding horizontally.
 */
public class WrapLayout extends FlowLayout {

    public WrapLayout() {
        super();
    }

    public WrapLayout(int align) {
        super(align);
    }

    public WrapLayout(int align, int hgap, int vgap) {
        super(align, hgap, vgap);
    }

    @Override
    public Dimension preferredLayoutSize(Container target) {
        return layoutSize(target, true);
    }

    @Override
    public Dimension minimumLayoutSize(Container target) {
        return layoutSize(target, false);
    }

    private Dimension layoutSize(Container target, boolean preferred) {
        synchronized (target.getTreeLock()) {
            int targetWidth = target.getWidth();
            if (targetWidth <= 0) {
                Container p = target.getParent();
                while (p != null && targetWidth <= 0) {
                    targetWidth = p.getWidth();
                    p = p.getParent();
                }
                if (targetWidth <= 0) {
                    targetWidth = com.bosswise.ui.BossWiseDesign.BODY_TEXT_WIDTH;
                }
            }

            Insets insets = target.getInsets();
            int maxRowWidth = targetWidth - (insets.left + insets.right + getHgap() * 2);
            if (maxRowWidth <= 0) {
                maxRowWidth = com.bosswise.ui.BossWiseDesign.BODY_TEXT_WIDTH;
            }

            int rowWidth = 0;
            int rowHeight = 0;
            int totalHeight = 0;
            int maxActualWidth = 0;
            boolean firstInRow = true;

            int n = target.getComponentCount();
            for (int i = 0; i < n; i++) {
                Component m = target.getComponent(i);
                if (m.isVisible()) {
                    Dimension d = preferred ? m.getPreferredSize() : m.getMinimumSize();
                    if (!firstInRow && rowWidth + d.width + getHgap() > maxRowWidth) {
                        totalHeight += rowHeight + getVgap();
                        maxActualWidth = Math.max(maxActualWidth, rowWidth);
                        rowWidth = d.width;
                        rowHeight = d.height;
                    } else {
                        if (!firstInRow) {
                            rowWidth += getHgap();
                        }
                        rowWidth += d.width;
                        rowHeight = Math.max(rowHeight, d.height);
                    }
                    firstInRow = false;
                }
            }
            totalHeight += rowHeight;
            maxActualWidth = Math.max(maxActualWidth, rowWidth);

            return new Dimension(
                    maxActualWidth + insets.left + insets.right + getHgap() * 2,
                    totalHeight + insets.top + insets.bottom + getVgap() * 2
            );
        }
    }
}

package com.bosswise.ui.components;

import com.bosswise.ui.BossWiseDesign;
import java.awt.Color;
import java.awt.Container;
import java.awt.Cursor;
import java.awt.Dimension;
import java.awt.Font;
import java.awt.Insets;
import javax.swing.BorderFactory;
import javax.swing.JTextArea;
import javax.swing.SwingUtilities;
import javax.swing.text.View;

/**
 * Read-only multi-line text that always wraps to the width its parent gives it.
 *
 * <p>Unlike an HTML JLabel with a fixed CSS width, this never asks for more horizontal space
 * than is available: its preferred width is tiny (so parent layout managers can shrink it),
 * and its preferred height is accurately computed by accumulating all ancestor container insets
 * so words wrap cleanly and are never clipped.</p>
 */
public class WrapText extends JTextArea {
    private static final int MIN_PREF_WIDTH = 10;

    public WrapText(String text, Font font, Color color) {
        super(text == null ? "" : text);
        setFont(font);
        setForeground(color);
        setLineWrap(true);
        setWrapStyleWord(true);
        setEditable(false);
        setFocusable(false);
        setHighlighter(null);
        setOpaque(false);
        setBackground(new Color(0, 0, 0, 0));
        setBorder(BorderFactory.createEmptyBorder());
        setMargin(new Insets(0, 0, 0, 0));
        setCursor(Cursor.getDefaultCursor());
        setAlignmentX(LEFT_ALIGNMENT);
    }

    /**
     * Width currently available for text, accurately accumulating all ancestor insets
     * until finding the enclosing viewport/window.
     */
    private int availableWidth() {
        int w = getWidth();
        if (w > 0) {
            Insets in = getInsets();
            return Math.max(1, w - (in != null ? in.left + in.right : 0));
        }

        int totalHorizontalInsets = 0;
        Insets in = getInsets();
        if (in != null) {
            totalHorizontalInsets += in.left + in.right;
        }

        Container current = getParent();
        while (current != null && current.getWidth() <= 0) {
            Insets ci = current.getInsets();
            if (ci != null) {
                totalHorizontalInsets += ci.left + ci.right;
            }
            current = current.getParent();
        }

        if (current != null && current.getWidth() > 0) {
            Insets ci = current.getInsets();
            if (ci != null) {
                totalHorizontalInsets += ci.left + ci.right;
            }
            w = current.getWidth() - totalHorizontalInsets;
            if (w > 20) {
                return w;
            }
        }
        return BossWiseDesign.BODY_TEXT_WIDTH;
    }

    @Override
    public Dimension getPreferredSize() {
        if (isPreferredSizeSet()) {
            return super.getPreferredSize();
        }
        Insets in = getInsets();
        int insetsH = in != null ? in.left + in.right : 0;
        int insetsV = in != null ? in.top + in.bottom : 0;
        int textWidth = Math.max(1, availableWidth() - insetsH);

        try {
            View root = getUI() != null ? getUI().getRootView(this) : null;
            if (root != null) {
                root.setSize(textWidth, Integer.MAX_VALUE);
                int h = (int) Math.ceil(root.getPreferredSpan(View.Y_AXIS));
                return new Dimension(MIN_PREF_WIDTH, Math.max(14, h + insetsV));
            }
        } catch (Exception ignored) {}

        return super.getPreferredSize();
    }

    @Override
    public Dimension getMinimumSize() {
        return new Dimension(0, getPreferredSize().height);
    }

    @Override
    public Dimension getMaximumSize() {
        return new Dimension(Integer.MAX_VALUE, getPreferredSize().height);
    }

    @Override
    public void setBounds(int x, int y, int width, int height) {
        int oldWidth = getWidth();
        super.setBounds(x, y, width, height);
        if (width != oldWidth && width > 0) {
            // Height depends on width: re-run layout once the new width is known.
            SwingUtilities.invokeLater(this::revalidate);
        }
    }
}

